// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":35,"question":"سائل يقول: فضيلة الشيخ عبد العزيز، نفعنا الله بعلمك: لي أب يعمل في شركة (أرامكو) منذ ثلاثة وثلاثين عامًا، ومنذ بدايته وهو يضع نقوده في بنك الضمان الاجتماعي في الشركة، والآن انتهى من العمل، وسوف يعطونه أمواله وزيادة، أو مضاعفة، فماذا يعمل في هذه النقود؟ وهل هي ربا؟ وماذا أفعل لو أخذها، أفدنا أطال الله بقاءك؟","title":"ماذا يُعمل بأرباح البنك؟ وهل هي ربا؟","answer":"الجواب: هذا صدر فيه فتوى منا باللجنة الدائمة: أن النقود التي توضع في الشركات التي تشترط من العامل إذا دفع نقودًا من راتبه كل شهر أنه بعد خمس سنوات يعطي كذا، وبعد عشر سنوات يعطي كذا، (6%) أو (50%) أو (100%) فإن هذه الزيادة ربا؛ لأنها تنتفع بوقت أمواله، وتنميها، وترابي فيها، وتعطيهم ذلك، وهذا شيء اطلعنا عليه في بعض بنود الشركات، وأنها بعد مرور خمس سنوات تعطيك (50%) مثلًا أو أقل أو أكثر، وإذا مضى عليه عشر سنوات أعطته (100%) في مقابل ما دفعه من أقساط، وهذا ربا.\nوالذي يظهر لنا أن الواجب عليه الصدقة بها، أو صرفها في مشاريع خيرية؛ لا يأكلها لأنها ربا، فيأخذ ماله الذي جمع، وحصل له من الأقساط التي قدمها لهم.\nوأما الربا الذي أعطوه زيادة: فهذه تصرف في وجوه البر وأعمال الخير، وبناء الطرق والمدارس، ودورات المياه، ومواساة الفقراء وقضاء دين المدينين، وإعطاء المجاهدين والمبتلين بالفقر في أي مكان.\nهذا هو الذي يجب؛ لأنه مال جاءه من غير حله، فلا يُحرق ولا يُتلف؛ ولكن يُصرف في مصارف الأموال الضائعة والأموال التي ليس لها أحد.","link":"https://binbaz.org.sa/fatwas/2815/ماذا-يعمل-بارباح-البنك-وهل-هي-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0008.mp3","categories":["الربا والصرف"]},{"id":135,"question":"سؤال عن تبديل الأوراق المالية أو العملة الورقية بالعملة المعدنية، هل يجوز التَّفاضل فيه؟","title":"حكم التفاضل بين العملية الورقية والمعدنية","answer":"الجواب: ترك التفاضل أوْلى وأحوط، فكونه يأخذ عشرة بعشرة ومئة بمئة أحوط، وبعض أهل العلم جوَّز التفاضل؛ لأنهما مختلفتان، هذه من معدن، وهذه من ورق، ولكن الأحوط للمؤمن ترك ذلك؛ لأنها ريـال، كلها ريـال، كلها عملة واحدة، فإذا ترك التَّفاضل فهو أحوط.","link":"https://binbaz.org.sa/fatwas/3667/حكم-التفاضل-بين-العملية-الورقية-والمعدنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0124.mp3","categories":["الربا والصرف"]},{"id":144,"question":"توجد شركة تبيع للناس بطاقات، قيمة البطاقة مئة وخمسون أو أكثر، ويحصل لحامل هذه البطاقة خصمٌ في بعض المُستشفيات والمحطات وكثير من المحلات التّجارية التي تتفق مع هذه الشركة؟","title":"حكم بيع بطاقات التخفيضات","answer":"الجواب: هذه ذكرناها في اللجنة، وكتبنا عنها أنها لا تجوز، وصلت إلينا وكتبنا عنها مدةً طويلةً أنا واللجنة الدائمة بإنكارها؛ لأنها من الربا، يُسلّمهم مئةً وخمسين وقد يستفيد مئات في مُقابلها.","link":"https://binbaz.org.sa/fatwas/3681/حكم-بيع-بطاقات-التخفيضات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0137.mp3","categories":["البيوع","الربا والصرف"]},{"id":205,"question":"في معارض بيع السيارات يلجأ صاحبُ المعرض إلى أخذ عربون من المُشتري الذي وقف عليه بسعر السيارة، فإذا ما عدل عن شراء السيارة فإنَّ صاحب المعرض يأكل العربون، فما حكم ذلك؟","title":"ما حكم \"العربون\" بين البائع والمشتري؟","answer":"الجواب: هذا فيه تفصيل: إذا تمَّ الاتفاقُ بينه وبين صاحب السيارة على ثمنٍ وقال له: العربون ألف ريـال، وأمهلني ثلاثة أيام أو أربعة أيام أو خمسة أيام حتى أُشاور وأنظر، فإن جئتُك وأخذتُها؛ سلَّمتُ باقي الثمن، وإلا فالعربون لك، هذا فيه خلافٌ بين أهل العلم، والصواب أنه يصحُّ، ويكون له العربون؛ لأنه عطله. أما من دون ذلك فلا يصحُّ العربون، فهو من الثمن، شرى وإلا يرده عليه، إلا إذا اتفقا على هذا؛ إذا اتفقا وقال: أمهلني أيامًا أنظر في أمري وأستخير الله، فإن جئتُك واشتريتُ فهو من الثمن، وإلا فهو لك؛ فلا بأس، المسلمون على شروطهم.","link":"https://binbaz.org.sa/fatwas/3969/ما-حكم-العربون-بين-الباىع-والمشتري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0212.mp3","categories":["الربا والصرف","البيوع"]},{"id":289,"question":"دار المال الإسلامي تُعطي أرباحًا شهريةً غير محددةٍ مقابل الأموال التي تُودع فيها من المواطنين، هل تلك الأرباح حلالٌ أم حرامٌ؟","title":"ما كيفية المضاربة الجائزة شرعًا والممنوعة؟","answer":"الجواب: هذا فيه تفصيل: فإن كان الأرباح حصلت عن بيعٍ وشراءٍ ومضاربةٍ، وحصل ربحٌ، فأعطته إياه على الشرط الذي بينهم: بالنصف، أو بالثلث؛ فلا بأس. وإن كانت أرباحه معينةً: في كل شهرٍ لك كذا ريـال، ريالين، 5% ، 10%، فهذا ربًا لا يجوز. أما إذا كان لا، تأخذ منهم أموالًا وتجعلها في سيارات، في أوانٍ، في أشياء أخرى تبيعها، حاجات تبيعها، وتُعطي حظّه من الربح بينهما أنصافًا، أو أثلاثًا، أو أرباعًا، تأخذ حقَّها وتُعطيه حقَّه من الربح؛ فهذا لا بأس به، مثل: المُضاربات، مثلما تُعطي أخاك مثلًا عشرة آلاف ريـال، وتحطّها فيما ترى من السلع، تقول: بعها والفائدة بيننا، فهذا لا بأس به، هذه جائزة بإجماع المسلمين، وهذا الواقع في العصور الأول: في عهد النبي ﷺ وقبله وبعده، هذا يُسمَّى: المُضاربة، وهي المُشاركة، فإذا صار الذي تسلم له المال بهذه الصِّفة بأن تأخذ الأموال وتجعلها في السلع، تبيعها بالربح، تبيع بين صاحب المال وبين الدار بالنصف أو بالثلث؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/4288/ما-كيفية-المضاربة-الجاىزة-شرعا-والممنوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0337.mp3","categories":["الربا والصرف","البيوع"]},{"id":291,"question":"ما حكم العمل في البنك بسبب الحاجة؟","title":"حكم العمل بالبنوك للحاجة والضرورة","answer":"الجواب: البنوك لا يجوز العمل فيها، بنوك الربا لا يجوز العمل فيها؛ لأنها تعاونٌ على الإثم والعدوان، فلا يجوز التَّعامل بها، الرسول لعن آكل الربا ومُوكله وكاتبه وشاهديه، وقال: هم سواء، فالكاتب للربا والشَّاهد عليه شريكٌ، والذي يُعينهم يكون محاسبًا أو يكون مُراسلًا أو يكون فرَّاشًا فيه إعانة لهم على بلائهم.\nس: والذي يُودع؟\nالشيخ: ما ينبغي الإيداع، لكن إذا دعت الضَّرورة لا بأس، الضَّرورة أن يُودع خوفًا على ماله، ليس عنده مكانٌ آخر يُودع بدون فائدةٍ.","link":"https://binbaz.org.sa/fatwas/4290/حكم-العمل-بالبنوك-للحاجة-والضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0339.mp3","categories":["الربا والصرف","البيوع"]},{"id":379,"question":"عندي محل لبيع الأجهزة الكهربائية، وكنتُ أبيع الجهاز نقدًا بمئة جنيه مصري، وأبيع الجهاز بالتقسيط على سنة بمئة وخمسين جنيهًا، فهل البيع بالتَّقسيط حلالٌ أم حرامٌ؟ وهل يُعتبر البيع بالتقسيط مثل نظام البنوك أم لا؟ مع الرجاء توضيح الفرق.","title":"حكم البيع بالتقسيط إلى أجل مسمى","answer":"الجواب: البيع إلى أجلٍ جائزٌ في الشرع بنصِّ الكتاب والسنة، وبعضهم حكاه إجماعًا، والله جلَّ وعلا بيَّن هذا في كتابه العظيم حيث قال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282]، فالمُداينة إلى أجلٍ مُسَمًّى أو إلى آجالٍ مُسَمَّاة لا بأس بها، بشرط أن يكون المبيعُ مملوكًا للبائع، وتحت قبضته وقدرته، فإذا كان تحت قبضته وقُدرته فباعه إلى أجلٍ أو إلى آجالٍ -وهي الأقساط- فلا بأس، كأن يبيع أرضه المملوكة له، أو سيارته التي في حوزته، أو بناء عنده، أو أوانٍ، أو ملابس، كلها في حوزته وتحت قدرته، يبيعها إلى أجلٍ مُسمًّى: إلى دخول رمضان من عام 1408، أو إلى أقساط، كل قسط يُسلم في أول رمضان من عام ثمانٍ، ومن عام تسع، ومن عام عشر، ومقدار القسط كذا وكذا ألف ريـال، أو مئة ريـال، فإذا كانت الأقساط معلومةً، والآجال معلومةً، والثمن مباحًا، والسلعة مملوكةً وفي قبضة البائع، والشروط الشرعية متوفرة؛ فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/4700/حكم-البيع-بالتقسيط-الى-اجل-مسمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0435.mp3","categories":["الربا والصرف","البيوع"]},{"id":421,"question":"بعض الأسواق التّجارية تضع جوائز على بعض المُنتجات الغذائية: كالحليب وغيره، هل يجوز للمسلم أن يشتري لكي يحصل على الجائزة؟ وما حكم مَن اشترى وحصلت له جائزةٌ وليس قصده أن يشتري لكي يكسب، وإنما جاءت الجائزة صدفةً؟ هل هي جائزة أم لا؟","title":"حكم شراء بعض السلع للفوز بجائزة عليها","answer":"الجواب: إذا كانت الجائزة بالقمار: مَن صادفه رقم كذا أو رقم كذا يحصل له كذا، هذا ما يجوز؛ لأنَّ هذا من القمار، من الميسر. أما إذا كانت الجائزة معلومةً، يقولون: مَن اشترى منا أربع مرات نُعطيه كذا، نعطيه..... وزيادة، نُعطيه سلعة كذا، معروفة، ما فيها شُبهة؛ هذا لا بأس به، هذا معناه ترغيب في الشراء منهم، أو: مَن اشترى منا عاملنا ننزل له ريالًا في السلعة، أو ريالين في السلعة، هذه ما فيها بأس؛ لأنها معلومة، ما في غرر ولا ميسر. أما إذا كانوا يحطّون أرقامًا: مَن صادف رقم كذا يُعطى راديو، ومَن صادف رقم كذا يُعطى سيارة، ومَن صادف رقم كذا يُعطى ثلاجة؛ هذا من الميسر، من الربا، ما يجوز.","link":"https://binbaz.org.sa/fatwas/4845/حكم-شراء-بعض-السلع-للفوز-بجاىزة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0479.mp3","categories":["الربا والصرف","البيوع"]},{"id":442,"question":"المشتري إذا كانت السلعة بالدولار فنقص في السوق فيتضرر البائع بذلك، هل نقول القول إذا رد... حتى يمينه مقبولة...، مثلًا اشترى منه \"دولار\" فنقص في السوق؟","title":"حكم خيار المجلس للمشتري والبائع","answer":"الجواب: ما دام تم البيع انتهى، إلا إذا كانوا في المجلس لهم الخيار، كل واحد له الخيار، سواء دولار وإلا غيره البيعان بالخيار حتى يتفرقا ما لم يشترطا ترك الخيار.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/5916/حكم-خيار-المجلس-للمشتري-والباىع","audio":"https://files.zadapps.info/binbaz.org.sa/dolar.mp3","categories":["الربا والصرف","البيوع"]},{"id":445,"question":"الآن بعض تجار السيارات إذا أراد أن يشتري سيارة يشتريها وتبقى باسم من اشتراها منه بحجة أن السيارة تصير أرغب للناس وهو يريد أن يبيعها، فيقول: ابق على اسمك، ويعطيه تفويضًا، هل يجوز لهذا المشتري أن يبيع؟","title":"ما حكم بيع السلعة قبل حيازتها؟","answer":"الجواب: هذا كذب، لا بدّ يبيعها باسم صاحبها؛ لأن هذا قد تترتب عليه أحكام. يبيعها من صاحبها ويعطيه وثيقة بأنه باعها عليه ولا يبيعها إلا بعد إخراجها من المعرض إلى معرض آخر أو إلى بيته أو إلى السوق؛ لما في الحديث نهى أن تُباع السلع حتى يحوزها التجار إلى رحالهم. (دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6153/ما-حكم-بيع-السلعة-قبل-حيازتها","audio":"https://files.zadapps.info/binbaz.org.sa/car.mp3","categories":["الربا والصرف","البيوع"]},{"id":450,"question":"بعض أهل العلم لا يفرِّق بين مسألة العِينَة والتَّوَرُّق؟","title":"ما الفرق بين بيع العِينَة والتَّوَرُّق؟","answer":"الجواب: غلط، التَّوَرُّق غير، التَّوَرُّق أن تشتري السلعة إلى أجل معلوم وتبيعها على الناس، واللي يشتريها ما يبيعها عليك، اللي يشتريها يبيعها على الناس الآخرين، إن باعها عليك هذه العِينة، لكن إن كان باعها على غيرك ما جاءت العِينة، يبيعها على غيرك، يتزوج أو يبني بيتًا أو يقضي دينًا، اشترى منه سيارة بمائة ألف ريال ثم باعها على غيره ما فيه شيء، العينة يبيعها عليه، أما إذا باعها على غيره فليس فيه ربا، والناس في حاجة إلى هذا.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6173/ما-الفرق-بين-بيع-العينة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/tawark008.mp3","categories":["الربا والصرف","البيوع"]},{"id":717,"question":"بعض المحلات التّجارية عند الافتتاح تضع جوائز من سيارات وغيرها، وتضع أرقامًا لمَن يشتري منها، وبعد الانتهاء من العرض يُسحب على أرقام مماثلةٍ، وصاحب الحظِّ السعيد مَن يفوز بالرقم المطلوب، فما حكم ذلك؟","title":"حكم الجوائز عند افتتاح المحال التجارية","answer":"الجواب: هذا صدرت فيه فتاوى عدة مرات، وتنبيه على أنه لا يجوز، وأنه من القمار، من الميسر؛ لأن معناه تشجيع سلعهم..... لعلهم يحرصون على هذه الأرقام، لعلهم يفوزون بشيءٍ منها، فيُغْرُونهم ويُعطلون سلع الناس الآخرين، فهو قمار وخداع وضررٌ على المجتمع الآخر، على أهل السلع، فلا يجوز.","link":"https://binbaz.org.sa/fatwas/20565/حكم-الجواىز-عند-افتتاح-المحال-التجارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0522فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الربا والصرف","البيوع"]},{"id":751,"question":"لقد جاءني رجلٌ طلب مني سيارةً دَيْنًا مُؤَجَّلًا، وقبل أن نتفق على القيمة ذهبت إلى المعرض واشتريتُ السيارة بالحاضر، وبعد شرائي للسيارة قررتُ قيمتها بالمُؤجل بمبلغٍ أكثر من القيمة التي دفعتُها، ثم بعتُها عليه، فهل هذه الصيغة شرعية أم أنَّ فيها شيئًا من الربا؟","title":"حكم شراء سيارة نقدًا وبيعها إلى أجل بفائدة","answer":"الجواب: لا حرج إذا اشتريتها وحُزتها وقبضتها وكُتبت على حسابك وانتهى كل شيءٍ، ثم بعتها إلى أجلٍ معلومٍ بفائدةٍ، فلا بأس على الصَّحيح، وهذا يُسمَّى: التَّوَرُّق، ويُسميه الناس: الوِعْدَة، ولا بأس بها على الصحيح، هذه من المداينة الشرعية، بشرط أن تحوزها، وتكون في ملكك، وتُكتب باسمك، وتنتهي إجراءاتها، وتنقلها إلى بيتك، أو إلى السوق، أو إلى المحل الآخر غير محل البائع، ثم بعد هذا تتصرف فيها بالبيع إلى أجلٍ معلومٍ، أو ببيعٍ نقدًا، كله واحد، وإذا بعتَها إلى أجلٍ فلا بأس بفائدةٍ، كأن تشتريها بعشرةٍ وتبيعها باثني عشر، ثلاثة عشر، أربعة عشر، تشتريها بعشرين وتبيعها بثلاثين، بخمسة وعشرين، إلى آجالٍ معلومةٍ، لا بأس بذلك، على الصحيح من أقوال العلماء.","link":"https://binbaz.org.sa/fatwas/20643/حكم-شراء-سيارة-نقدا-وبيعها-الى-اجل-بفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0566مسألة  في التورق ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":755,"question":"لقد وضعتُ مالًا بالبنك، وبعد عامٍ أرسل إليَّ البنك الحساب، وإذا به زيادة لم أضعها، وإنني في حيرةٍ من هذا المال الزائد على ما وضعتُه في البنك: أأتركه لصاحب البنك، أما ماذا أتصرف به حفظكم الله؟","title":"ما كيفية التصرف في فوائد البنوك الربوية؟","answer":"الجواب: هذه الزيادة هي الربا، المعروفة عندهم: الفائدة الربوية، والواجب في مثل هذا عدم التعامل مع البنوك بالربا، لا قليلًا، ولا كثيرًا، لا 5%، ولا 10%، ولا أقلَّ، ولا أكثر.\nوإذا كنت لم تتفق معهم على الربا ولم تشرطه عليهم وجاءك المالُ فأنفقه في وجوه الخير، هذه الزيادة للفقراء والمساكين، في بعض المشاريع الخيرية، ويكفيك رأس مالك.\nأما الاتفاق معهم فلا يجوز، لا تتفق معهم، تقول: أشترط عليهم الربا وأنفقه، لا، دع الربا بالكلية، لكن لو قدر أنَّهم دفعوا لك المال، أو أنك تساهلت وأخذت المال، ثم تبتَ إلى الله؛ تُنفقه في وجوه الخير، ولا تأكله أنت، ولا تصرفه في حاجاتك، ولكن تُنفقه في وجوه الخير، مثل: بعض الفقراء، مثل: إرساله للمُجاهدين الأفغان، مثل: إصلاح الطُّرقات، دورات المياه، وأشباه ذلك.","link":"https://binbaz.org.sa/fatwas/20636/ما-كيفية-التصرف-في-فواىد-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0562حكم آخذ الفوائد الربوية من البنوك وكيف يتصرف بها ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":787,"question":"هل يجوز أخذ الذهب بالدَّين –أي: يشتري الذهب والدفع يكون بعد عدة شهور لعدم توفر المال؟","title":"هل يجوز أخذ الذهب بالدَّين؟","answer":"الجواب: إذا اشترى الذهب بالنقود لا يجوز، هذا ربا، لكن لو اشترى الذهب بعروض أخرى: كملابس، أو سيارات، أو أطعمة؛ فلا بأس، أما أن يشتري بالنقود فهذا ربا، لا بدّ يدًا بيدٍ، لكن لو اشترى قلادةً من الذهب بخامٍ من الملابس الأخرى، أو بقهوةٍ، أو بسكرٍ، أو بأوانٍ، أو بسيارةٍ؛ لا بأس، نعم، ولو مُؤَجَّلة.","link":"https://binbaz.org.sa/fatwas/20789/هل-يجوز-اخذ-الذهب-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0619هل يجوز أخذ الذهب بالدين أي يشتري الذهب والدفع يكون بعد عدة شهور لعدم توفر المال؟ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":860,"question":"البنوك الربوية مُنتشرة في كثيرٍ من الدول العربية، لدرجة أنه يتعذر على المسلم أن يتحصل على سكنٍ أو قرضٍ لإنجاز أي مشروعٍ إلا عن طريق هذا البنك، ما العمل؟","title":"حكم القرض الربوي لأخذ مسكن أو مشروع","answer":"الجواب: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، ما هو ملزومٌ بالبنوك، يتسلّف من إخوانه، لا يَبْنِ، لا يقوم بالمشروع إلا بعدما يتيسر له الأمر، مَن الذي حادّه على المشروع الذي يحدّه على الربا؟! المشروع الذي يدعوه إلى الربا لا يُقيمه، يُقيم مشروعًا بالحرام؟! يصبر حتى يفرج الله، حتى يأتيه الحلال، أو يقترض من إخوانه بدون ربا، أما أن يقول: يُقيم مشروعًا، أو يتزوج، أو يَعْمُر بيتًا بالحرام؛ هذا منكرٌ، هذا غلطٌ.","link":"https://binbaz.org.sa/fatwas/20894/حكم-القرض-الربوي-لاخذ-مسكن-او-مشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القرض الربوي لأخذ مسكن أو مشروع.mp3","categories":["الربا والصرف","البيوع"]},{"id":955,"question":"السلام عليكم ورحمة الله وبركاته، يوجد في بعض المحلات التّجارية ألبان، وهذه الألبان إذا اشترى المُشتري بما يُعادل مئة ريـال تقريبًا يأخذ رقمًا، وهذا الرقم قد يقع على سيارةٍ أو ساعةٍ ثمينةٍ، فهل ذلك لا بأس به؟ أفيدونا جزاكم الله خيرًا.","title":"حكم منح المشتري بقيمة معينة رقمًا في سحب","answer":"الجواب: هذا كتبنا فيه واللجنة بأنه من القمار، لا يصلح؛ لأنه يشتري على الرقم: ما يُدريه؟ هل يحصل جائزةً أو ما يحصل جائزةً؟ وربما تذهب منهم أموالٌ كثيرةٌ بسبب هذه الجائزة. أما لو عيَّن قال: مَن اشترى منا أربع مرات بكذا أو خمس مرات بكذا نُعطيه كذا من سلعة كذا، نعطيه زيادة كذا شيء معلوم، ما يضرُّ إن كان معلومًا، إذا اشترى منا مثلًا بمئة ريـال أعطيناه لترًا أو اثنين أو كذا، أو اشترى منا بعشرة آلاف ريـال من كذا وكذا، ومن سبلٍ معينةٍ، ومن أصنافٍ؛ نقصنا عنه في الساعات الأخيرة كذا وكذا، وكان من هكذا وهكذا، فالأمر في هذا واضحٌ، ما فيه غرر.","link":"https://binbaz.org.sa/fatwas/21002/حكم-منح-المشتري-بقيمة-معينة-رقما-في-سحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0799في بعض المحلات يبيع ألبان فإذا اشترى المشتري بقيمة100ريال يأخذرقم قد يكون له سيارةفهل هذاجائز.mp3","categories":["الربا والصرف","البيوع"]},{"id":985,"question":"إذا كنتُ في حاجةٍ شديدةٍ إلى مبلغٍ كبيرٍ من المال، وليس أمامي سوى الاقتراض من البنك، علمًا بأنَّ البنك عند السَّداد يزيد مبلغًا على المبلغ الأصلي، فما الحل جزاكم الله خيرًا؟","title":"حكم قرض البنك الربوي في حال الضرورة","answer":"الجواب: ليس لك أن تأخذ بالربا مطلقًا، ولو كنتَ في حاجةٍ التمس الطرق الأخرى: اقترض من إخوانك الطيبين، أو اشترِ سلعةً إلى أجلٍ وبِعْها، وهي التي تُسمَّى: الوعدة، يُسمّيها العلماء: التَّورق، تشتري سلعةً إلى أجلٍ: تشتري سيارةً أو غيرها، ثم تبيعها وتقضي حاجتك.\nأما أخذ القرض بالربا فلا يجوز ولو كنتَ محتاجًا، ولو للزواج، أو لقضاء الدَّين، ليس لك أن تأخذ الربا أبدًا، الله يسَّر لك طرقًا أخرى غير الربا.","link":"https://binbaz.org.sa/fatwas/21023/حكم-قرض-البنك-الربوي-في-حال-الضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0820إذا كنت في حاجة شديدة إلى مبلغ كبير من المال وليس أمامي سوى الاقتراض من البنك الربوي؟.ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":1002,"question":"أفتونا مشكورين عن حكم شرب الدخان، وكذلك مَن يُتاجر في بيعه وهو لا يشربه، هل مكسبه حلالٌ أم حرامٌ؟","title":"ما حكم شرب الدخان وبيعه وكَسْبه؟","answer":"الجواب: بيع الدخان حرامٌ، والتجارة فيه حرامٌ، ومكسبه حرامٌ، وشربه حرامٌ، والواجب الحذر من ذلك، الواجب التَّواصي بتركه؛ لما فيه من مضارٍّ كثيرةٍ، والعواقب الوخيمة، وإضاعة المال، والمضرَّة في الدين والدنيا، فالواجب الحذر من ذلك، فليس للمؤمن بيعه، ولا التجارة فيه، ولا شربه بالكلية. وهكذا بقية المضرَّات والمخدرات والمسكرات، كلها حرام، كلها شرُّها عظيم، فالمسكر محرَّمٌ من أي جنسٍ كان، والذي يضرُّك في دينك ودُنياك محرَّمٌ وإن لم يُسْكِر.","link":"https://binbaz.org.sa/fatwas/21052/ما-حكم-شرب-الدخان-وبيعه-وكسبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0848ما حكم شرب الدخان وحكم من يتاجر ببيعه؟ ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":1007,"question":"شخصٌ اشترى ليرات لبنانية بريالات سعودية، وسلَّم الريالات ولم يستلم الليرات، بل استلم مقابلها شيكًا بالمبلغ، فهل هذا العمل جائز؟","title":"حكم شراء عملة باستلام شيك مصرفي بقيمتها","answer":"الجواب: هذا فيه خلافٌ بين علماء العصر: منهم مَن يرى الشيك يقوم مقام القبض؛ لأنه كالعملة. ومنهم مَن لا يرى أنه يقوم مقام القبض، فالذي ينبغي أن يقبض العملة، إذا سلَّم له دولارات أو جنيهات أو عملة لبنانية أو غير ذلك يأخذ مقابلها في المجلس، حتى يبتعد عن شبهة الربا؛ لأنَّ هذه العُمَل مُنَزَّلة منزلة الذهب والفضة، فينبغي لمن أخذ عملةً بعملةٍ أن يتقابضا في المجلس..... أو على بنك أو نحو ذلك، هذا هو محل النظر، وفيه شبهة: بعض أهل العلم جعله من قبيل عملة بعملة؛ لأن الشيك ماضٍ ويمشي بين الناس، ومنهم مَن لم يجعله كذلك، وقال: إنَّ هذا الشيك بمنزلة صكّ الدَّين والوثيقة، وذلك لا يجوز. وسوف يُعرض هذا على مجلس هيئة كبار العلماء لتبادل الرأي في موضوعه؛ لأنه موضوعٌ مهمٌّ، والحاجة إلى إعلانه وحكمه أمرٌ مهمٌّ، لا بد إن شاء الله من النظر في ذلك وإعلان ما يتمّ في ذلك.","link":"https://binbaz.org.sa/fatwas/21046/حكم-شراء-عملة-باستلام-شيك-مصرفي-بقيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0842شخص اشترى ليرات لبنانية بريالات سعودية وسلم الريالات ولم يستلم الليرات بل استلم بدل عنها شيك؟.mp3","categories":["الربا والصرف","البيوع"]},{"id":1047,"question":"سائلٌ يسأل عن حكم الاتِّجار بالعملة: بالدولار، أو بالليرة، أو باليِنّ الذي نراه في البنوك، ويلجأ إليه الأفراد لطلب الكسب وتحقيق الربح، لكنه لا يحصل فيه التَّقابض، فهل يصحّ ذلك؛ لأن ذلك كله يكون على الورق فقط؟","title":"ما الكيفية الصحيحة للتجارة بالعملات؟","answer":"الجواب: هذه الفتوى كثر السؤال عنها قديمًا وحديثًا، ولكن في هذه الأيام السؤال أكثر. والصواب: أنه لا يجوز إلا يدًا بيدٍ، فيأخذ العملة التي يُريد، ويدفع العملة التي عنده، يدًا بيدٍ، ثم يُمسكها عنده، أو يُودعها عند مَن شاء إلى أن يبيعها، أما كونه يأخذ ورقةً فقط فهذا حرَّمه جمع من أهل العلم، وبعضهم تساهل في هذا الشيء، ولكن الذي يظهر أنه لا ينبغي التَّساهل في ذلك، بل ينبغي له أن يأخذها يدًا بيدٍ، أو يدع؛ لأنَّ الشيك أشبه بالوثيقة، وأشبه بالمُداينة، والنبي ﷺ قال في الحديث الصحيح: إذا اختلفت هذه الأصناف لما ذكر الذهبَ والفضةَ والبُرَّ والشعيرَ والتَّمر وغيرها قال: فإذا اختلفت هذه الأصناف فبيعوا كيف شئتُم، إذا كان يدًا بيدٍ.\nوهكذا في العُملات: كالدولار، والجنيه، والريال، والين، وغيرها، إذا اختلفت فلا بد أن تكون يدًا بيدٍ، سواء ينّات، أو جنيهات، أو دولارات، أو دنانير، أو غير هذا، الواجب يدًا بيدٍ، ثم يُودعها إذا شاء، أما كتابة شيك فالأحوط والواجب تركه؛ لأنه ليس هناك ما يقتضي إقامته مقام العملات، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/21108/ما-الكيفية-الصحيحة-للتجارة-بالعملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0904ما حكم التجارة بالعملات؟ ابن باز فتاوى المحاضرات.mp3","categories":["الربا والصرف","البيوع"]},{"id":1077,"question":"ما حكم شراء العملات، بحيث يدفع المُشتري مبلغًا من الريالات السعودية، لكن لا يقبض هذه العملات، وإنما يقبض سندًا من البنك فقط، وقد يكون القبض بوسيلة التليفون؟","title":"حكم شراء العملات بسند بنكي دون تقابض","answer":"الجواب:\nالدلائل التي جاءت في الكتاب والسنة تدل على أنه لا بدّ من التقابض، الله جلَّ وعلا قال: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النور:54]، وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، وقد دلَّ ﷺ أمَّته على أنه لا بد من التَّقابض يدًا بيدٍ، ثم ذكر الذهب والفضة والبرَّ والشَّعير والتَّمر والملح، قال في ذكر بيع بعضها ببعض: مِثْلًا بمثلٍ، يدًا بيدٍ، سواء بسواء، فإذا اختلفت هذه الأصناف فبيعوا كيفما شئتُم إذا كان يدًا بيدٍ.\nفلا بد من التَّقابض عند اختلاف الأصناف: ريالات سعودية بريالات يونانية، أو دولارات أمريكية، أو دنانير، أو جنيهات مصرية، لا بد من التقابض، أما ورقة: يُعطيه شيكًا، لا يكفي، هذا هو المعتمد الذي دلَّت عليه الأدلةُ؛ لأن الشيك يُشبه الوثيقة، وقد يعتريه ما يعتري الوثيقة.\nفالحاصل أنه لا بد من أن يقبض اللّيرات أو الجنيهات أو الدولارات، ويُعطي ما في يده، ثم بعد ذلك إذا أحبَّ يُحوِّلها أو يُودعها، هو حرٌّ.","link":"https://binbaz.org.sa/fatwas/21140/حكم-شراء-العملات-بسند-بنكي-دون-تقابض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0936ما حكم شراءالعملات من الريال السعودي ويقبض المبلغ من البنك سنداً وقد يكون القبض بوسيلة التليفون؟.mp3","categories":["الربا والصرف","البيوع"]},{"id":1115,"question":"لدي سوقٌ، وأرغب في توزيع هدايا في شهر رمضان، منها سيارة، ويكون توزيع الهدايا بعد شراءٍ بمبلغ مئة ريـال لأخذ كوبون. أفتوني مأجورين، هل هذا العمل صحيح؟","title":"حكم توزيع هدايا بمتجر بعد شراءٍ معيّن","answer":"الجواب:\nهذا فيه إجمالٌ: إن كنتَ تُوزع الهدايا تُعطي الفقراء والمساكين دون شيءٍ، تُوزع عليهم، تُعطيهم صدقات، تُعطيهم أموال، ملابس، للفقراء والمساكين في رمضان. أما على طريقة القمار: تأخذ يعني: بطاقات تُقدِّمونها، فيدخل البطاقة مئة أو مئتين، ثم يُكتب عليها أرقام، مَن فاز بالرقم حصل كذا، هذا ما يجوز، هذا رِبا، بل قمار، مَيْسِر، إذا كنتَ صادقًا تريد البِرَّ ؛تصدَّق ولا تحطّ بطاقات، ولا تحطّ شيئًا، تصدَّق على الناس بما يسَّر الله لك من النقود، أو الملابس، أو الطعام.\nأما كوبونات أو بطاقات يكتب فيها مبالغ مطلوبة، مَن قدَّمها يقدم مئة ريـال، أو يعني: ما يُعطاها إلا بتقديم مئة ريـال أو مئتين، وعليها أرقام، ومَن فاز بالرقم حصل سيارةً أو راديو، أو كذا، أو كذا، هذه من أعمال المقامرة، ما تصلح، هذه ما هي بصدقة، هذا نهب أموال الناس.","link":"https://binbaz.org.sa/fatwas/21164/حكم-توزيع-هدايا-بمتجر-بعد-شراء-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0960أقوم بتوزيع هدايا في رمضان ويكون توزيع الهدايا بعد شراء مبلغ مائة ريال لأخذ كربون فما الحكم.mp3","categories":["الربا والصرف","البيوع"]},{"id":1166,"question":"تنتشر في بلادنا البنوك الربوية، ويعمل فيها الكثيرُ من الموظفين من أبناء المسلمين، وتحت رعاية شيوخ ونساء وأطفال، فهل دخلُ هؤلاء المُوظفين حرامٌ أم حلالٌ؟ أي: هل يدخل في الربا المُحرَّم؟","title":"هل العمل في البنوك الربوية حرام؟","answer":"الجواب:\nالعمل في البنوك محرَّمٌ؛ لأنه من باب التَّعاون على الإثم والعدوان، وقد صدر مني ومن اللَّجنة الدائمة فتاوى كثيرة في هذا الباب، والأصل في هذا قوله جلَّ وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2]، وقول النبيِّ ﷺ في الحديث الصحيح: أنه ﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء، فجعلهم ملعونين لتعاونهم مع المُرابين، فلا يجوز التَّعاون مع المرابين، لا بكونك مُحاسبًا، ولا أمين صندوقٍ، ولا مُراسلًا، ولا غير ذلك؛ لأنَّ هذا كله من التَّعاون: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، عساها تتعطل كلها: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، لعلها تتعطل كلها، أو يتوب الله عليهم ويتركوا الربا.","link":"https://binbaz.org.sa/fatwas/21217/هل-العمل-في-البنوك-الربوية-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1013ما حكم العمل في البنوك الربوية؟ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":1190,"question":"اشتريتُ سلعةً بمالي، وسلمتُ له الدراهم، ولكن قلتُ له: اتركها عندك لتبيعها لي، هل يجوز له شراؤها أو أجعله وكيلًا لي في بيعها؟ نرجو التفصيل.","title":"ضابط البيع المشروع وتمييزه عن بيع العِينة","answer":"الجواب:\nإذا اشتريتَ السلعة لا بد أن تنقلها من محلِّ البائع إلى محلٍّ آخر، وتبيعها في محلٍّ آخر؛ لقول النبي ﷺ: لا تبع ما ليس عندك؛ لأنه ﷺ نهى أن تُباع السلع حيث تُبتاع، حتى يحوزها التُّجار إلى رحالهم، وقال ﷺ: لا يحل سلفٌ وبيعٌ، ولا بيعُ ما ليس عندك، تُنقل السلعةُ من محلِّ البائع إلى السوق، أو إلى بيتك، أو إلى محلٍّ آخر، يبيعها لك إنسانٌ آخر، ولا تخليها عند الذي شريتها منه، تنقلها، وإذا بعتَها عليه بعدما نقلتها فلا بأس، وإن بعتها عليه؛ لأنه هو الذي اشتراها منك، فلا بأس، إذا كان الثمنُ حالًّا حاضرًا، أما إذا اشتريتَه منه بمؤجَّلٍ ثم بعتها له بأقلّ؛ هذا ما يجوز، هذه يُقال لها: العِينة.\nإذا اشتريتَها مثلًا بـ100 ريـال، ثم بعتَها عليه بـ80 أو 70 حاضرة، ويبقى في ذمَّتك الدَّين المؤجَّل، هذا يُسمَّى: العِينة، لا يجوز هذا، لكن إذا اشتريتَها بثمنٍ حاضرٍ 100 ريـال، سلَّمتَها له، ثم طرأ عليك أن تبيعها عليه بثمنها أو بأقلّ أو بأكثر فلا بأس.","link":"https://binbaz.org.sa/fatwas/21242/ضابط-البيع-المشروع-وتمييزه-عن-بيع-العينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1152اشتريت سلعة بمالي وسلمت له الدراهم ولكن قلت له أتركها عندك لتبيعها هو يجوز هو شراؤها.mp3","categories":["الربا والصرف","البيوع"]},{"id":1191,"question":"هل يجوز أن أشتري من فلاحٍ بُرًّا، وأُعطيه كيسًا مثل الذي أخذتُ منه عند الحصاد، أو أقول له: سلفة، أو كيس بكيسين؟","title":"حكم شراء بُرّ ثم ردِّه بمثله عند الحصاد","answer":"الجواب:\nهذا فيه تفصيل: أما السلف: أن تأخذ منه كيسًا فيه مئة صاع، أو مئتا صاعٍ، أربعون كيلو، ثلاثون كيلو، على سبيل السلف والقرض؛ فلا بأس، سواء تمرًا أو أرزًا أو غيره، على سبيل القرض والسلف. أما البيع: فلا تشترِ شيئًا من الحبوب بحبوبٍ أخرى مُؤجَّلة، لا بالمثل، ولا بالأكثر، تقول: أعطني مثلًا كيسًا فيه أربعون كيلو من التمر أو من الأرز بستين كيلو إلى أجلٍ، هذا ربا، ما يجوز هذا، ولو نقدًا أيضًا، ما تأخذ أربعين كيلو طيبة من التمر بستين كيلو رديئة من التمر، هذا ربا، ولو في الحال، لا بدّ أن يكون مثلًا بمثلٍ، صاعًا بصاعٍ، كيلو بكيلو، ما يزيد هذا على هذا من التمر، وهكذا من الأرز، وهكذا من الحنطة، أما إذا كان مختلفًا: فإن أخذتَ مثلًا أربعين كيلو من الحنطة بخمسين كيلو من الشعير، أو أربعين كيلو من الحنطة بثلاثين كيلو من الأرز مختلفة، يدًا بيدٍ؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/21241/حكم-شراء-بر-ثم-رده-بمثله-عند-الحصاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1153هل يجوز أن أشتري من فلاح بر وأعطيه كيس مثل الذي أخذته منه عند الحصاد؟ ابن باز.mp3","categories":["الربا والصرف","السلف والقرض"]},{"id":1219,"question":"أولًا: اعلم حفظك الله أني أُحبُّك في الله.ثانيًا: نود من فضيلتكم بيان مقدار الربح فيما يُتاجر به التُّجار، وهل هناك ضابط معينٌ لمقدار الربح أم أنه لا يوجد؛ لأنَّ بعض التجار الآن هداهم الله يربحون أضعاف أضعاف ما اشتروا به؟ نرجو التفصيل حفظكم الله؟","title":"هل هناك ضابط لمقدار الربح في التجارة؟","answer":"الجواب:\nالشيخ: أولًا: نقول: أحبَّك الله الذي أحببتنا له، جاء في الحديث: يقول ﷺ: مَن أحبَّ منكم أحدًا فليُخبره، أو كما قال عليه الصلاة والسلام، وإذا أخبره فليقل: أحبَّك الله الذي أحببتنا له، نسأل الله جلَّ وعلا أن يجعلنا وإيَّاكم من المتحابين في جلاله، وأحبَّكم الله الذي أحببتُمونا له.\nويقول النبيُّ ﷺ في الحديث الصحيح: سبعة يُظلُّهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجلٌ قلبه مُعلَّقٌ بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه -هذا مثالٌ- ورجلٌ دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله، وهكذا المرأة إذا دعاها ذو منصبٍ وجمالٍ قالت: إني أخاف الله، من السبعة الذين يُظلهم الله في ظلِّه، ورجل تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شماله ما تُنفق يمينه، يعني: يتصدَّق ويحرص على السر، وإن جهر فلا بأس، قال تعالى: إِنْ تُبْدُوا الصَّدَقَاتِ فَنِعِمَّا هِيَ وَإِنْ تُخْفُوهَا وَتُؤْتُوهَا الْفُقَرَاءَ فَهُوَ خَيْرٌ لَكُم [البقرة:271]، فالإخفاء أفضل، وإن جهر لمصلحةٍ، مثل: صدقة في المسجد حتى يتبعه الناسُ، أو في اجتماعٍ حتى يتبعه الناسُ، فهذا أفضل، والسابع: رجل ذكر الله خاليًا ففاضت عيناه، ذكر الله ما عنده أحدٌ، فبكى من خشية الله جلَّ وعلا.\nوفي الحديث الآخر: يقول ﷺ: يقول الله  يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلّهم في ظلِّي يوم لا ظلَّ إلا ظلي.\nأما السؤال الثاني: فليس للربح حدٌّ محدودٌ، لم يأتِ في الشرع تحديدٌ للربح: لا بالثلث، ولا بالربع، ولا بغير ذلك، بعض الفقهاء -بعض العلماء- قالوا: الثلث، ولكن ليس عليه دليلٌ، والأولى بالمؤمن الرفق، وألا يكون جشعًا، وأن يرضى بالربح القليل، وأن يرفق بإخوانه، هذا هو المشروع، وهذا هو الأفضل: أن يتحرى الربح القليل الكافي الذي يُعينه على البيع والشراء، ويُعينه على أداء أجور المحل من العمال ونحو ذلك، ولا يكون كثيرًا يُتعب الناس، يتحرَّى ويجتهد الربح المناسب، هذا هو المشروع للتاجر وغير التاجر.\nأما التَّحديد: فليس له حدٌّ محدودٌ، قد اشترى النبيُّ ﷺ البعير بالبعيرين، من إبل الصدقة، البعير الواحد بالبعيرين، ولا حرج أن يبيع ما اشتراه بمئةٍ بمئتين إذا تغيَّرت الأحوال، أو جاءه إنسان ظالم مثل هذا الشيء وهو ما يُريد أن يبيعه لكن لأجله باعه إيَّاه بربح مئة في مئة لا حرج، ليس فيه حدٌّ محدودٌ، قد تكون عندك سيارة تُريدها وليس لك رغبة في بيعها، ثم يأتي إنسانٌ له رغبة فيها، ويُحب أن يشتريها ولو بالكثير، لا حرج في ذلك وهكذا بيته، وهكذا أرضه، لكن إذا رفق الإنسانُ وأخذ الربحَ المناسبَ الذي يُناسب حاله وحال نفقاته فهو أحسن.","link":"https://binbaz.org.sa/fatwas/21275/هل-هناك-ضابط-لمقدار-الربح-في-التجارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1119هل هناك ضابط لمقدار الربح؟ ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":1243,"question":"كنتُ في بعثةٍ في خارج المملكة، ووضعتُ فلوسي في بنك، وفُوجئتُ بعد سنتين أنهم قد قدَّموا لي ربحًا من هذا الرصيد، فهل آخذه أم أتركه لأولئك الكفَّار لكي يستفيدوا منه؟","title":"حكم وكيفية التصرف في أرباح البنوك الربوية","answer":"الجواب:\nهذا ما دمتَ لم تُشارطهم عليه تأخذه وتتصدَّق به، لك رأس مالك، والربح الذي هو الربا تصرفه في وجوه الخير: من مساعدة الفقراء والمجاهدين، وتعمير الطرقات ودورات المياه، وغير هذا مما ينفع الناس.\nوبعض أهل العلم يرى أنه لا حرج فيه إن كنتَ لم تشترطه ولم تقصده ولم تُواطئهم عليه؛ لقوله ﷺ: إنَّ خيار الناس أحسنُهم قضاءً، ولقول عمر  لما أعطاه النبيُّ بعضَ الشيء قال: يا رسول الله، أعطه مَن هو أفقر مني، فقال: ما جاءك من هذا المال وأنت غير مشرفٍ ولا سائلٍ فخذه، وما لا فلا تتبعه نفسك، فإذا كنت غير مشرفٍ له ولم تقصده ولم تتواطأ معهم عليه فظاهر النصِّ حلُّه، لكن لما كان التَّعاون مع البنوك معروفًا أنه ربا، والإنسان يعرف أنهم يعطون الربا، ولم يقل لهم: هذه وديعة بدون ربا؛ فإنَّ هذا المال الذي يأخذه لا ينبغي له أن يستطيبه، بل يُنفقه في وجوه البر وأعمال الخير؛ لأنهم أعطوه على أنه ربا، على أنه في مقابل وضعه وديعةً، وهذا عُرْفٌ بين الناس معروف، فكأنه مشروطٌ، فإذا أخذته ودفعته لوجوه الخير كان ذلك حسنًا.  أما أن تتفق معهم على ذلك فتشترط الربح وتقول: أُعطيه أهل الخير، لا، ما يجوز هذا.","link":"https://binbaz.org.sa/fatwas/21291/حكم-وكيفية-التصرف-في-ارباح-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1034كنت في بعثة خارج البلد ووضعت فلوسي في بنك فوجئت بعد سنتين أنه قدموا لي ربحاً هل آخذه أو أتركه.mp3","categories":["الربا والصرف","البيوع"]},{"id":1273,"question":"ما حكم التَّعامل في أحد البنوك المحلية في صناديق الاستثمار، ويكون عقد بين البنك وواضع النقود بالربح والخسارة؟","title":"ما حكم معاملات صناديق الاستثمار بالبنوك؟","answer":"الجواب:\nهذا إذا أُمِن، لا بدّ أن يكون من طريق الربح والخسارة، يعني: من طريق المضاربة، جزء مشاع، يُعطيه مئة ألف أو أكثر أو أقلّ ويقول: تعمل فيها بالمضاربة، يشتري سيارات، يشتري عملات ويبيعها، يقول: لك النصف، أو لك الربع، أو لك الخمس، لا بأس.  أما فائدة معينة: لك 5%، 10%، هذا الربا، ما يجوز.  لكن إذا كان بربع الحاصل: ربع الربح، عُشر الربح، يعني 10% من الربح، 20، 50،  النصف لا بأس، هذه تُسمَّى المضاربة، وهي جائزة عند جميع العلماء، لكن هل يُؤْمَنون؟ هذا محل نظرٍ، هل يُؤْمَنون على هذه العملية، أو يبيعون بالربا؟ بعضهم لا يُؤْمَن، وأشكّ أنهم يُؤْمَنون في هذا الشيء؛ لأنهم قد اعتادوا الربا، لكن إن كان مع أناسٍ مأمونين فهذا طيبٌ.","link":"https://binbaz.org.sa/fatwas/21332/ما-حكم-معاملات-صناديق-الاستثمار-بالبنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1075ما حكم التعامل مع البنوك في صناديق الأستثمار ويكون عقد بين البنك وواضع النقود في الربح والخسارة.mp3","categories":["البيوع","الربا والصرف"]},{"id":1352,"question":"يعطي البنك الرجل هدية، عنده عمالة عند البنك يعطيه هدية؟","title":"ما حكم أخذ هدايا البنوك؟","answer":"الجواب:\nالبنك لا تجوز معاملته؛ لأنه ربا، لا هديته ولا معاملته، كله.  والواجب الحذر من الربا، يقول الله جل وعلا: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275]، وهديتهم دعوة إلى الربا.\nس: بعض البنوك يعطوننا هدية \"دفتر\" أو \"تقويم\" أو شيئًا كذا؟\nج: لا، هذا ترغيب لك في المعاملة. أما إذا كان لأسباب كإيداع عندهم يعطونك وثيقة بأن مالك عندهم؛ هذا ما فيه بأس.\nس: هو بقصد الترغيب؟\nج: لا لا، الترغيب لا، ما يصلح، أما وثيقة عندهم لك مال، هذا مثل غيرهم، الوثيقة لا بأس بها، لكن من دون معاملة إذا اضطر إلى وديعة عندهم أو تحويل مال بواسطتهم يأخذ وثيقة؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/21445/ما-حكم-اخذ-هدايا-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ هدايا البنوك.mp3","categories":["الربا والصرف","البيوع"]},{"id":1410,"question":"العمل بالأسهم التجارية؟","title":"ما حكم العمل بالأسهم التجارية؟","answer":"الجواب:\nإذا كان ما فيها ربا لا بأس. إذا كان أسهم في حديد، في بناء، في أراضٍ، في سيارات؛ لا بأس، أما الربا لا.\nس: الأسهم التي تتداول في البنوك؟\nج: البنوك لا، ما يصلح، أما أسهم ما فيها ربا فالحمد لله، شركات يشتركون في أراضٍ، في سيارات، في معدات، في ملابس؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/21505/ما-حكم-العمل-بالاسهم-التجارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العمل بالأسهم التجارية.mp3","categories":["البيوع","الربا والصرف"]},{"id":1451,"question":"بعضهم يبيعون الدخان، ويحتجون بأنه ليس لهم بل لكفيلهم؟","title":"ما حكم مَن يُلزمه كفيله ببيع الدخان؟","answer":"الجواب:\nولو، لا يساعد على باطل، بيع الدخان محرم مثل بيع الخمر، لا يساعد ولو ما هو له، لا يصير دلَّالًا ولا وكيلًا في البيع المحرم، يقول الله: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2]، والذي يبيع الخمر أو يبيع الدخان أو يبيع شيئًا مما حرَّمه الله يكون شريكًا لمن وكَّله، مُعِينًا له على الإثم.\nس: إذا رفض هذا أحدُ الناس فقد يقوم كفيله بتسفيره إلى بلاده وهو في أمس الحاجة إلى التحصّل على وسيلة المعاش، فكيف يصنع في مثل هذه الحالة؟\nج: ولو، لا يتعاون على غش ولا محرم ولا بيع محرم، إنما الطاعة في المعروف، لا طاعة لمخلوقٍ في معصية الخالق، لكن يُراجع المحكمة، بحيث لا يُمَكِّنه من التساهل، فيذهب إلى المحكمة أو إلى الأمير إن كان في بلدٍ فيها أمير.","link":"https://binbaz.org.sa/fatwas/21548/ما-حكم-من-يلزمه-كفيله-ببيع-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المساعدة على الباطل.mp3","categories":["الربا والصرف","البيوع"]},{"id":1483,"question":"راتبنا الآن إلى بعض البنوك الربوية، وأحيانًا عند الصرف يبقى لنا عندهم مثلًا عشر هللات، أو يعطونا زيادة عشر هللات، ما الحكم حينئذٍ؟","title":"حكم تحويل الرواتب بواسطة البنوك الربوية","answer":"الجواب:\nالأمر سهل، هذه حوالة على أموال الدولة، ما يضركم.","link":"https://binbaz.org.sa/fatwas/21581/حكم-تحويل-الرواتب-بواسطة-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التعامل مع البنوك الربوية.mp3","categories":["الربا والصرف","البيوع"]},{"id":1507,"question":"يحصل من بعض التجار أنه يشتري كميةً كبيرةً، مثلًا: نحو عشرة آلاف كرتونة صابون، أو عشرة آلاف كيس أرز، وما أشبه ذلك، فتكون هذه أحيانًا مستوردةً، وأحيانا غير مستوردةٍ، فهل يُشترط في هذه الحالة قبل أن أبيعها أن أنقلها؟ وإذا نقلتها يقول: ما الفائدة حينئذٍ ما دمتُ سأبيعها؟ ما الفائدة؟","title":"حكم القبض والتخلية في البيع والشراء","answer":"الجواب:\nإذا شقَّ عليه النقلُ فلا يلزم، فالشيء الذي يشق يُعْفَى عنه؛ لعظمه وكثرته، كالمنزل والأرض، فقبضها التَّخلية، أما إذا تيسر النقلُ فالنبي ﷺ أمر بالنقل، فقد نهى رسول الله ﷺ أن تُباع السلع حيث ابتيعتْ حتى يحوزها التُّجار إلى رحالهم، فإذا تيسَّر حوزها فليحوزها.","link":"https://binbaz.org.sa/fatwas/21606/حكم-القبض-والتخلية-في-البيع-والشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في القبض والتخلية في البيع والشراء.mp3","categories":["الربا والصرف","البيوع"]},{"id":1574,"question":"بالنسبة لشخصٍ أُعطي من البنك فوائد، ورأى أن تُصرف هذه الفوائد في بناء حمامات مثلًا، أو ما شابه ذلك؟","title":"ما كيفية التصرف في فوائد البنك المالية؟","answer":"الجواب:\nما في بأس، الحمامات، أو إصلاح الطرق، أو ما أشبه ذلك.\nس: لو كان له أقارب فقراء، هل له أن يُعطيهم ولا يُخبرهم؟\nج: إذا كانوا مستحقين للزكاة لا يلزم أن يُخبرهم، نعم، ما هو بلازم أن يُخبرهم، إلا إذا كان في شكٍّ يقول تراها زكاة، سواء كان من أهلها وإلا..","link":"https://binbaz.org.sa/fatwas/21677/ما-كيفية-التصرف-في-فواىد-البنك-المالية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التصرف في مال فوائد البنك.mp3","categories":["الربا والصرف","البيوع"]},{"id":1586,"question":"يقول السائل: احتجتُ إلى قرضٍ من المال، فلم أجد مَن يُقرضني، وقال لي شخصٌ أنه سوف يُقرضني بالدولار على أن أُسدد بالريال، وحسب الدولار بخمسة ريالات، تُسدد على أقسامٍ، والمعروف أنَّ الدولار...؟","title":"ما حكم من اقترض بالدولار وسدَّد بالريال؟","answer":"الجواب:\nلا تُكْمِل، هذا ربا، ما يجوز، ربا، ما يصلح.","link":"https://binbaz.org.sa/fatwas/21689/ما-حكم-من-اقترض-بالدولار-وسدد-بالريال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اقترض بالدولار وسدد بالريال.mp3","categories":["الربا والصرف","البيوع"]},{"id":1911,"question":"بيع كلب الصيد؟","title":"حكم شراء الكلب والقط والثعلب ونحوها","answer":"الجواب:\nلا يجوز شراء كلب الصيد ولا غيره.\nس: طيب، هل تدخل بيع السباع والثعالب والقطط هل تدخل فيه؟\nج: لا تُباع، الرسول ﷺ نهى عن بيع السِّنَّوَر –القط- فلا يباع، فالرسول نهى عن ثمن السِّنَّوَر والكلب.\nس: إذا اضطر لشِّراء كلب الصيد؟\nج: ما يجوز شراؤه، لكن يمكن أن يُربِّي كلبًا صغيرًا عند غنمه حتى ينفع.\nس: هناك محلات تبيع هذا، أحسن الله إليك؟\nج: عملهم ما هو بحجة، جاء في حديثٍ عند النسائي: إلا كلب صيد، لكنه حديث ضعيف، وفي \"الصحيحين\" النهي عن بيع الكلاب مطلقًا، والنهي عن ثمن الكلاب وأنه خبيث.","link":"https://binbaz.org.sa/fatwas/22024/حكم-شراء-الكلب-والقط-والثعلب-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم شراء بعض الحيوانات كالكلب ونحوه.mp3","categories":["الربا والصرف","البيوع"]},{"id":2016,"question":"يقول السائل: فضيلة الشيخ أنا أعمل في البنك السعودي البريطاني منذ عشر سنوات والبنك يقدم قروضًا ربوية، فهل كوني أعمل في بنك ربوي حرام، علمًا بأنني بحثت عن وظيفة أخرى فلم أجد؟","title":"هل يجوز العمل في البنوك الربوية؟","answer":"الجواب:\nنعم، لا يجوز لك العمل فيه، ما دام بنكًا ربويًا لا تعمل فيه، والله يرزقك عملًا آخر أفضل منه، يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا  ۝  وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2-3]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] يجب عليك البُعْد عن هذا الربا، والتوبة مما سلف.","link":"https://binbaz.org.sa/fatwas/22132/هل-يجوز-العمل-في-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1013ما حكم العمل في البنوك الربوية؟ابن باز.mp3","categories":["الربا والصرف","البيوع"]},{"id":2177,"question":"أريد أن أشتري عقارًا عن طريق إحدى الشركات بالتقسيط، ولكنَّها لا تملكه، وإنما أدلّها أنا عليه، فتمتلكه وأنا أشتريه عن طريقها؟","title":"حكم شراء العقار عن طريق شركات التقسيط","answer":"الجواب:\nإذا كان بالتّقسيط فلا بأس.\nس: الشركة لا تملك هذا العقار، لكني أنا أدلها عليه؟\nج: لا بأس.............\nس: لا، أقصد الشركة مثلًا ما عندها عقار، وأنا عندي أرض أدلُّ الشركة عليها لتشتريها؟\nج: تبيع عليها أرضك؟\nس: لا، أنا أريد أن أشتريها (كاش) لكن ما عندي قدرة، فلذلك أشتريها عن طريق إحدى شركات التقسيط؟\nج: إذا عمَّروها وباعوها عليك اشترِها، فلا تشترِها إلا بعدما يُعَمِّروها.\nس: أنا أريد أن أشتريها أرضًا؟\nج: اشترِ أرضًا منها أو من غيرها.\nس: لا، من الشركة نفسها.\nج: اشترِ الأرض من مالِكَ، من شركةٍ أو من غير شركة، بالنقد أو بالأقساط المعلومة، لا بأس.","link":"https://binbaz.org.sa/fatwas/22298/حكم-شراء-العقار-عن-طريق-شركات-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شراء العقار بالتقسيط عن طريق شركات التقسيط.mp3","categories":["الربا والصرف","البيوع"]},{"id":2250,"question":"يقول السائل: أحيانًا يطلب مني بعضُ الزملاء أن أصرف له مبلغ مئة ريـال، ولا يكون معي إلا خمسة وتسعون ريالًا، وأعطيه الخمسة ريالات المتبقية بعد ذلك، وتكون في حكم الدَّين عليَّ له، فهل يُعدّ ذلك من الرِّبا؟","title":"حكم صرف مئة ريال مع بقاء جزء مؤجل","answer":"الجواب:\nما يصلح، لكن تأخذها أمانةً عندك، ثم إذا جاءت الخمسة تُعطيه إياها مع ما مضى، وتقبض منه المئة فتكون كأمانةٍ، وتكون الأولى سلفةً كالقرض حتى يتيسر لك التكميل، ثم تُكمل، ثم تأخذ المئة، ثم يكون الصرف، فالصرف لا بد أن يكون بالتّقابُض، مثلما قال ﷺ، لا بأس أن تأخذها بسعر يومها، ما لم تفترقا وبينكما شيء، فتبقى عنده المئة أمانة كالرهن.","link":"https://binbaz.org.sa/fatwas/22373/حكم-صرف-مىة-ريال-مع-بقاء-جزء-موجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صرف مبلغ مئة ريال بخمسة وتسعين ريال.mp3","categories":["الربا والصرف","البيوع"]},{"id":2268,"question":"رجلٌ يسأل عن حكم البيع بالتَّصريف؟","title":"ما معنى وحكم البيع بالتَّصريف؟","answer":"الجواب:\nهذا الكلام مُجْمَل.\nس: صفته أن التاجر يأتي بالبضاعة ويقول: ما أُريد منك مالًا، إذا بعتَ أعطني المال؟\nج: لا، لا بد من بيعها إمَّا لأجل معلومٍ أو حالّ؛ حتى يكون على بصيرةٍ، فإمَّا أن يقول أنه حالّ ومتى شاء طالبه به، وإلا إلى أجلٍ معلومٍ.\nس: يقول: الذي ما تبيعه ردّه لي لا بأس؟\nج: لا بدَّ من أجلٍ معلومٍ.\nس: إذن يُقال: يُترك احتياطًا أم لا يجوز؟\nج: لا يجوز، لا بد من جزم البيع.\nس: وأيش يُسمَّى هذا؟\nج: يُسمّونه: أن يبيع بشرطٍ على خسارته، متى شاء ردّه، وهذا من الشروط الباطلة.","link":"https://binbaz.org.sa/fatwas/22391/ما-معنى-وحكم-البيع-بالتصريف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بالتَّصريف.mp3","categories":["الربا والصرف","البيوع"]},{"id":2299,"question":"يقوم بعضُ الناس ببيع الكلاب المُعَلَّمة، ويقولون أنهم أنفقوا من أموالهم ووقتهم في سبيل تعليمها، فهل يدخل ذلك في نهي النبيِّ ﷺ عن ثمن الكلب؟","title":"حكم بيع الكلاب المُعَلَّمة","answer":"الجواب:\nالكلب لا يُباع مطلقًا، سواء كان مُعَلَّمًا أو غير مُعَلَّمٍ، ورواية النَّسائي: إلا كلب الصيد ضعيفة، فالرسول نهى عن بيع الكلب، وثمنه خبيثٌ مطلقًا، سواء كان مُعلَّمًا أو غير مُعلَّمٍ.","link":"https://binbaz.org.sa/fatwas/22423/حكم-بيع-الكلاب-المعلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع الكلاب المعلمة.mp3","categories":["الربا والصرف","البيوع"]},{"id":2302,"question":"يقول أحدُ الطلبة: ذهب بعضُ العلماء إلى أنَّ مسألة التَّورق التي يشتري فيها شخصٌ سلعةً ما بثمنٍ مُؤَجَّلٍ، ثم يبيعها لشخصٍ آخر بثمنٍ أقلَّ حاضرٍ: إلى أنها بيعٌ ربويٌّ، فعلى مَن يقع إثم الرِّبا في هذا البيع؟","title":"هل بيع التَّورق من البيوع الربوية؟","answer":"الجواب:\nهذا ما هو بربا، الصحيح أنه ليس ربًا، فمسألة التَّورق ليست ربًا، وقول مَن قال أنها ربا غلطٌ، فإذا اشترى سلعةً بأجلٍ، ثم باعها بنقدٍ على غير مَن اشتراها منه لحاجته فلا بأس، هذا هو الصواب، فالله  يقول: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275]، فالأصل حِلُّ البيع.","link":"https://binbaz.org.sa/fatwas/22426/هل-بيع-التورق-من-البيوع-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل بيع التَّورق بيعٌ ربويٌّ.mp3","categories":["الربا والصرف","البيوع"]},{"id":2305,"question":"إنسان عنده ورقة بعشرة ريالات يُبدلها بتسعة ريالات هلل؟","title":"حكم استبدال عملة ورقية بمعدنية أقل عددًا","answer":"الجواب:\nلا بأس، الهلل جنس آخر، يدًا بيدٍ، مثل أو بقياس؛ لأنَّ هذا غير هذا، مثل العملة الأخرى.","link":"https://binbaz.org.sa/fatwas/22429/حكم-استبدال-عملة-ورقية-بمعدنية-اقل-عددا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استبدال ورقة عشرة ريالات بتسعة ريالات هلل.mp3","categories":["الربا والصرف","البيوع"]},{"id":2473,"question":"حكم البيع بعد النداء الأول؟","title":"حكم البيع بعد النداء الأول يوم الجمعة","answer":"الجواب:\nما في بأس، التحريم يكون بعد النداء الثاني، إذا أذّن النداء الثاني حَرُم البيع وبَطَل، الأذان الثاني بين يدي الإمام عند دخوله للخطبة، هذا الأذان الثاني، يُسمّى الأذان الثاني، وهو الأول بالنسبة إلى الإقامة.","link":"https://binbaz.org.sa/fatwas/22602/حكم-البيع-بعد-النداء-الاول-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بعد النداء الأول يوم الجمعة.mp3","categories":["الربا والصرف","البيوع"]},{"id":2511,"question":"موضوع التقسيط فيه شركات يقسطون بحيث يقولون:السيارة بمائة ألف لو خليتها على سنه واحدة نأخذ منك مائة وعشرة، سنتين مائة وعشرين، ثلاث سنوات مائة وثلاثين؟","title":"حكم البيع بالتقسيط مع عدم الجزم بالثمن","answer":"الجواب:\nلا بد مِنْ جَزْم، ما يصلح هكذا، لا بد من جزم على قسطين ثلاثة أربعة، إذا جزم عليها فلا بأس، كل سنة كذا، كل شهر كذا...\nس: إذا قال له: على السنة نسبة معينة؟\nالشيخ: لا بد من جزم.\nس: كيف يعني الجزم؟\nالشيخ: أربعين ألف كل سنة عشرة آلاف جزما، أو خمسين ألف كل سنة عشرة آلاف.\nس: بعض الشركات الآن يأخذون نسبة على السنة يقول ثمانية ونصف في المائة على السنة، أو عشرة بالمائة على السنة؟\nالشيخ: المقصود أن يتفقوا على شيء معلوم، هذا هو المقصود، كل سنة أو كل شهر أو كل شهرين.","link":"https://binbaz.org.sa/fatwas/22641/حكم-البيع-بالتقسيط-مع-عدم-الجزم-بالثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بالتقسيط مع زيادة في الثمن.mp3","categories":["الربا والصرف","البيوع"]},{"id":2560,"question":"تقول: عندما يريدون أن يسافروا إلى هناك (بالخراج) يودِعون أموالهم في البنوك ويعطونهم \"كرت\" فيه نوع من الربا فلا بدّ أن يفعلوا هذا، فماذا يصنعون في مثل هذه الحالة؟","title":"حكم الاضطرار لإيداع أموال في بنك ربوي","answer":"الجواب: لا، يضعونها بدون ربا، يأخذون الوثيقة بدون الربا، يضعونها عندهم كأمانة ويحولون عليها بالتحويلات المعتادة بينهم.\nس: على حسب سؤالها تقول: لا بدّ يعطونها الكرت هذا الذي فيه ربا؟\nالشيخ: يمكن هذه القيمة، يقول: سَلِّم قيمة هذا الكرت، هذا قيمة الورقة، مثل الحوالة التي تحول أنت على زيد أو على عمرو تعطيهم قيمة الحوالة عن تعبهم، أما يكون في جداولهم هذه قيمة السفتجة، أما الربا عن المال ما يصلح.\nس: إذا اضطر إلى ذلك يفعل أو لا يفعل؟\nالشيخ: هذا للوثيقة، قيمة الوثيقة، يعطونه قيمة الوثيقة التي يحول بها، مثل وثيقة السفتجة، الحوالة.","link":"https://binbaz.org.sa/fatwas/22692/حكم-الاضطرار-لايداع-اموال-في-بنك-ربوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاضطرار لإيداع الأموال في البنوك الربوية.mp3","categories":["الربا والصرف","البيوع"]},{"id":2570,"question":"هل يجوز فتح محل لبيع الملابس الرجالية الإفرنجية، ويرتادها نسبة كبيرة من الشباب الذين يريدون السفر إلى بلاد العهر والدعارة؟","title":"حكم فتح محل لبيع الملابس الرجالية الإفرنجية","answer":"الجواب: إذا كان مما يلبسه المسلمون ولو مصنوعة في الخارج، إذا كان من ملابس المسلمين ولو هو مصنوع في لندن وفي أمريكا، أما إذا كان فيه تشبه بالكفار؛ لا.\nس: بنطلونات وكرفتات؟\nالشيخ: المقصود إذا كان من لباس الكفار ما هي من لباس المسلمين، ما يجوز، لا يساعدهم على الباطل، الله جل وعلا يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] نسأل الله العافية.\nس: إذا كانت مشتركة بين المسلمين والكفار؟\nالشيخ: إذا كانت مشتركة فمثل السيارة؛ ما هي من خواص الكفار، والطائرة كذلك المشتركة ما فيها شيء، الطائرات ما هي من خواص الكفار، والسيارات ما هي خاصة للكفار.","link":"https://binbaz.org.sa/fatwas/22703/حكم-فتح-محل-لبيع-الملابس-الرجالية-الافرنجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فتح محل لبيع الملابس الرجالية الأفرنجية.mp3","categories":["الربا والصرف","البيوع"]},{"id":2800,"question":"الذي عنده أغنام يعدها للبيع يسمّنها ويغذّيها قبل أن يعرضها للبيع، هل في ذلك محظور؟","title":"حكم تسمين الأغنام لتنتفخ قبل بيعها","answer":"الجواب: وأيش المانع، يسمّنها حتى تَسْمَن وتنفعه. أما اللبن لا يغش الناس باللبن، أما كونه يسمَنها ويخليها أسبوعين ثلاثة حتى تزيد ما في شيء.\nس: بعضهم يعطيها ماءَ وملحًا فتنتفخ؟\nالشيخ: لا، الشيء الذي فيه غش ما يجوز، أما السمينة عادي ما في شيء، يسمّنها، مطلوب منه يسمنها حتى تنفعه... أما الغش لا يجوز، الشيء الذي ينفخها ما يجوز، أو...كذلك يجمع اللبن فيها ويقول إنه من الصبح، وهو ما هو من الصبح، لبن البارحة ولبن الصبح ولبن أمس، هذا ما يجوز؛ غِشّ.","link":"https://binbaz.org.sa/fatwas/22948/حكم-تسمين-الاغنام-لتنتفخ-قبل-بيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هنده أغنام يعدها للبيع فيسمنها لتنتفخ.mp3","categories":["الربا والصرف","البيوع"]},{"id":3101,"question":"رجل أراد أن يشتري حاجة من محل، ما معه إلا مائة ريال واشترى حاجة بمبلغ خمسين ريال وبقي له خمسين، ولم يكن موجودًا الباقي مع صاحب المحل...؟","title":"حكم مَن اشترى سلعة وبَقي له مبلغ مما دفعه","answer":"الجواب: يُمْهِله وإلا يخلّي عنده المائة أمانة حتى يحضر له الخمسين، وإلا يعطيه إياها ويرد عليه خمسين، الأمر واسع، إما يعطيه إياها ويرد عليه خمسين، وإلا يُمْهِله ويُنْظِره حتى يأتي له بالخمسين، وإلا يخليها عنده أمانة حتى يأتي له بالخمسين كالرهانة.","link":"https://binbaz.org.sa/fatwas/23261/حكم-من-اشترى-سلعة-وبقي-له-مبلغ-مما-دفعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشترى سلعة وبقي له مبلغ عند صاحب المحل.mp3","categories":["الربا والصرف","البيوع"]},{"id":3133,"question":"ما حكم بيع الرجل المشرك ثوب الحرير؟","title":"حكم بيع ثوب الحرير إلى الرجل المشرك","answer":"الجواب: الأقرب عندي أنه لا يجوز، لا يعينه على الباطل، يُروى عن عمر أنه كان يرسل بعض الثياب لأقارب له من الكفار الحرير؛ لكن لعله أرسلها لهم لصلة بينهم حتى يُلبسوها نساءهم.\nس: ما يدل على الجواز؟\nالشيخ: لا ما هو بصريح، قد يكون أراد أنهم يُلبسونها نساءهم.","link":"https://binbaz.org.sa/fatwas/23294/حكم-بيع-ثوب-الحرير-الى-الرجل-المشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع الرجل المشرك ثوب الحرير.mp3","categories":["الربا والصرف","البيوع"]},{"id":3232,"question":"معاملة غير المسلمين بالغش؟","title":"حكم الغش في معاملة غير المسلمين","answer":"الجواب: لا يغش المسلمين ولا غير المسلمين، حتى الكفار لا يغشهم.","link":"https://binbaz.org.sa/fatwas/23395/حكم-الغش-في-معاملة-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم معاملة غير المسلمين بالغش.mp3","categories":["الربا والصرف","البيوع"]},{"id":3235,"question":"تشترط كثير من المحلات شرطًا يُكتب في الفاتورة: البضاعة لا تُرَدّ ولا تُسْتَبْدَل؟","title":"حكم شرط البائع \"البضاعة لا تُرَدّ ولا تُسْتَبْدَل\"","answer":"الجواب: هذا ما هو صحيح، تُرَدّ وتُسْتَبْدَل إذا وجد ما يقتضي ذلك، إذا وجد غشٌّ تُرَدّ ولا تُسْتَبْدَل، هذا كذب.\nس: لكن إذا قَبِل به المشتري يلزمه؟\nالشيخ: إذا قبله ووجد عيبًا له الرد...، إذا وجد عيبًا خدعوه به، له الرد، أما إذا كان ما في عيب يلزمه، لو جئت السيارة قلت: والله ما أعلم فيها \"عيب\" واشترى.. يلزم البيع. لكن ثبت أنه غاشّه له الخيار.\nس: يكون هذا الشرط باطلًا؟\nالشيخ: ما هو باطل، لكن ما يَمْنع، ما يمنع الرجوع فيه إذا وجد عيبًا يعلمه البائع وستره خَدَعَه به، أما إذا قال ما أعلم بها عيبًا واشترى.... يلزمه البيع.","link":"https://binbaz.org.sa/fatwas/23398/حكم-شرط-الباىع-البضاعة-لا-ترد-ولا-تستبدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم شرط المحلات التجارية البضاعة لا ترد ولا تستبدل.mp3","categories":["الربا والصرف","البيوع"]},{"id":3267,"question":"الذي يتعاون مع أهل الرِّبا كمُوَرِّد لهم هل يدخل في اللعن؟","title":"هل يدخل في اللَّعن مَنْ يتعاون مع أهل الربا؟","answer":"الجواب: يدخل في قوله جل وعلا: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] الله جل وعلا حذّر عباده من التعاون على الإثم والعدوان على الرّبا، وعلى السرقة، وعلى قطع الطريق، وعلى الغش في المعاملات، وعلى كل ما يضر الناس، والذي يعينهم على عمل الرّبا يجلب لهم السلع التي يستعينون بها في الربا يُخشى عليه من هذا، وإن كان ما أكل لكن يُخشى عليه؛ لأن الأثمان التي يأخذها منهم تدخل في أكله.","link":"https://binbaz.org.sa/fatwas/23431/هل-يدخل-في-اللعن-من-يتعاون-مع-اهل-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل في اللعن من يتعاون مع أهل الربا.mp3","categories":["شروح الحديث","الربا والصرف"]},{"id":3459,"question":"يسأل بعض الإخوة الحاضرين يقول: أنا موظف في كهرباء الخرج ومُجبر على ترك حساب في أحد البنوك، ولكن حسابي بدون فائدة يسمى حسابي \"دائم\"، والبنك يأخذ خدمات بنكية اثنين ونصف في المائة؟","title":"حكم الإيداع في البنك الربوي للضرورة","answer":"الجواب: إذا كان ما في ربا، ودعت الضرورة للإيداع؛ لا بأس بدون ربا. لكن الإيداع عند غيرهم أحوط، المحرمُ الرِّبا.","link":"https://binbaz.org.sa/fatwas/23636/حكم-الايداع-في-البنك-الربوي-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإيداع في النبك الربوي للضرورة.mp3","categories":["الربا والصرف","البيوع"]},{"id":3461,"question":"شخص يقول: لدي محل تجاري، وأضع فيه جوائز للزبائن، ولكني أشتري هذه الجوائز قبل وضع الدعاية، أي لا أشتري هذه الجوائز من مال الزبائن، فهل يصح عملي هذا أم لا؟","title":"حكم وضع الجوائز لزبائن المحلات","answer":"الجواب: ينبغي ترك هذا؛ لأنه قد يؤذي من حوله، يعطيهم جوائز حتى يرغّبهم في الشراء منه، ويعطّلون الناس الآخرين، فالأحوط ترك ذلك، ويكون مثل الناس.","link":"https://binbaz.org.sa/fatwas/23638/حكم-وضع-الجواىز-لزباىن-المحلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع الجوائز لزبائن المحلات.mp3","categories":["الربا والصرف","البيوع"]},{"id":3467,"question":"لو أن الإنسان أراد أن يعقد عقدًا بين بعض الناس، وهم يريدون أن يشرطوا عليه شرطًا باطلًا، فأراد ألّا يخبرهم حتى يمضي العقد ثم يقول: الشرط باطل، يصح ذلك؟","title":"هل يجوز إتمام العقد وفيه شرط باطل؟","answer":"الجواب: لا، يعلّمهم، ما يتم الشرط، يعلّمهم أن الشرط باطل، لا يعقد لهم، يبيّن لهم، لا يغشهم.\nس: جاء في الحديث هذا....... ؟\nالشيخ:.... يعلمهم، الرسول ﷺ علّمهم، قال: علّميهم، وأخبريهم أن العقد باطل، أنه لا بأس أن تشتريها والولاء لها إنما الولاء لمن أعتق.\nس: في بعض الروايات أنه قال لعائشة: اشتريها، واشترطي الولاء؟\nالشيخ: لأنه بلّغهم، ما دام بلّغوا، يعني من باب النكال لهم، والتثريب عليهم، يعني: اشترطتم أو لم تشترطوا قد بُلّغتم أنه لا يجوز.","link":"https://binbaz.org.sa/fatwas/23644/هل-يجوز-اتمام-العقد-وفيه-شرط-باطل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العقد إذا كان فيه شرطا باطلا.mp3","categories":["الربا والصرف","البيوع"]},{"id":3665,"question":"التدين (الاقتراض) للزوجة الثانية والثالثة؟","title":"حكم من يستدين ليتزوج الثانية والثالثة","answer":"الجواب: ما في بأس، إذا كان له وفاء لا بأس، يتدين ويتزوج إذا كان له وفاء؛ يتسبب ويبيع ويشتري أو يؤجر نفسه؛ لا بأس.\nس: ويأخذ من الزكاة؟\nالشيخ: إذا احتاج لا بأس، إذا كان غارمًا أو ليس بيده شيء يُعطى من الزكاة ما يتزوج به.","link":"https://binbaz.org.sa/fatwas/23853/حكم-من-يستدين-ليتزوج-الثانية-والثالثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التدين ليتزوج الثانية والثالثة.mp3","categories":["السلف والقرض","الربا والصرف"]},{"id":3788,"question":"ولو زيد الثَّمن بالتقسيط؟","title":"حكم زيادة الثمن في البيع بالتقسيط؟","answer":"الجواب: ولو زيد نعم، لا بدّ أن يُزاد في الغالب، بيع الآجل غير بيع النقد، إذا صار الشيء يُباع بالنقد بألف، يُباع بالأجل بألفين، ثلاثة، بالآجال، الأجل يُزاد، لا حرج فيه عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/23986/حكم-زيادة-الثمن-في-البيع-بالتقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة الثمن في البيع الآجل.mp3","categories":["الربا والصرف","البيوع"]},{"id":3923,"question":"هل الجمرك حرام أو حلال؟","title":"ما حكم الجمرك؟","answer":"الجواب: الجمرك محرم، مكس، يقال المكوس محرمة لا تجوز، لكن الدول.. يقع من الدول أشياء ممنوعة، وقد يكون لهم فيها بعض التأويلات أحيانًا، فالأصل في هذا كله تحريم مال المسلم على أخيه، وإذا كان المال ممنوعًا يُمنع... وما حرم الله يُمنع، كالخمور وما حرم الله، يجب منعه.","link":"https://binbaz.org.sa/fatwas/24141/ما-حكم-الجمرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمرك وحكمه.mp3","categories":["الربا والصرف","البيوع"]},{"id":4181,"question":"المنح للأراضي الآن، وتكون فيها بيعها قبل استلامها؟","title":"هل يجوز بيع الأراضي قبل الاستلام والقبض؟","answer":"الجواب: ما يجوز هذا حتى يحوزها، يُعطى صكًّا بها ويتملكها، حتى الأراضي ليس له بيعها حتى يحوزها، يعني حتى يُعطى صكًا بذلك ويثبت الأمر، لا يصير غرر.","link":"https://binbaz.org.sa/fatwas/24438/هل-يجوز-بيع-الاراضي-قبل-الاستلام-والقبض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع قبل الاستلام والقبض.mp3","categories":["الربا والصرف","البيوع"]},{"id":4182,"question":"من يشتري السيارة ثم يبيعها قبل نقل ملكيتها؟","title":"حكم شراء سيارة ثم بيعها قبل نقل ملكيتها","answer":"الجواب: لا بدّ أن يقبضها قبضًا تامًا وينقلها من معرضه إلى محل آخر، يُتِمُّ الملكية، الرسول ﷺ نهى أن تباع السلع حيث ابتاعت حتى يحوزها التجار إلى رحالهم...  لا يشتري شيئًا إلا عن قبض تام، وعلى الطريقة التي رسمتها الدولة على حسب التعليمات تبع الدولة، لا يخالف التعليمات حتى لا يقع الغرر والخطر.","link":"https://binbaz.org.sa/fatwas/24439/حكم-شراء-سيارة-ثم-بيعها-قبل-نقل-ملكيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع السيارة قبل نقل ملكيتها.mp3","categories":["الربا والصرف","البيوع"]},{"id":4183,"question":"بيع النخل بالنخل؟","title":"هل يجوز بيع النخل بالنخل؟","answer":"الجواب: ما في بأس، بيع النخل بالنخل لا بأس.  المقصود بيع الثمرة؛ لا تباع الثمرة مفردة إلا بعد أن يطيب الثمر. أما إذا باع النخل فالثمر تبع؛  يكون للمشتري إذا كان قد لُقِّح، يعني أُبِّر.","link":"https://binbaz.org.sa/fatwas/24440/هل-يجوز-بيع-النخل-بالنخل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع النخل بالنخل.mp3","categories":["الربا والصرف","البيوع"]},{"id":4184,"question":"بعض المحلات يبيعون أشياء محرمة.. كالمجلات.. والدخان؟","title":"حكم الشراء من محلات تبيع أشياء محرمة","answer":"الجواب: تشتري منهم الشيء المباح، الشيء المباح تشتريه إذا باعوه، أشياء طيبة تشتريها، باعوا مجلات طيبة تشتريها، باعوا كتبًا طيبة تشتريها، باعوا أواني تشتريها، ولا تشتر الدخان، ولا تشتر المحرمات، تنصحهم وتنكر عليهم وتعلّمهم الخير.\nس: هناك بقالات تكون بجانبها، يعني من باب تشجيع هذه البقالات التي لا تبيع الدخان والمجلات..؟\nالشيخ: لا بأس، يشتري من هؤلاء ومن هؤلاء وإذا شجع الطيبين طيب، لكن قد يكون الذي عنده طيب غال واللي عنده الرديء رخيص أرخص، لا بأس عليه، اليهود من أكفر الناس واشترى منهم النبي ﷺ.\nس: ما يُهجرون للتأديب يا شيخ؟\nالشيخ: إذا رأى المصلحة في ذلك لا بأس.","link":"https://binbaz.org.sa/fatwas/24441/حكم-الشراء-من-محلات-تبيع-اشياء-محرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الشراء من المحلات التي تبيع أشياء محرمة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4187,"question":"الأرض التي عليها قرض، أرض قيمتها مئة ألف، وعليها قرض يجعلها مئة وثلاثين ألفًا، هل يجوز أن تباع بقرضها بالزيادة؟","title":"حكم بيع أرض عليها قرض زائد على قيمتها","answer":"الجواب: المقصود إذا كان عنده أرض اشتراها من الحكومة وأراد أن يبيعها يبيعها، إذا اشتراها من الحكومة يبيعها ويوفي الحكومة حقهم، وإن سامحته الحكومة فلا بأس، إذا كان عنده أرض وعليه للحكومة فيها مائة ألف أو أقل أو أكثر، وباعها وسدد للحكومة حقهم أو حولهم على المشتري؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/24444/حكم-بيع-ارض-عليها-قرض-زاىد-على-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع الأرض التي عليها قرض زائد على قيمتها.mp3","categories":["الربا والصرف","البيوع"]},{"id":4189,"question":"الاحتكار لغير الطعام؟","title":"حكم الاحتكار لغير الطعام","answer":"الجواب: الأقرب أنه يُمنع أيضًا، حتى غير الطعام إذا كان فيه ضرر على المسلمين؛ بجامع العلة.","link":"https://binbaz.org.sa/fatwas/24446/حكم-الاحتكار-لغير-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاحتكار لغير الطعام.mp3","categories":["الربا والصرف","البيوع"]},{"id":4190,"question":"الوكالات التجارية هل هي من الاحتكار؟","title":"هل تدخل الوكالات التجارية في الاحتكار؟","answer":"الجواب: أيش الوكالات التجارية؟\nس: يعني إنسان يحتكر نوعًا  معينًا من السيارات لا يبيعها إلا هو؟\nالشيخ: هذا فيه تفصيل، إن كان يضر الناس يمنع، وإن كان ما فيه ضرر الأمر سهل.","link":"https://binbaz.org.sa/fatwas/24447/هل-تدخل-الوكالات-التجارية-في-الاحتكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الاحتكار الوكالات التجارية.mp3","categories":["الربا والصرف","البيوع"]},{"id":4281,"question":"عندنا جار مؤجر لواحد يبيع شيشة وكلمناه وقال: أنه مؤجر لواحد ثانٍ خمس سنين وبقى له سنة، وأجّره للثاني صاحب الشيشة وقال كلمنا شيخ وقال معليش..؟","title":"حكم تأجير المحلات لبائعي الشيشة","answer":"الجواب: لا، غلط غلط، يُعَلَّمُ الناس أن هذا لا يجوز، الله يقول: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] ينبغي لجيرانه أن يتكلموا معه وينصحوه حتى لا يعود لهذا، وإن دعت الحاجة للمحكمة يحاكمونه.\nس: يفسخ العقد؟\nج: إما يفسخ العقد أو يرفعونه إلى المحكمة؛ لعلها تعينهم على هذا.","link":"https://binbaz.org.sa/fatwas/24551/حكم-تاجير-المحلات-لباىعي-الشيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تأجير المحلات لمحلات الشيشة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4766,"question":"يقول ما الحكم في البيع بعد الأذان عند المساجد؟","title":"حكم البيع بعد الأذان عند المساجد؟","answer":"لا يصح البيع بعد أذان الجمعة - الأذان الثاني - عند دخول الخطيب، أما غيره فتركه أولى، الصلوات الأخرى تركه أولى؛ لعدم ورود شيء في ذلك، إذا أذن يبادر بالسعي إلى الصلاة ولا ينبغي له أن يتشاغل ببيع ولا غيره بعد الأذان، لكن النص إنما جاء في صلاة الجمعة؛ لضيق وقتها وعظم شأنها، ولأن المقصود من الصلاة حضور الخطبة، فإذا اشتغل بشيء فاتت الخطبة.","link":"https://binbaz.org.sa/fatwas/25127/حكم-البيع-بعد-الاذان-عند-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم البيع بعد الأذان عند المساجد.mp3","categories":["الربا والصرف","البيوع"]},{"id":4869,"question":"في بعض البلاد تباع الأصنام للسُّوَّاح للشيخ من غير قصد أنها تعبد، للزينة؟","title":"حكم بيع الأصنام للسُّوَّاح بقصد الزينة","answer":"تحرم.\nس: ما يكفر بهذا؟\nج: لا، ما يكفر، مثل هذا الذي يبيع الصور، الآن يبيعون صور النساء وصور الرجال.","link":"https://binbaz.org.sa/fatwas/25348/حكم-بيع-الاصنام-للسواح-بقصد-الزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بيع الأصنام للسواح بقصد الزينة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4874,"question":"إذا أعطاه أجرة على التبرع بالدم؟","title":"هل تجوز الأجرة على التبرع بالدم؟","answer":"لا ما يصلح، الرسول ﷺ نهى عن بيع الدم، ونهى عن ثمن الدم؛ فلا يأخذ شيئًا مقابله.","link":"https://binbaz.org.sa/fatwas/25360/هل-تجوز-الاجرة-على-التبرع-بالدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأجرة على التبرع بالدم.mp3","categories":["الربا والصرف","البيوع"]},{"id":4883,"question":"في شركة مضاربة يقولون: إذا أعطيتنا رأس المال لسنة نعطيك نسبة 10% من الربح، إذا تركت رأس المال معنا سنتين نعطيك 20%؟","title":"هل تجوز المضاربة على نسبة ربح معلومة؟","answer":"من الربح، أو شيء معلوم دراهم معلومة؟\nس:  يقول: من الربح، لكن تختلف نسبة الربح في زيادة السنوات؟\nج: ما في بأس، إذا كان الربح بنسبة فلا بأس، أما دراهم معلومة فلا.","link":"https://binbaz.org.sa/fatwas/25388/هل-تجوز-المضاربة-على-نسبة-ربح-معلومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المضاربة على نسبة ربح معلومة.mp3","categories":["الربا والصرف","البيوع"]},{"id":4884,"question":"بعض أهل العلم لا يفرِّق بين مسألة العِينة والتورُّق؟","title":"ما الفرق بين بيع العِينة والتورُّق؟","answer":"غلط، التورُّق غير، التورُّق أن تشتري السلعة إلى أجل معلوم وتبيعها على الناس، واللي يشتريها ما يبيعها عليك، اللي يشتريها يبيعها على الناس الآخرين، إن باعها عليك هذه العِينة، لكن إن كان باعها على غيرك ما جاءت العينة. يبيعها على غيرك، يتزوج أو يبني بيتًا أو يقضي دينًا، اشترى منه سيارة بمائة ألف ريال ثم باعها على غيره: ما فيه شيء. العِينة يبيعها عليه، أما إذا باعها على غيره فليس فيه ربا، والناس في حاجة إلى هذا.","link":"https://binbaz.org.sa/fatwas/25389/ما-الفرق-بين-بيع-العينة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين مسألة العينة والتورق.mp3","categories":["الربا والصرف","البيوع"]},{"id":4885,"question":"من قال: يجوز بيع الدين بالدين، لكن بشرط قبض العوض قبل مفارقة المجلس؟","title":"ما حكم بيع الدين بالدين؟","answer":"هذا لا بأس، مثل ما قال ﷺ: لا بأس أن تأخذها بسعر يومها، الدين بالدين كلها مؤجلات.\nس: إذا كان مؤجلًا؟\nج: لا، أما إذا كان الدين بشيء معجّل ما يسمى \"دين\".","link":"https://binbaz.org.sa/fatwas/25392/ما-حكم-بيع-الدين-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بيع الدين بالدين بشرط قبض العوض ومفارقة المجلس.mp3","categories":["الربا والصرف","البيوع"]},{"id":4890,"question":"بالنسبة لبيع رقم أرض وهو محتاج، يبيعها بسعر بخس؟","title":"ما حكم من يبيع أرضًا لم يستلمها؟","answer":"إذا كانت في ملكه وقد استوفى شروط الملك ما يوجد فيها دعوة ولا خصومة؛ يبيعها وإذا نزل؛ لأنه محتاج أن يبيعها.\nس: هو لم يستلمها بعد، استلم الأوراق.\nج: لا، ما يصح، ما بعد مَلَكها، لا يبيع حتى يملكها ويأخذ صكًّا عليها أو وثيقة.\nس: بيع الأرض بوصف منضبط؟\nج: إذا كانت موجودة.\nس: موجودة لكن بصكٍّ المشتري لم يره؟\nج: ولو، إذا وصفها، طولها كذا وعرضها كذا وصفتها كذا؛ ما في بأس، تنضبط.","link":"https://binbaz.org.sa/fatwas/25402/ما-حكم-من-يبيع-ارضا-لم-يستلمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع أرض لم يستلمها.mp3","categories":["الربا والصرف","البيوع"]},{"id":4893,"question":"بالنسبة للعربون: هل يكون من نصيب البائع لو ما كان بينهم شرطٌ بين البائع والمُشتري؟","title":"هل يكون العربون للبائع أو للمشتري؟","answer":"لا، على حسب الشروط، المسلمون على شروطهم، العربون تارةً يشترط أنه له، وتارةً أمانة، ما هو له، أمانة، إن تمَّ البيعُ وإلا أعطاه إياه، إن كان أمانةً فهو أمانة، وإن كان لا، قال: ما أسمح، ولا ...\nس: إذا كان العربون يأخذ نصف القيمة؟\nج: الذي اتَّفقوا عليه، المسلمون على شروطهم.\nس: يأخذه بدون مقابل؟\nج: المقابل تضييع الفرص، وتفرَّقوا، الناس يمكن لو دوَّر مَن يشتريها ما يحصل أحدًا، تفرَّقوا.","link":"https://binbaz.org.sa/fatwas/25408/هل-يكون-العربون-للباىع-او-للمشتري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لمن يكون العربون للبائع أو للمشتري.mp3","categories":["الربا والصرف","البيوع"]},{"id":4895,"question":"الذي يشتري ملابس بخمسين ريالًا، ويبيعها بمئةٍ وخمسين، يعني: ثلاثة أضعاف قيمتها؟","title":"هل للربح في البيع حدٌّ معين؟","answer":"إذا كان لها أسباب: ما لها سعر معلوم في الأسواق، على حسب البيع والشراء، إذا ما كان لها ربحٌ معين، ما لها سوقٌ معين، لا يخدع الناس، إن كان لها سوقٌ معينٌ وسعرٌ معينٌ لا يخدع الناس، يقول: ترى سعرها كذا وكذا، أما إذا ما كان لها سعر معين: ما أبيعها إلا بكذا وكذا، إلا بفائدة كذا؛ لا بأس.\nس: الربح ما له حدٌّ؟\nج: ما له حدٌّ، إذا كان ما له أسعار مُعينة، أما إذا كان السوقُ مُسَعَّرًا: هذا في السوق يُباع بعشرة ريالات، وأنت تقول: لا، أبيعه بعشرين تضر الناس، لا.","link":"https://binbaz.org.sa/fatwas/25410/هل-للربح-في-البيع-حد-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للربح في البيع حدٌّ معين.mp3","categories":["الربا والصرف","البيوع"]},{"id":4899,"question":"لو قال في السلم الوصف ليس منضبطًا؟","title":"ما شروط السَّلَم؟ وهل يكون حالًّا أم مؤجلًا؟","answer":"لا، هم يتفقون على أصل مضبوط وإلا ما يصح البيع، لا بدّ أن يتفرقا على شيء معلوم.\nس: ما هي شروط السلم؟\nج: مثل ما تقدم: على شيء معلوم. والشروط الأخرى في محلها، لكن إذا أسلف في شيء معلوم إلى أجل معلوم؛ فلا بأس، هذا في الذمة مما يوجد غالبًا.\nس: قول بعض الفقهاء أن العقار لا يدخل في السلم؛ لأنه لا ينضبط فيه الوصف، هل هو سليم؟\nج: العقار ما يسمى \"سلم\" يسمى بيع أعيان، إذا كان عنده عقار مضبوط يعرفه هذا بيع أعيان، ما هو بيع سلم.\nس: إذا كانت هذه السلعة تباع بألف ريال لكن رفض أن يبيعنيها إلا بألفين؟\nج: أو بثلاثة ما يخالف، أو بأربعة، إذا تراضيتم إلى أجل معلوم لا بأس.\nس: هل يجوز أن يكون السلم حالًّا؟\nج: ما يكون سلمًا إلا مؤجلًا، ما يكون حالًّا، لا يسمى سلمًا إلا مؤجلًا.","link":"https://binbaz.org.sa/fatwas/25414/ما-شروط-السلم-وهل-يكون-حالا-ام-موجلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في السَّلَم.mp3","categories":["الربا والصرف","البيوع"]},{"id":4904,"question":"بالنسبة لاستبدال القديم بالجديد في البضاعة، ويقدرونها كسيارة أو أي شيء؟","title":"حكم بيع بضاعة قديمة بجديدة مع زيادة في الثمن","answer":"ما في بأس؛ يبيعه سيارة بسيارة ويزيده، أو يبيعه بيت ببيت ويزيده، أو يبيعه أرضًا بأرض ويزيده، أو يبيعه \"بشت\" ببشت ويزيده؛ ما في بأس؛ لأن هذه أجناس ما يدخلها ربا.","link":"https://binbaz.org.sa/fatwas/25419/حكم-بيع-بضاعة-قديمة-بجديدة-مع-زيادة-في-الثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استبدال القديم بالجديد بزيادة في الثمن، هل يدخل فيها الربا.mp3","categories":["الربا والصرف","البيوع"]},{"id":5061,"question":"بعضهم يحتج يقول: \"الدخان إذا ما بعته ما يشترون مني\" هل من كلمةٍ توجيهيةٍ لهم؟","title":"حكم من يبرر بيعه الدخان بحاجته للزبائن","answer":"الجواب: هذا ما هو بعذرٍ شرعيٍّ، هذا مثل الذي يقول: \"إذا لم أضع خمرًا لم يجئني أحدٌ\"، هذا ما هو بعذرٍ، يجب عليه تقوى الله، والحذر مما حرَّم الله ولو ما جاءه ناسٌ، فالذي يكتبه الله يأتي، يضع سلعًا ينتفع بها الناس، جاؤوا أو لا، ولا يلزم أن يضع شيئًا محرَّمًا، هذا من تسويل الشيطان، ومن تلاعب الشيطان.","link":"https://binbaz.org.sa/fatwas/29349/حكم-من-يبرر-بيعه-الدخان-بحاجته-للزباىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يبرر بيعه الدخان بالحاجة للزبائن.mp3","categories":["الربا والصرف","البيوع"]},{"id":5089,"question":"سائل يقول: فضيلة الشيخ عبد العزيز، نفعنا الله بعلمك: لي أب يعمل في شركة (أرامكو) منذ ثلاثة وثلاثين عامًا، ومنذ بدايته وهو يضع نقوده في بنك الضمان الاجتماعي في الشركة، والآن انتهى من العمل، وسوف يعطونه أمواله وزيادة، أو مضاعفة، فماذا يعمل في هذه النقود؟ وهل هي ربا؟ وماذا أفعل لو أخذها، أفدنا أطال الله بقاءك؟","title":"أين تُصرف أموال الربا؟ وهل يحلُّ تملكها؟","answer":"الجواب: هذا صدر فيه فتوى من اللجنة الدائمة: أن النقود التي توضع في الشركات التي تشترط من العامل إذا دفع نقودًا من راتبه كل شهر أنه بعد خمس سنوات يعطي كذا، وبعد عشر سنوات يعطي كذا، (60%) أو (50%) أو (100%) فإن هذه الزيادة ربا؛ لأنها تنتفع بأمواله، وتنمّيها، وترابي فيها، وتعطيهم ذلك، وهذا شيء اطلعنا عليه في بعض بنود الشركات، وأنها بعد مرور خمس سنوات تعطيك (50%) مثلًا أو أقل أو أكثر، وإذا مضى عليه عشر سنوات أعطته (100%) في مقابل ما دفعه من أقساط، وهذا ربا. والذي يظهر لنا أن الواجب عليه الصدقة بها، أو صرفها في مشاريع خيرية؛ لا يأكلها؛ لأنها ربا، فيأخذ ماله الذي جمع وحصل له من الأقساط التي قدمها لهم. وأما الربا الذي أعطوه زيادة فهذه تصرف في وجوه البر وأعمال الخير، وبناء الطرق والمدارس، ودورات المياه، ومواساة الفقراء وقضاء دين المدينين، وإعطاء المجاهدين والمبتلين بالفقر في أي مكان. هذا هو الذي يجب؛ لأنه مال جاءه من غير حله، فلا يُحرق ولا يُتلف؛ ولكن يُصرف في مصارف الأموال الضائعة والأموال التي ليس لها أحد.","link":"https://binbaz.org.sa/fatwas/29992/اين-تصرف-اموال-الربا-وهل-يحل-تملكها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 09.mp3","categories":["الربا والصرف","البيوع"]},{"id":5112,"question":"سماحة الشيخ حفظكم الله، هل يجوز لي شراء أثاث بالتقسيط من بنك الراجحي؛ لأن هناك من يقول: إن الشراء بالتقسيط حرام؛ لأن فيه ربا أفيدوني؟","title":"ما حكم شراء السلع بالتقسيط من البنك؟","answer":"الجواب: لا بأس بالتقسيط، شراء سيارة أو أثاث أو ملابس أو بيت أو أرض بالتقسيط؛ لا بأس إذا كان مالكًا لها البائع، إذا كانت عند البائع مملوكة له، حائزًا لها في بيته، في ملكه، في حوشه، إذا كانت عنده قد ملكها، وحازها وباعها بالتقسيط؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/30020/ما-حكم-شراء-السلع-بالتقسيط-من-البنك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 40.mp3","categories":["الربا والصرف","البيوع"]},{"id":5146,"question":"هذا السائل يقول يا سماحة الشيخ: ما حكم التعامل مع أحد البنوك المحلية في صناديق الاستثمار، ويكون عقد بين البنك وواضع النقود في الربح والخسارة؟","title":"ما حكم التعامل مع البنوك بعقد في الربح والخسارة؟","answer":"الجواب: هذا إذا أُمِن لا بدّ أن يكون من طريق الربح والخسارة، يعني من طريق المُضاربة جزء مشاع، مثل: أن يُعطيه مئة ألف أو أكثر أو أقلّ، ويقول: اعمل فيها بالمُضاربة، فاشترِ سيارات، اشترِ عُمَلًا، وبعها، ويكون لك النصف، أو الربع، أو الخمس؛ فلا بأس. أما فائدة معينة لك: 5%، 10% فهذا هو الربا، ما يجوز، لكن إذا كان بربع الربح أو عُشر الربح يعني: 10% من الربح، أو 20%، أو النصف؛ فلا بأس. هذا يُسمَّى: المُضاربة، وهي جائزة عند جميع العلماء، لكن هل يُؤْمَنُون على هذه العملية أو يبيعون بالربا؟ هذا محل النظر، بعضهم لا يُؤمَن، وأشكّ أنَّهم يُؤْمَنُون في هذا الشيء، وهم قد اعتادوا الربا، لكن إذا كان معه أناس مأمونون فهذا طيبٌ.","link":"https://binbaz.org.sa/fatwas/30061/ما-حكم-التعامل-مع-البنوك-بعقد-في-الربح-والخسارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 82.mp3","categories":["الربا والصرف","البيوع"]},{"id":5149,"question":"هذا السائل يقول يا سماحة الشيخ: ما حكم إيداع النُّقود في البنوك الأهلية التِّجارية كحسابٍ جارٍ؟","title":"ما حكم إيداع النُّقود في البنوك كحسابٍ جارٍ؟","answer":"الجواب: إذا دعت الحاجةُ إلى هذا فلا بأس أن نفعله، ونفعل غيره من دون فائدةٍ؛ لأنَّ وضعها في غير ذلك خطرٌ، كوضعها في البيوت، أو عند إنسانٍ غير مأمون؛ ما يمكن. فوضعها في البنوك إذا دعت الحاجةُ إلى ذلك من دون فائدةٍ لا حرج فيه، وإن تيسَّر وضعها في مكانٍ آمنٍ أو بنك إسلامي وجب ذلك؛ لئلا يُساعد هؤلاء على رباهم، لكن إذا ما تيسرت الأمور ووضعها الإنسانُ في بنكٍ للحفظ لئلا تضيع عليه فهو معذورٌ للضَّرورة، والله يقول: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]، فالضَّرورات لها أحكامها، حتى الميتة تجوز عند الضَّرورة، والخنزير عند الضَّرورة، إذا اضطُرَّ إليه ولم يجد غيره. فالمقصود أنَّ هذه الأمانات والودائع في البنوك جائزة عند الضَّرورة، وإذا تيسَّر مكانٌ آخر انتقل إليه، مكان آمن، ليس ببنكٍ ربويٍّ.","link":"https://binbaz.org.sa/fatwas/30064/ما-حكم-ايداع-النقود-في-البنوك-كحساب-جار","audio":"https://files.zadapps.info/binbaz.org.sa/fatwa 85.mp3","categories":["الربا والصرف","البيوع"]},{"id":5172,"question":"هذا سؤال عن تبديل الأوراق المالية أو العملة الورقية بالعملة المعدنية، هل يجوز التَّفاضل فيه؟","title":"ما حكم التفاضل في تبديل العملة الورقية بالمعدنية؟","answer":"الجواب: ترك التفاضل أولى وأحوط، فكونه يأخذ عشرة بعشرة ومئة بمئة أحوط، وبعض أهل العلم جوَّز التفاضل؛ لأنهما مختلفتان، هذه من معدن، وهذه من ورق، ولكن الأحوط للمؤمن ترك ذلك؛ لأنها ريـال، كلها ريـال، كلها عملة واحدة، فإذا ترك التَّفاضل فهو أحوط.","link":"https://binbaz.org.sa/fatwas/30099/ما-حكم-التفاضل-في-تبديل-العملة-الورقية-بالمعدنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 124.mp3","categories":["الربا والصرف","البيوع"]},{"id":5236,"question":"ما حكم العمل في البنك بسبب الحاجة؟","title":"ما حكم العمل والإيداع في البنوك الربوية؟","answer":"الجواب: البنوك لا يجوز العمل فيها، بنوك الربا لا يجوز العمل فيها؛ لأنها تعاونٌ على الإثم والعدوان، فلا يجوز التَّعامل بها، الرسول لعن آكل الربا ومُوكله وكاتبه وشاهديه، وقال: هم سواء، فالكاتب للربا والشَّاهد عليه شريكٌ، والذي يُعينهم يكون محاسبًا أو يكون مُراسلًا أو يكون فرَّاشًا فيه إعانة لهم على بلائهم. س: والذي يُودع؟ الشيخ: ما ينبغي الإيداع، لكن إذا دعت الضَّرورة لا بأس، الضَّرورة أن يُودع خوفًا على ماله، ليس عنده مكانٌ آخر يُودع بدون فائدةٍ.","link":"https://binbaz.org.sa/fatwas/30578/ما-حكم-العمل-والايداع-في-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 39.mp3","categories":["الربا والصرف","البيوع"]},{"id":5517,"question":"يا شيخ، بالنسبة إذا عُلم أنَّ هذا التاجر رافضي، وأنَّ بضاعته معروفة عند الناس، يعني: بضاعة موجودة في الأسواق، هل يُحذر منه على أساس أنهم ما يشترون منه، ويقال للناس: لا تشتروا منه هذه البضاعة؛ حتى لا يدعمونه؟","title":"حكم معاملة المبتدع في البيع والشراء ونحوه","answer":"الجواب: هذا محل نظرٍ، الشراء والبيع من الكفرة جائز؛ النبي ﷺ اشترى من اليهود، ومات ودرعه مرهونة عند يهودي في طعامٍ لأهله عليه الصلاة والسلام، لكن يُبين له عقيدتهم؛ حتى لا يتَّخذهم أصحابًا ولا رُفقاء، أما كونه يشتري منهم إذا دعت الحاجةُ لشرائه؛ فالأمر سهل، لكن لا يُواليهم، ولا يأكل من ذبيحتهم، ولا طعامهم؛ فذبيحتهم محرَّمة. س: يا شيخ، يمكن أن يشتري من غيرهم؟ ج: أولى، لكن المقصود الحذر من المغالاة والمحبَّة، أو التَّساهل معهم، أو تمرير أعمالهم والتَّساهل فيها، ويُبين للناس كفرهم وضلالهم، وأنَّ هذه من أعمالهم: يسبُّون الصديق، ويسبون عمر، ويسبون الصحابة، ويستغيثون بأهل البيت، ويستغيثون بعليٍّ، هذا الشرك الأكبر، سبُّ الصحابة شرك مُستقل، معناه: تخوينهم، وأنهم ليسوا أهلًا ليُروى عنهم.","link":"https://binbaz.org.sa/fatwas/31450/حكم-معاملة-المبتدع-في-البيع-والشراء-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 032.mp3","categories":["الربا والصرف","البيوع"]},{"id":5596,"question":"هل البيع في غير يوم الجمعة جائز بين الأذان والإقامة؟","title":"حكم البيع بين الأذان والإقامة في غير الجمعة","answer":"الجواب: ينبغي تركه؛ لأنه قد يعوقه عن الصلاة، ولكن النص في الجمعة، ولكن غير الجمعة ينبغي أن يتركه؛ حتى لا يعوقه عن الصلاة، الأولى والأحوط له ترك ذلك، وإن كان النص في الجمعة، لكن الأحوط للمؤمن ترك ذلك، إذا نودي للصلاة: الظهر أو العصر أو المغرب أو العشاء؛ لأن الصلوات متقاربة في المعنى، كلها فريضة، كلها يجب السعي لها، فالنص على الجمعة يدل على عظم شأن الجمعة، ولكن لا يمنع من كون غيرها كذلك، كون المؤمن يتحرى فإذا أذَّن بادر هذا هو الأحوط للمؤمن.[1]","link":"https://binbaz.org.sa/fatwas/31560/حكم-البيع-بين-الاذان-والاقامة-في-غير-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 037.mp3","categories":["الربا والصرف","البيوع"]},{"id":5637,"question":"الذي يعمل في البنك هل هو ملعون؟","title":"من يعمل في البنك هل هو ملعون؟","answer":"الجواب: يدخل في هذا، آكِل الربا وموكله وكاتبه وشاهده، الكاتب والشاهد لأنهم مساعدون على الباطل، والله يقول: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] هكذا الموظفون الآخرون. س: هذه من الكبائر؟ الشيخ: من الكبائر نعم، المعاصي التي يُلعن صاحبها من الكبائر، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31638/من-يعمل-في-البنك-هل-هو-ملعون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 006.mp3","categories":["الربا والصرف","البيوع"]},{"id":5676,"question":"ما حكم من بدل ذهبًا ملبوسًا بذهب جديد، ودفع الفرق؟","title":"حكم تبديل الذهب بذهب مع دفع الفارق","answer":"الجواب: لا يجوز هذا؛ لا بدّ يشتري الذهب الجديد مستقلًا، ثم يبيع الذهب القديم، أو الردئ مستقلًا، مثل ما قال النبي ﷺ في التمر لما قال له بلال: إنا اشترينا صاعًا من التمر الطيب بصاعين من التمر الرديء، فقال: أوه أوه عين الربا، لا تفعل، بل بع بالدراهم، ثم ابتع بالدراهم جديدًا. وهكذا صاحب الذهب الرديء مع الذهب الطيب، يبيع الذهب الرديء أولًا لأخذ الثمن، ثم يشتري به ذهبًا جديدًا، أم يبيع هذا بهذا وزيادة لا؛ لأنه يتقابل ذهب بأقل من ذهب، النبي -عليه الصلاة والسلام-: الذهب بالذهب مثلًا بمثل، سواء بسواء، وزنًا بوزن فلا بدّ أن يبيع الذهب بالذهب وزنًا بوزن، سواء بسواء.","link":"https://binbaz.org.sa/fatwas/983/حكم-تبديل-الذهب-بذهب-مع-دفع-الفارق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_12.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":5777,"question":"ما حكم العمل في القضاء الذي يحكم بالقوانين الوضعية؟ وكذلك العمل في البنوك الربوية الذي إذا تركها تمكن منها غير المسلمين؟","title":"حكم العمل في البنوك الربوية والقضاء بالقوانين الوضعية","answer":"الجواب: هذا لا يجوز، يجب منع الربا، وعدم الموافقة عليه، والاجتهاد في تطبيق أحكام الله الشرعية في البنوك وغيرها، وهذا يجب على الدول الإسلامية أن تعنى بهذا، وأن تسير البنوك، والمصارف على حكم الله  وأن تبذل الوسع في ذلك حتى تستقيم البنوك في البلاد الإسلامية على شريعة الله، وأن تمنع الربا منعًا باتًا. وهكذا القوانين الوضعية يجب أن تمنع إلا ما وافق منها شرع الله  فيجب على الدول الإسلامية أن يحكموا كتاب ربهم، وسنة نبيهم، وأن يحذروا السير مع أعداء الله في تحكيم القوانين الوضعية التي تخالف شرع الله. هذا من أهم الواجبات عليهم، وليس لهم عذر في ذلك، بل يجب عليهم وجوبًا قطعيًا أن يحكموا شريعة الله، إن كانوا صادقين في دعواهم الإسلام، عليهم أن يحكموا شريعة الله، وعليهم أن يجتهدوا أيضًا في تسيير المصارف على النهج الإسلامي، ومنع المعاملات الربوية، وأن يستعينوا بأهل العلم في ذلك، حتى يضعوا ما ينبغي وضعه للسير عليه في البنوك، وفي غير البنوك من الأشياء التي يتعاطاها الناس، وهي مخالفة للشرع والله المستعان. س:... الشيخ:  هذا معصية عظيمة، وكبيرة، وإذا استحلها كفر، من استحل الربا كفر، من استحل الحكم بغير ما أنزل الله كفر. أما إذا فعلها للهوى وهو يعلم أنه مخطئ عاصٍ أنه ظالم لا يكفر بهذا، يكون عاصيًا ومرتكبًا كبيرة عظيمة، نسأل الله العافية. وعلى المسلم أن يتقي الله، وأن ينصح إخوانه، وأن يوجههم إلى الخير. السؤال: ... موظف في البنك؟ الجواب: لا يعمل، لا يتعاون معهم على الإثم والعدوان.\n\nالسؤال:...  الشيخ: الله يقول: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] والله ولي عباده.","link":"https://binbaz.org.sa/fatwas/1103/حكم-العمل-في-البنوك-الربوية-والقضاء-بالقوانين-الوضعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_109.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":5838,"question":"ما هو حكم الإسلام فيما ذهب إليه الشيخ محمد عبده في إحلال الربا، وإلغاء تعدد الزوجات؟","title":"الرد على من يحل الربا ويمنع تعدد الزوجات","answer":"الجواب:  إحلال الربا أمر خطير لا يحل الربا إلا كافر، لكن من قال: إنه يحل الربا؟! من قال: إنه يمنع تعدد الزوجات؟! هذا يحتاج إلى مراجعة كتبه، ولا علينا من الأشخاص، إنما علينا من الحكم، حكم الله -جل وعلا- أما الأشخاص فكل يخطئ ويصيب، كل يغلط إلا من عصمه الله، وعافاه، وإلا فبنو آدم معرضون للخطأ، والأغلاط. ومحمد عبده له أغلاط، وغيره له أغلاط، لكن المقصود أن الربا لا يجوز إحلاله من الناس أبدًا، ومن أحله عن عمد، وعن بصيرة يعلم أنه ربا، ثم يحله، يعاند الله، ويخالف أمر الله؛ فيكون كافرًا -نعوذ بالله- كالذي يحل الزنا، أو يحل الخمر؛ يكون كافرًا. أما إذا غلط، واجتهد في بعض أنواع الربا، ورأى أن هذا جائز لأجل كذا وكذا، وشبه عليه؛ فهذا له حكم المجتهدين، إن أصاب؛ فله أجران، وإن أخطأ؛ فله أجر. وكذلك تعدد الزوجات كثير من المستشرقين النصارى، وغيرهم من اليهود، وغيرهم كتبوا في ذلك، وانتقدوا الإسلام! وانتقدوا الشريعة في تعدد الزوجات! وهم الغالطون، وهم المنتقدون، وهم الضالون، وكثير منهم يعرف ذلك، ولكن العناد، والحسد، والبغي، وإلا فكثير منهم يعرف أن ما جاءت به الشريعة من تعدد الزوجات هو الحق، وهو الحل لمشاكل الناس، وقد كتب في ذلك منصفوهم من رجال ونساء، واعترفوا أن ما جاء به الإسلام من التعدد هو الحق والهدى، وهو الطريق لإنقاذ البشرية مما وقعت فيه من الفساد في الأخلاق، ولكنهم يجحدون هذا في بعض الأحيان، إما خوفًا من رؤسائهم، وكبرائهم، وإما لأجل متاع يأخذونه من هناك، فيخافون أن يضيع عليهم، وإما لحسد المسلمين، والبغي على المسلمين، والعدوان على المسلمين -نعوذ بالله- هذه طريقة الكفرة، وإلا فالمنصفون منهم يعلمون أن تعدد الزوجات فيه مصالح كثيرة، وفيه خير كثير، وهو من أسباب حل المشاكل القائمة في العصر، من كثرة السفاح، والزنا، والفواحش. وكثير من هؤلاء النصارى الذين يزعمون أن التعدد منكر يتخذ زوجة واحدة، ويتخذ معها عشرات الخدينات، والمسافحات، فأي فرق بين هذا وهذا؟! المسلم يأخذ زوجات مسلمات، يأخذ زوجات أحلهن الله له، وأولئك يأخذون مسافحات، زانيات، فاجرات، فرق بين المسلم وبين هؤلاء، فالمسلم في خير عظيم إذا تزوج ثنتين، أو ثلاثًا، أو أربعًا على شرع الله، قد أباح الله له ذلك، وإن عدل فهو على خير عظيم، وأولئك الجهلة الظالمون ينتقدون الإسلام في تعدد الزوجات، وهم -والعياذ بالله- يتمتعون بالزانيات، والفاجرات بلا عدد يحصر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1173/الرد-على-من-يحل-الربا-ويمنع-تعدد-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_171.mp3","categories":["الربا والصرف","زكاة النقدين","قضايا المرأة","شروح الحديث"]},{"id":5865,"question":"ما هو حكم تعدد الزوجات؟ هل هو أصل، أو رخصة؟ وما هي الضرورة التي تنطبق عليها هذه الرخصة إذا كانت رخصة؟","title":"هل تعدد الزوجات أصل أم رخصة؟","answer":"الجواب:  تعدد الزوجات قربة، وطاعة، وليست مجرد رخصة، تعدد الزوجات قربة، وطاعة، وعمل صالح في تكثير الأمة، وفي عفة الرجال، والنساء، وفيه القضاء على أسباب الفساد، والسفاح، قال الله -جل وعلا-: وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ [النساء:3] فأمر به -جل وعلا- أمر بالنكاح مثنى، وثلاث، ورباع، ونبينا ﷺ تزوج تسعًا من النساء، مات عن تسع من  النساء، وتزوج مع ذلك امرأتين سابقتين، وعنده جاريتين، عليه الصلاة والسلام. فالمقصود: أن تعدد النساء أمر مطلوب مع القدرة عليه، ومع العدالة في ذلك، فإذا كان قادرًا، وعادلًا؛ فمشروع له أن يعدد حتى يكثر الأمة، وحتى يكون أعف لفرجه، وأعف لبصره، وحتى يعف من النساء من يسر الله له إعفافها، وحتى يكثر بسبب ذلك النسل، والأمة.  والنبي -عليه الصلاة والسلام- قال: تزوجوا الودود الولود، فإني مكاثر بكم الأمم يوم القيامة وفي لفظ: مكاثر بكم الأنبياء يوم القيامة فإكثار من يعبد الله في الأرض وهو يصلح في الأرض، ويقوم بالخلافة للرسل فيما دعوا إليه هذا خير عظيم، ونسأل الله أن يوفق المسلمين للهدى، والصلاح، والزوجات الصالحات، والأزواج الصالحين.  فإذا وجد الزوج الصالح، والزوجة الصالحة؛ فهو خير كثير، ومصلحة عظيمة، ولا يخفى أن الناس قد يبتلون بحروب، وأمراض، وغير ذلك، فتعدد الزوجات فيه مصالح كثيرة: الزوج يعف الله به فرجه، ونظره، فإن المرأة تبتلى بالمرض، وتبتلى بالحيض، والنفاس، تبتلى بأشياء تمنع الرجل من التمتع بها، فإذا كان عنده ثانية، وثالثة، ورابعة؛ انتفع بهذه، وهذه، وهذه في قضاء وطره، وفي عفة فرجه، وفي غض بصره، وهكذا النساء قد يبتلين بالفقر، قد يبتلين بالحروب، فإذا كان تحت زوج يقوم عليها، ويحسن إليها، ويعفها، ويحميها ربع زوج، أو ثلث زوج، أو نصف زوج خير لها من عدم ذلك. فالمصالح في هذا كثيرة مع العدالة، ومع الاستقامة، ومع تقوى الله، ومع النصح، ففي هذا خير كثير، أما مع الظلم، والعدوان لا يجوز ذلك، لكن يجوز، ويشرع مع العدالة، والاستقامة، والإنصاف من الزوج لهن، والعدل بينهن في الإنفاق عليهن، وفي جميع شؤونهن، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1186/هل-تعدد-الزوجات-اصل-ام-رخصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_181.mp3","categories":["قضايا المرأة","ردود وتعقيبات","الربا والصرف","تعدد الزوجات"]},{"id":5987,"question":"رجل أودع مالًا في بنك من البنوك الربوية آجل، ويقول له لما استلم رأس ماله، أعطاه ربح، فهو حيران في الربح هذا أيش يعمل؟","title":"حكم إيداع المال في البنوك وأخذ الزيادة","answer":"الجواب: البنوك الربوية لا يودع فيها إلا عند الضرورة، فإذا أودع عندهم للضرورة؛ فلا يأخذ الربح، لا يأخذ الفوائد؛ لأنها ربًا، ولا يحل له أن يأخذ الربا. ولكن بعض أهل العلم قالوا: إذا أخذ الفائدة التي ما اشترطها، ولا اتفق معهم عليها، ولكن قالوا: هذه الفائدة لك، إذا أخذها، وصرفها في جهة بر لمواساة فقير، أو إصلاح طريق، أو ما أشبه ذلك من شيء ينفع المسلمين، ولا يأكلها، ولا يخلطها بماله، بل يصرفها في وجه البر، قال بعض أهل العلم: إن  هذا لا بأس به؛ لأجل مصلحة المسلمين؛ ولئلا يأخذها النصارى، وغيرهم، فيصرفونها في معاصي الله، هذا قاله بعض أهل العلم.  .. إذا أخذه، واحتاط، وصرف ذلك في جهة البر، وهو لم يشارطهم، ولم يرض بذلك؛ فهذا له وجه، أما أن يتفق معهم على الربا، أو يأخذ الربا لنفسه، أو لماله، أو يخلطه بماله، فهذا لا يجوز. السؤال: وإن كان عن جهل يا شيخ؟ الجواب:  ولو عن جهل، لا يأخذه.  السؤال: وبعدين أخذه؟ الجواب:  يتصدق به على الفقراء، والمساكين.","link":"https://binbaz.org.sa/fatwas/1364/حكم-ايداع-المال-في-البنوك-واخذ-الزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_322.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":6024,"question":"رجل وضع مبلغًا من المال في بنك من البنوك على سبيل الوديعة، بدون فائدة، ولكنه اكتشف فيما بعد أن هذا البنك يعمل، ويشتغل في مشاريع محرمة؟","title":"حكم إيداع الأموال في البنوك الربوية بدون أخذ فائدة","answer":"الجواب: ينبغي حفظ الأموال، وأن لا تودع في البنوك التي ترابي مهما أمكن، لكن إن اضطر إلى ذلك جعلها عند البنك ليحفظها فقط، ولا يرضى بالربا، ولا يريد الربا، ولا يأخذ الفائدة، فأرجو ألا يكون عليه حرج؛ للضرورة، لحفظ الأموال في البنوك الآن؛لأن بعض الناس لو وضع في بيته؛ يخشى عليه الذهاب، والسرقة. فالحاصل: أنه إذا كانت الضرورة جعل المال فيها للضرورة، ولا يريد فائدة من ذلك؛ فلا شيء عليه. السؤال: والراجحي؟ الجواب: الراجحي ما نعلم فيه، لا بأس، الراجحي، والسبيعي، وأشباههم ما نعلم فيه شيء، ما نعلم إلا خيرًا.","link":"https://binbaz.org.sa/fatwas/1374/حكم-ايداع-الاموال-في-البنوك-الربوية-بدون-اخذ-فاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_332.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":6101,"question":"ما حكم أخذ الفوائد من البنوك الربوية، وصرفها في وجوه خيرية؟","title":"حكم أخذ الفوائد الربوية وصرفها في وجوه خيرية","answer":"الجواب: لا يجوز للمسلم أن يتفق مع البنوك، ومع غيرها على فوائد؛ لأنها ربا، فالذي أودع عندهم مالًا يودعه على أنه ليس له فائدة، بل لحفظه عند المودع، أو ليتصرف فيه المودع، ويعتبره قرضًا عنده، ثم ...على الحساب الجاري يأخذ حاجاته، ولا يأخذ له فوائد، أما الاتفاق معهم على فوائد فلا يجوز، ولو قال: إنه يصرفها في وجوه خيرية، أو المشاريع الخيرية لا يجوز له هذا. لكن لو قدر أنه جهل هذا الأمر، وقبضها، وما درى، وهو يحسب أنه جائز؛ فإنه لا يردها إلى البنك، ولا يردها إلى المصرف، بل تصرف في الفقراء، والمحاويج، ومثل إصلاح الطرقات، ومثل إصلاح مشاريع تنفع المسلمين ... يشرب منها الناس، أو طرق ينتفع بها الناس، مثل مهر البغي، ومثل حلوان الكاهن، ومثل المكوس التي أخذتها الدولة، ثم هداها الله، وتركتها تصرف في الوجوه الخيرية التي تنفع المسلمين، ومثل المال الضائع الذي ذهب صاحبه، ولم يعرف، وأشباه ذلك لا ترد إلى أصحابها.  وهكذا من أعطاه الكاهن من المال لإخباره بعض المغيبات، ليس له أن يأكله، ولا أن يعيده إلى صاحبه، بل يصرف في وجوه الخير من مواساة الفقير، والمسكين ونحو ذلك، ومثل هذا مهر البغي ما تعطاه المهر لأجل الزنى حرام عليها -نعوذ بالله- لكن لا ترده إلى صاحبه إذا أخذته، لا ترده، ولكن يصرف في جهة أخرى كمواساة الفقير، ولا يخبر أنه كذا وكذا، فهو بالنسبة إلى الفقير، ونحوه حل له؛ لأنه مال ضائع، مال لا صاحب له، لكن الذي أخذه بوجه محرم، فلا يستعمله، وإذا صرفه لفقير، ومسكين حل له؛ لأنه بمثابة المال الضائع الذي يصرف في جهة خيرية تنتفع به.","link":"https://binbaz.org.sa/fatwas/1516/حكم-اخذ-الفواىد-الربوية-وصرفها-في-وجوه-خيرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_446.mp3","categories":["الربا والصرف","قضايا معاصرة"]},{"id":6139,"question":"هل يجري الربا في غير المطعوم، والذهب، والفضة مثل: رجل يبيع سيارة بسيارتين، وكتابًا بكتابين، وشاة بشاتين؟","title":"جريان الربا في غير المكيلات والموزونات","answer":"الجواب:  لا، هذا ما هو من الربا، الربا في المطعومات .. مما يكال، ويدخر، وفي الموزونات المعتادة المعروفة، أما بيع السيارة بسيارتين، أو سيارة بإبل، أو سيارة ببيت، أو بأرض، أو سيارة بغنم، أو غنم بإبل، لا شيء، لا حرج في هذا.","link":"https://binbaz.org.sa/fatwas/1604/جريان-الربا-في-غير-المكيلات-والموزونات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_498.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6145,"question":"أرجو شرح هذه العبارة (شروط النسيئة قبض أحد العوضين المتفاضلين الربويين قبل التفرق) وهل هذا الشرط لتجنب الوقوع في ربا النسيئة، أم هو شرط محرم، أفتونا جزاكم الله؟","title":"شروط بيع الربوي بمثله","answer":"الجواب:  هذا بينه الرسول ﷺ ربا الفضل محرم، مطلقًا في ربا الفضل، وفي ربا النسيئة إذا باع جنسًا بجنسه متفاضلًا؛ صار محرمًا بهذا الشيء، وإذا صار إلى أجل، وهو من جنس واحد؛ اجتمع فيه المعنيان ربا الفضل، وربا النسيئة. فشرط بيع الجنس من جنسه يدًا بيد إذا كان جنسًا بجنس متماثلًا؛ فلا بدّ أن يكون يدًا بيد، وإن كان من غير جنسه متفاضلًا؛ فلا بدّ أن يكون يدًا بيد، فهذا شرط للحل، والإباحة. لا يباع الجنس بغير جنسه مما اجتمع معه الوصف في العلة إلا بشرط التقابض، فإذا باع ذهبًا بفضة؛ فلا بد من التقابض يدًا بيد، أو باع تمرًا بشعير؛ فلا بدّ يد بيد، وإلا حرم ذلك؛ لأنه يصير في حكم النسيئة، وأعظم الربا ربا النسيئة، فإذا لم يتقابضا؛ ألحق بربا النسيئة؛ فحرم. فالله -جل وعلا- حرم النسيئة، فإذا لم يتقابضا؛ فهو ملحق بالنسيئة، وهو وسيلة إلى النسيئة، فلهذا حرم الله -جل وعلا- التفرق قبل التقابض، فلا يجوز بيع الربا بالربوي من جنسه، أو من غير جنسه متفاضلًا إلا يدًا بيد .. سواء كان من جنسه الذهب بالذهب، الفضة بالفضة، والتمر بالتمر، لا بدّ أن يكون يدًا بيد مع شرط التساوي، والتماثل، وإن كان بغير جنسه كالتمر بالشعير، والتمر بالملح، والذهب والفضة؛ فإنه يجوز التفاضل، لكن لا بدّ من يد بيد؛ حتى لا يلتحق بالربا.","link":"https://binbaz.org.sa/fatwas/1600/شروط-بيع-الربوي-بمثله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_494.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6151,"question":"ما حكم التأمين على الأموال المستوردة من الخارج؟ كذلك التأمين على الأموال في المخازن ضد الأخطار، والتلف نظير مبلغ يأخذه المؤمن، ويضمنها في حالة التلف أليس هذا من الغرر؟","title":"حكم التأمين على الأموال المستوردة","answer":"الجواب:  التأمين من عقود الغرر من عقود الربا، وهو محرم، سواء كان على الأموال، أو على الصحة، أو على غير ذلك، فالعقود التأمينية محرمة، وإن فعلها الناس ففي هذا الغرر، والربا.","link":"https://binbaz.org.sa/fatwas/1601/حكم-التامين-على-الاموال-المستوردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_495.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6190,"question":"أفيد سماحتكم أنني مساهم في البنك الأمريكي، وهو يتعامل بالربا، وعندما علمت ذلك؛ سحبت بعض الأسهم التي تخصني، وفيها بعض النقود من سبب الربا؟","title":"كيفية التصرف بالأموال الربوية","answer":"الجواب: المساهمة في البنوك الربوية لا تجوز، المساهمة في البنوك لا تجوز؛ لأنها تعامل بالربا، والمساهمة فيها من باب التعاون على الإثم، والعدوان. وإذا جاءه ربح من سهمه؛ فينبغي له أن يتصدق بهذا الربح، ولا يجعله من ماله، بل يخرجه في وجوه البر، كمواساة بعض الفقراء، والمساكين، أو إصلاح دورات مياه، أو ما أشبه ذلك مما ينفع الناس، ولا يجعله من ماله.","link":"https://binbaz.org.sa/fatwas/1677/كيفية-التصرف-بالاموال-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_551.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6205,"question":"أفيد سماحتكم أنني مساهم في البنك الأمريكي، وهو يتعامل بالربا، وعندما علمت ذلك؛ سحبت بعض الأسهم التي تخصني، وفيها بعض النقود من سبب الربا؟","title":"كيفية التصرف بالأموال الربوية","answer":"الجواب: المساهمة في البنوك الربوية لا تجوز، المساهمة في البنوك لا تجوز؛ لأنها تعامل بالربا، والمساهمة فيها من باب التعاون على الإثم، والعدوان. وإذا جاءه ربح من سهمه؛ فينبغي له أن يتصدق بهذا الربح، ولا يجعله من ماله، بل يخرجه في وجوه البر، كمواساة بعض الفقراء، والمساكين، أو إصلاح دورات مياه، أو ما أشبه ذلك مما ينفع الناس، ولا يجعله من ماله.","link":"https://binbaz.org.sa/fatwas/1677/كيفية-التصرف-بالاموال-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_551.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6316,"question":"هناك نوعان من البيع والشراء تشكك الناس اليوم في صحتهما، نرجو توضيح الحكم فيهما، جزاكم الله خير الجزاء، أولاً: ما يجري الآن في سوق الجفرة بالرياض الذي لا يخفى على أحد من الاقتراض بزيادة، ثانيًا: التجارة الحديثة في البورصات الدولية، لاسيما وقد كثر المتعاملون فيها هذه الأيام من خلال البنوك الدولية المفتوحة حديثًا في المملكة.","title":"حكم الاقتراض بزيادة والتعامل في البورصة","answer":"الجواب: أما القرض بزيادة فهذا لا يجوز، كونه يقول: أعطني خمسة، وأعطيك ستة سبعة، أو أقرضني ألفًا، وأعطيك ألفًا، وعشرين، أو ألفًا، وثلاثين، أو ألفًا، وأربعين، كما تفعل البنوك، وغير البنوك، هذا منكر، وهذا من الربا المحرم بلا شك، كونه يقترض مالًا بالزيادة، ولو قليلة، فهذا لا يجوز. وله حيلة، وطريقة شرعية -بحمد الله- تغنيه عن هذا، يشتري إذا كان مضطرًا، يشتري سلعة إلى أجل، ويبيعها على اختياره، يشتري السلعة من زيد، أو عمرو من التاجر، ويقبضها، ويحوزها، ثم يتصرف فيها على مهله، يبيعها على مهلة بالنقد، ويقضي حاجته. وبعض الناس في هذا يغلط أيضًا، يشتري من إنسان ما عنده سلعة، يشتري منه، ثم يروح يشتريها من الثاني، لا، لا تشتري سلعة إلا وهي مملوكة لمن باعها، قد حازها في دكانه، في بيته، ثم يبيع عليك، ثم أنت إذا اشتريتها تحوزها أيضًا، وتنقلها إلى بيتك، أو إلى السوق، ثم تبيعها بعد ذلك على من يسر الله، وتقضي حاجتك، والزيادة التي عليك بالأجل سوف يسهل الله -جل وعلا- النبي ﷺ يقول: من أخذ أموال الناس يريد أداءها؛ أدى الله عنه.  ومن استدان لقصد حاجة للزواج، أو لقضاء دين، أو للإنفاق على عياله سوف يقضي الله عنه إذا صلحت نيته، سوف يقضي الله عنه، ويوفي عنه، والله أباح المداينة  إلى أجل، فلا بأس أن تستدين من إنسان عنده المال، في حوزته المال، تشتري منه المال بحوزته، ثم تنقله، وتقبضه ثم تبيع على مهلك، تبيع المال مرة واحدة، أو أجزاء تبيع، وتقضي حاجاتك، أما أن تقترض من البنك، أوغير البنك بالربا، الألف بألف بخمسمائة ألف ومائة، المائة ألف بمائة ألف وخمسة آلاف زيادة، كل هذا ربا لا يجوز، ولو مائة بمائة ونصف ريال، ما يجوز الزيادة، لا تصلح. وأما البورصة فقد بلغنا عنها أنها بيع في الهواء، بيع لا فيه قبض، ولا فيه شيء، فهو منكر، ومحرم، يتبايعون بالمكاتبات، ويبيع بجميع أنواع المكاتبات، من برقية، ومن لبس، ومن غير ذلك، أموال لا قبضوها، وهذا يبيع، وهذا يبيع، وهي موجودة عند أهلها، هذا منكر، وهي بيوعات باطلة، لا تصلح، لكن حب المال، وكثرة المال بين الناس ما وجدوا له مكانًا إلا هذا التصرف، نسأل الله السلامة!.","link":"https://binbaz.org.sa/fatwas/1873/حكم-الاقتراض-بزيادة-والتعامل-في-البورصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_662.mp3","categories":["الربا والصرف","البيوع","الآداب والأخلاق"]},{"id":6322,"question":"كثير من المبتعثين خارج المملكة لهم أموال في بنوك الكفار، وعند استلامهم لهذه الأموال، يسلمون معها أرباحًا ربوية، فهل تعطى للمسلمين، أم تترك للكفار؟","title":"حكم أخذ الأرباح التي تعطيها البنوك الربوية في بلاد الكفر","answer":"الجواب: هذا فيه خلاف بين علماء الإسلام، يعني كون المسلم يقبض مع أمواله أرباحًا من البنوك، يعطى إياها؛ لأن البنوك اعتادت أنها تعطي أرباحًا على الأموال التي عندها في بنوكها، فهل للمسلم أن يأخذ هذه الأرباح، وينفقها في وجوه البر، وأعمال الخير، أم يتركها لهم، ويأخذ رأس ماله؟ هذا محل نزاع بين أهل العلم، هل يجوز، أم لا يجوز؟  لكن هنا أمر لا بدّ من الانتباه له، وهو أنه لا يجوز للمسلم أن يتفق على الربا، ما يجوز أن يتفق مع البنك، يقول: أنا أعطيك هذا المال على أن  لي 5% أو 10% ربحًا، ما يجوز هذا، فهو من الربا، لكن لو أعطاه المال، وجعل عنده المال من غير مشارطة، من غير شيء بينه وبينه، ولكن معلوم أن هذا عند البنوك معروف عندهم، فإذا ... المال وأعطوه الربح المعتاد، فهل يقبضه، أم لا؟ المشروع عند العلماء: أنه لا يقبضه إذا كان معروفًا؛ لأن الشرط العرفي كالنطقي، كأنه شارطهم على ذلك، وقال بعض أهل العلم: لا بأس أن يؤخذ، لكن لا يدخل في ماله، بل يجعل في جهات أخرى: من صدقة على الفقراء، من إصلاح الطرق، من إصلاح دورات المياه، من أشباهه، مما ينفع المسلمين، ولا يكون في ماله، ولا يأخذه، ولا ينتفع به، هذا قول جماعة من أهل العلم، وهو قول قوي، لكنه يخشى على الإنسان أن تطاوعه نفسه، يخشى عليه أنه إذا أخذه أن يأكله، ويخشى عليه .. في ذلك فالحيطة له أن لا يأخذه، فإن أخذه؛ فليجعله عند غيره من الأمناء، والأخيار؛ حتى يصرف في جهة بر، وفي جهة تنفع المسلمين، وهو يسلم من شره،، ولا يستعين به في شيء من  أموره الخاصة.","link":"https://binbaz.org.sa/fatwas/1880/حكم-اخذ-الارباح-التي-تعطيها-البنوك-الربوية-في-بلاد-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_666.mp3","categories":["الربا والصرف","الأخلاق المذمومة"]},{"id":6335,"question":"لا يخفى عليكم أن البنوك الموجودة الآن ربوية، وتتعامل بالربا داخل المملكة، وخارجها، وقد جعل قسط من رأس مالها للمواطن مساهمة، وحسب علم بعض الناس أنها حلال، فعليكم أمام الله أن توضحوا ذلك لأجل أن يكون الناس على بينة من ذلك، وبما أن كل شخص يريد بضاعة من الخارج، لا ترد إلا عن طريق البنوك الموجودة، ولماذا لا تكون هناك بنوك إسلامية تتعامل هكذا؟","title":"البنوك الربوية وخطرها والتحذير منها","answer":"الجواب: البنوك الربوية كلها محرمة، ويجب أن لا يتعامل معها، بل يجب أن تهجر، وأن لا يتعامل معها لما في التعامل معها من التعاون على الإثم، والعدوان، وقد نشرنا هذا غير مرة في الصحف الأهلية، ونشر غيرنا ذلك، وبيان تحريم الربا فهو بحمد الله واضح في القرآن العظيم، والسنة المطهرة. ولا شك أن تحذيرنا عن الربا واجب، فعلى أهل العلم أن يحذروا من الربا دائمًا، ويبينوا للناس أنه من كبائر الذنوب، وأنه خطر عظيم، ومن أسباب العقوبات العامة، ظهور الربا، والزنا، والخمر، والغيبة، والنميمة، وعقوق الوالدين، وقطيعة الرحم، وأشباه ذلك من المعاصي كلها، من أسباب العقوبات العامة -نعوذ بالله- فيجب الحذر من ذلك، ويجب على كل مسلم أن يحذر من ذلك.  ونسأل الله أن يسهل إيجاد بنوك إسلامية قريبًا؛ فإن الدولة -وفقها الله- قد وعدت بهذا الشيء إيجاد بنوك إسلامية، ووجود مؤسسات إسلامية تغني عن البنوك الربوية، ونرجو أن يستهل هذا قريبًا -إن شاء الله- حتى يقضى على هذه البنوك الربوية، أو يهديهم الله، فيرجعون إلى الصواب.","link":"https://binbaz.org.sa/fatwas/1922/البنوك-الربوية-وخطرها-والتحذير-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_707.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6341,"question":"يوجد صندوق توفير في شركة كهرباء الرياض المنطقة الوسطى، وهذا الصندوق يعيد المبالغ للمشتركين لمن أمضى خمس سنوات 50% ولمن أمضى عشر سنوات 100% ما حكم ذلك شرعًا؟","title":"حكم صندوق التوفير","answer":"الجواب: هذا من الربا، إذا كان يعطيهم أموالًا، وهم يعملون فيها، ويعطونه 50% مثل البنوك سواء سواء، صندوق التوفير مثل البنوك، أما إذا كان شيء بينهم، يعني جماعة اشتركوا فيما بينهم صندوق يضعون فيه مالاً بينهم؛ لحاجاتهم هم، ولحوادث تقع لهم، ونمى .. وكيل لهم ينميه لهم، هذا ما هو الربا، هذا لمصلحتهم هم. أما صندوق توفير يتولاه ناس، يأخذون أموال الناس، يعملون فيها، ويعطونه 50% أو 10% أو 100% بعد خمس سنين، أو بعد ثلاث، أو بعد عشر، فهذا من الربا، من جنس الربا، سواء.","link":"https://binbaz.org.sa/fatwas/1924/حكم-صندوق-التوفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_709.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6349,"question":"ما حكم إيداع المال بدون أخذ الفائدة عليه كأمانة، أو حساب جار في البنوك الموجودة حاليًا؛ علمًا أنها تتعامل بالربا، وإعطاء الفائدة؟","title":"حكم إيداع المال في البنوك الربوية دون أخذ الفائدة","answer":"الجواب: لا يجوز أن يعطوا مالاً يحفظونه عندهم؛ لأنهم يعاملون بالربا، وهذا إعانة لهم في الربا، لكن بعض أهل العلم يقول: إذا كان للضرورة، وليس عنده مكان يحفظ فيه ماله، ولم يجد من يحفظ ماله إلا من طريق هذه البنوك، فقد يجوز له للضرورة من دون فائدة، ولكن إذا اجتهد -إن شاء الله- وَجَدَ محلاً لماله، ولم يعطه هذه البنوك التي تستعين به على الربا، والشر، أما الفائدة فلا.","link":"https://binbaz.org.sa/fatwas/1925/حكم-ايداع-المال-في-البنوك-الربوية-دون-اخذ-الفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_710.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6359,"question":"يوجد صندوق توفير في شركة كهرباء الرياض المنطقة الوسطى، وهذا الصندوق يعيد المبالغ للمشتركين لمن أمضى خمس سنوات 50% ولمن أمضى عشر سنوات 100% ما حكم ذلك شرعًا؟","title":"حكم صندوق التوفير","answer":"الجواب: هذا من الربا، إذا كان يعطيهم أموالًا، وهم يعملون فيها، ويعطونه 50% مثل البنوك سواء سواء، صندوق التوفير مثل البنوك، أما إذا كان شيء بينهم، يعني جماعة اشتركوا فيما بينهم صندوق يضعون فيه مالاً بينهم؛ لحاجاتهم هم، ولحوادث تقع لهم، ونمى .. وكيل لهم ينميه لهم، هذا ما هو الربا، هذا لمصلحتهم هم. أما صندوق توفير يتولاه ناس، يأخذون أموال الناس، يعملون فيها، ويعطونه 50% أو 10% أو 100% بعد خمس سنين، أو بعد ثلاث، أو بعد عشر، فهذا من الربا، من جنس الربا، سواء.","link":"https://binbaz.org.sa/fatwas/1924/حكم-صندوق-التوفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_709.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6425,"question":"السؤال الأول وهو ما يتصل بالموضوع: هل يجوز شراء الذهب الذي فيه خرز، حيث إنه يوجد الآن بكثرة في الأسواق؟","title":"حكم شراء الذهب إلى أجل","answer":"الجواب: يجوز شرائه لكن بغير الورق، أما بالورق لا بدّ يدًا بيد، لا يجوز النسيئة، يشتري الذهب الذي فيه خرز بالفضة، بالورق يدًا بيد، أو بفضة حقيقية يدًا بيد؛ لا بأس، أو بأموال أخرى يشتري سلعة ذهبية التي فيها خرز، فيها ماس، فيها لؤلؤ، يشتريها بسكر، بسيارة، بملابس، بأشياء أخرى غير الذهب، والفضة، والأوراق المعروفة بدلًا الفضة، والذهب.  أما إذا كان بهذا؛ لا بدّ أن يكون يدًا بيد، وإن كان بذهب؛ فلا بدّ من التماثل إن كانت السلعة فيها ذهب، لا بدّ أن يفرز الذهب، ويتماثل مع الذهب يدًا بيد، وإذا باعه بغير الذهب، بأوراق؛ فلا بأس، لكن يدًا بيد، ولا يقول: أعطنيها والدراهم أعطيك بعد حين، أو .. بعد حين لا، يدًا بيد.","link":"https://binbaz.org.sa/fatwas/2139/حكم-شراء-الذهب-الى-اجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_788.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6429,"question":"السؤال الأول وهو ما يتصل بالموضوع: هل يجوز شراء الذهب الذي فيه خرز، حيث إنه يوجد الآن بكثرة في الأسواق؟","title":"حكم شراء الذهب إلى أجل","answer":"الجواب: يجوز شرائه لكن بغير الورق، أما بالورق لا بدّ يدًا بيد، لا يجوز النسيئة، يشتري الذهب الذي فيه خرز بالفضة، بالورق يدًا بيد، أو بفضة حقيقية يدًا بيد؛ لا بأس، أو بأموال أخرى يشتري سلعة ذهبية التي فيها خرز، فيها ماس، فيها لؤلؤ، يشتريها بسكر، بسيارة، بملابس، بأشياء أخرى غير الذهب، والفضة، والأوراق المعروفة بدلًا الفضة، والذهب.  أما إذا كان بهذا؛ لا بدّ أن يكون يدًا بيد، وإن كان بذهب؛ فلا بدّ من التماثل إن كانت السلعة فيها ذهب، لا بدّ أن يفرز الذهب، ويتماثل مع الذهب يدًا بيد، وإذا باعه بغير الذهب، بأوراق؛ فلا بأس، لكن يدًا بيد، ولا يقول: أعطنيها والدراهم أعطيك بعد حين، أو .. بعد حين لا، يدًا بيد.","link":"https://binbaz.org.sa/fatwas/2139/حكم-شراء-الذهب-الى-اجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_788.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6478,"question":"أستطيع أن أقول بأن الكثير من بائعي الذهب، والنساء اللاتي يشترين الذهب، ويقعون في الربا، وذلك مثل: البدل، يعني ذهب بذهب، وعندما يبقى لصاحب المحل بعض الفلوس؛ فيرضى بأن يصبر على الشخص بموجب المعرفة بينهما، ولقد سألنا كثيرًا من النساء عن البدل، فيقولون: نعم نبدل دائمًا، ولا نعلم عن الربا شيئًا؟","title":"حكم بيع الذهب القديم بالذهب الجديد","answer":"الجواب:  المعاصي تقع، ما يقال: إنها لا تقع، المعاصي تقع بين الناس، تقع في الربا، تقع معاصي الربا، ومعاصي غير الربا،  كلها تقع، لكن المهم العلاج لهذه المعاصي بالحدود الشرعية، والمواعظ، والتذكير، والنصائح، وإلا فالمعاصي تقع، فالربا يقع من النساء، ومن الرجال مع الصاغة، ومع غير الصاغة، فلا يجوز السكوت عنهم، من علم أنه يقع منه المعصية ينصح، ويوجه إلى الخير.  فالذي يشتري من الصاغة القلائد، أو أسورة، أو غير ذلك لا بد أن يشتريها بمال يدًا بيد في الأسورة، في القلائد في .. [ثم] يشتريها بالنقد يدًا بيد، أو بنوع آخر غير النقد، يشتري مثلاً قلادة من الذهب، أو من الفضة، أو خاتم من الذهب، أو أسورة من الذهب، أو غير ذلك، يشتريها بغير النقود، يشتريها مثلًا بطعام، يشتريها بملابس، يشتريها بهيل، بقهوة، بسكر إلى أجل، ما في بأس، لكن بنقود لا، لا بد يدًا بيد، بذهب لا بدّ يدًا بيد.  فإذا باع؛ أعطى الخواتم المستعملة، أو الأشياء المستعملة بشيء جديد، لا بد أن يكون يدًا بيد، مثلًا بمثل، وإلا فلتشتري من الجديد بثمن مستقل، ولتبع عليه المصمت بثمن مستقل، أما أن تعطي هذا بهذا وزيادة، ما يجوز، هذا ربا، تبيع هذا الجديد بهذا المصمت، وزيادة جنيه جنيهين، ما يجوز، فلا بد أن تشتري الجديدة بثمن مستقل، يدًا بيد إن كان من النقود من الورق، وإن كان بغير النقود .. إلى أجل، طعام إلى أجل، بملابس إلى أجل، لا بأس يعني ما هو بربوي إذا باع الذهب بهيل، أو قهوة، أو ملابس، أو خام آخر، أو سلع أخرى غير النقود؛ فلا بأس إلى أجل معلوم، أما بالنقود فلا، لا بدّ يدًا بيد، فإن كان ذهبًا بذهب، لا بد أن يكون مثلًا بمثل، سواء بسواء، وجها لوجه يدًا بيد، لا يتفرقا، وهكذا الفضة.  فإن باع فضة بذهب، لا بأس، لكن يدًا بيد، إن اشترى من الصائغ، أسورة من الذهب بورق يدًا بيد؛ فلا بأس، أما يقول: روح، وبعدين تجيء لي ما يصلح، لا بدّ يدا بيد، وإذا فعلته المرأة، والرجل؛ ينصح، ويبين له أن هذا منكر، وعلى الهيئة، والحسبة أن تقوم بهذا الأمر، وأن تنكر على من فعل هذا الشيء، ومن لم يرتدع؛ يعاقب بالأدب، والسجن، والضرب إذا لم ينزجر عما حرم الله عليه.","link":"https://binbaz.org.sa/fatwas/2226/حكم-بيع-الذهب-القديم-بالذهب-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_846.mp3","categories":["الربا والصرف","الأخلاق المذمومة"]},{"id":6493,"question":"أستطيع أن أقول بأن الكثير من بائعي الذهب، والنساء اللاتي يشترين الذهب، ويقعون في الربا، وذلك مثل: البدل، يعني ذهب بذهب، وعندما يبقى لصاحب المحل بعض الفلوس؛ فيرضى بأن يصبر على الشخص بموجب المعرفة بينهما، ولقد سألنا كثيرًا من النساء عن البدل، فيقولون: نعم نبدل دائمًا، ولا نعلم عن الربا شيئًا؟","title":"حكم بيع الذهب القديم بالذهب الجديد","answer":"الجواب:  المعاصي تقع، ما يقال: إنها لا تقع، المعاصي تقع بين الناس، تقع في الربا، تقع معاصي الربا، ومعاصي غير الربا،  كلها تقع، لكن المهم العلاج لهذه المعاصي بالحدود الشرعية، والمواعظ، والتذكير، والنصائح، وإلا فالمعاصي تقع، فالربا يقع من النساء، ومن الرجال مع الصاغة، ومع غير الصاغة، فلا يجوز السكوت عنهم، من علم أنه يقع منه المعصية ينصح، ويوجه إلى الخير.  فالذي يشتري من الصاغة القلائد، أو أسورة، أو غير ذلك لا بد أن يشتريها بمال يدًا بيد في الأسورة، في القلائد في .. [ثم] يشتريها بالنقد يدًا بيد، أو بنوع آخر غير النقد، يشتري مثلاً قلادة من الذهب، أو من الفضة، أو خاتم من الذهب، أو أسورة من الذهب، أو غير ذلك، يشتريها بغير النقود، يشتريها مثلًا بطعام، يشتريها بملابس، يشتريها بهيل، بقهوة، بسكر إلى أجل، ما في بأس، لكن بنقود لا، لا بد يدًا بيد، بذهب لا بدّ يدًا بيد.  فإذا باع؛ أعطى الخواتم المستعملة، أو الأشياء المستعملة بشيء جديد، لا بد أن يكون يدًا بيد، مثلًا بمثل، وإلا فلتشتري من الجديد بثمن مستقل، ولتبع عليه المصمت بثمن مستقل، أما أن تعطي هذا بهذا وزيادة، ما يجوز، هذا ربا، تبيع هذا الجديد بهذا المصمت، وزيادة جنيه جنيهين، ما يجوز، فلا بد أن تشتري الجديدة بثمن مستقل، يدًا بيد إن كان من النقود من الورق، وإن كان بغير النقود .. إلى أجل، طعام إلى أجل، بملابس إلى أجل، لا بأس يعني ما هو بربوي إذا باع الذهب بهيل، أو قهوة، أو ملابس، أو خام آخر، أو سلع أخرى غير النقود؛ فلا بأس إلى أجل معلوم، أما بالنقود فلا، لا بدّ يدًا بيد، فإن كان ذهبًا بذهب، لا بد أن يكون مثلًا بمثل، سواء بسواء، وجها لوجه يدًا بيد، لا يتفرقا، وهكذا الفضة.  فإن باع فضة بذهب، لا بأس، لكن يدًا بيد، إن اشترى من الصائغ، أسورة من الذهب بورق يدًا بيد؛ فلا بأس، أما يقول: روح، وبعدين تجيء لي ما يصلح، لا بدّ يدا بيد، وإذا فعلته المرأة، والرجل؛ ينصح، ويبين له أن هذا منكر، وعلى الهيئة، والحسبة أن تقوم بهذا الأمر، وأن تنكر على من فعل هذا الشيء، ومن لم يرتدع؛ يعاقب بالأدب، والسجن، والضرب إذا لم ينزجر عما حرم الله عليه.","link":"https://binbaz.org.sa/fatwas/2226/حكم-بيع-الذهب-القديم-بالذهب-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_846.mp3","categories":["الربا والصرف","الأخلاق المذمومة"]},{"id":6557,"question":"أعمل بأحد البنوك، وأخذت قرضًا لتسديد السكن، حيث إن البنك يأخذ عمولة على هذا القرض، فما حكم الدين؟ وأيضًا رواتبنا من هذا البنك تتحصل من العمولة التي يحصلها البنك على المبالغ المقروضة لبعض العملاء، فما حكم الدين، وما حكم الراتب من هذا البنك؟","title":"حكم الاقتراض من البنك وأخذ الراتب منه","answer":"الجواب: أما الدين فلا يجوز، عليك أن ترد الأصل فقط، وليس لهم حق في الزيادة، وأما كون القرض تخصم من هذا البنك فالإثم على من أخذ الربا، أنت تأخذ راتبك، والبنك فيه الطيب والرديء، البنك فيه أشياء بحق، وأشياء بغير حق، ولست تعلم أن هذا من الربا، أو من غير الربا، أما كونك تعامل بالربا لا يجوز لك هذا، وما أخذته من الفائدة مائة فيها عشرة، أو فيها خمسة عشر ليس لك ذلك، هذا لا يجوز لك، وإذا كانت باقية عندك ليس لك تسليمها لهم.  السؤال: العمل في البنك؟ الجواب: لا يجوز عمله في البنك أيضًا؛ لأنه يعين على الإثم، والعدوان.","link":"https://binbaz.org.sa/fatwas/2395/حكم-الاقتراض-من-البنك-واخذ-الراتب-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_924.mp3","categories":["الربا والصرف","السلف والقرض"]},{"id":6558,"question":"هل شراء كيس أرز بسمتي بـ115 ريالًا بشرط أن تعطيه كيس أرز أبو بنت بـ95 ريالًا يجوز هذا التبادل؟","title":"حكم بيع الأرز بمثله متفاضلاً","answer":"الجواب: هذا لا يجوز بيع الرز بالرز إلا مثلًا بمثل، الرز بالرز، والحنطة بالحنطة، والشعير بالشعير، والتمر والملح، كل أنواع الحبوب هذه لا يجوز بيعها ببعض إلا يدًا بيد، مثلاً بمثل، يعني 100 كيلو بـ 100 كيلو، 100 صاع بـ 100 صاع، 50 صاع بـ 50 صاع يدًا بيد مثلاً بمثل، لا يزادد، ولا ينقص، أما بأكياس لا ما ينفع، أكياس تزيد، وتنقص، لا بد أن يكون مثلًا بمثل بالكيل، أو بالوزن، والكيل أحسن.","link":"https://binbaz.org.sa/fatwas/2424/حكم-بيع-الارز-بمثله-متفاضلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_951.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6564,"question":"رجل يتعامل في البنوك الربوية، وسألته لماذا تتعامل مع البنوك؛ فقال: أنا لا آخذ الفائدة الربوية؟","title":"حكم من يتعامل مع البنوك الربوية دون أخذ الفائدة","answer":"الجواب: الرسولﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: «هم سواء» فالتعاون مع من يأخذ الربا، ويعامل في الربا تعامل لا يجوز؛ لأن الله قال: وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2] فليس للمؤمن أن يتعاطى الربا في المعاملات.","link":"https://binbaz.org.sa/fatwas/2425/حكم-من-يتعامل-مع-البنوك-الربوية-دون-اخذ-الفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_952.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6586,"question":"أعمل بأحد البنوك، وأخذت قرضًا لتسديد السكن، حيث إن البنك يأخذ عمولة على هذا القرض، فما حكم الدين؟ وأيضًا رواتبنا من هذا البنك تتحصل من العمولة التي يحصلها البنك على المبالغ المقروضة لبعض العملاء، فما حكم الدين، وما حكم الراتب من هذا البنك؟","title":"حكم الاقتراض من البنك وأخذ الراتب منه","answer":"الجواب: أما الدين فلا يجوز، عليك أن ترد الأصل فقط، وليس لهم حق في الزيادة، وأما كون القرض تخصم من هذا البنك فالإثم على من أخذ الربا، أنت تأخذ راتبك، والبنك فيه الطيب والرديء، البنك فيه أشياء بحق، وأشياء بغير حق، ولست تعلم أن هذا من الربا، أو من غير الربا، أما كونك تعامل بالربا لا يجوز لك هذا، وما أخذته من الفائدة مائة فيها عشرة، أو فيها خمسة عشر ليس لك ذلك، هذا لا يجوز لك، وإذا كانت باقية عندك ليس لك تسليمها لهم.  السؤال: العمل في البنك؟ الجواب: لا يجوز عمله في البنك أيضًا؛ لأنه يعين على الإثم، والعدوان.","link":"https://binbaz.org.sa/fatwas/2395/حكم-الاقتراض-من-البنك-واخذ-الراتب-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_924.mp3","categories":["الربا والصرف","السلف والقرض"]},{"id":6590,"question":"هل شراء كيس أرز بسمتي بـ115 ريالًا بشرط أن تعطيه كيس أرز أبو بنت بـ95 ريالًا يجوز هذا التبادل؟","title":"حكم بيع الأرز بمثله متفاضلاً","answer":"الجواب: هذا لا يجوز بيع الرز بالرز إلا مثلًا بمثل، الرز بالرز، والحنطة بالحنطة، والشعير بالشعير، والتمر والملح، كل أنواع الحبوب هذه لا يجوز بيعها ببعض إلا يدًا بيد، مثلاً بمثل، يعني 100 كيلو بـ 100 كيلو، 100 صاع بـ 100 صاع، 50 صاع بـ 50 صاع يدًا بيد مثلاً بمثل، لا يزادد، ولا ينقص، أما بأكياس لا ما ينفع، أكياس تزيد، وتنقص، لا بد أن يكون مثلًا بمثل بالكيل، أو بالوزن، والكيل أحسن.","link":"https://binbaz.org.sa/fatwas/2424/حكم-بيع-الارز-بمثله-متفاضلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_951.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6757,"question":"ما حكم العمل في البنوك الربوية، وأخذ الراتب منهم، الآن كثير من الناس يعملون عندهم بجهل الحال، أو بعلم، أفتونا جزاكم الله خيرًا؟","title":"حرمة العمل في البنوك الربوية","answer":"الجواب: العمل في البنوك الربوية منكر، ولا يجوز، الرسول ﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء العمل في البنوك في الربا، وفي غير البنوك، إذا كان في الربا؛ لا يجوز الربا، ولا المعاونة عليه، لا بكونه كاتبًا، ولا محاسبًا، ولا غير ذلك، -والله المستعان-.","link":"https://binbaz.org.sa/fatwas/2656/حرمة-العمل-في-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1152.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6815,"question":"طيب يا شيخ، غفر الله لك، بالنسبة للريال السعودي يساوي عشرين قرشًا، وهناك في السوق السوداء يشترونه بأربعين قرشًا، أو بخمسين قرشًا، ما الحكم في ذلك؟","title":"حكم الزيادة في الصرف","answer":"الجواب: إذا كان يدًا بيد؛ ما في بأس. السؤال: يعني المكسب هذا جائز؟ الجواب: إذا كان يدًا بيد؛ لأن الجنس غير الجنس، هذا ورق، وهذا معدن.","link":"https://binbaz.org.sa/fatwas/2700/حكم-الزيادة-في-الصرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1199.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":6902,"question":"أنا شاب أبلغ من العمر عشرين عامًا، والدي يعمل في التجارة، غير أنه يأخذ في بعض الأوقات قروضًا من البنك، ثم يردها إلى البنك، إضافة إلى الفائدة، وأنا بعض الأوقات أقوم بقضاء بعض الأعمال له،  هل يجوز لي أن آكل، أو آخذ من مال والدي؟","title":"حكم أكل الولد من مال والده المرابي","answer":"الجواب: ما دام والدك عنده دخول أخرى من الحلال، ولكنه قد يخطئ، فيأخذ سلفًا من البنك، لا حرج عليك أن تأكل مع والدك، وأن تعينه في الخير فقط، وتنصحه حتى لا يعود إلى القرض من البنك بالفائدة، تقول له: إن هذا محرم ولا يجوز لك، لعل الله يهديه بأسبابك، أو تقول لعمك، أو إخوانك الكبار، يقولون له بأسلوب حسن؛ حتى يهديه الله، ويقبل، عليك أن تفعل ما تستطيع من الخير، ولو بتحريك غيرك من أعمام، أو أخوال، أو إخوة كبار؛ حتى ينصحوه، ويتوجهوا إليه بما يعينه على ترك الربا.","link":"https://binbaz.org.sa/fatwas/2837/حكم-اكل-الولد-من-مال-والده-المرابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1285.mp3","categories":["الربا والصرف","البيوع","الآداب والأخلاق"]},{"id":7077,"question":"هل يجوز إيداع المال في بنك ربوي، مثل البنك العربي الوطني؟ وما حكم ترك هذا البنك إذا كان يتعامل بالربا، وأنا لا أتعامل معه؟","title":"حكم إيداع الأموال في البنوك الربوية بدون أخذ الفائدة","answer":"الجواب:\n\nالأصل لا يجوز إيداع الأموال في البنوك الربوية، هذا هو الأصل؛ لأن في ذلك إعانة لها على أعمالها الخبيثة، لكن إذا اضطر إلى ذلك، وخاف على ماله؛ فإنه يودع بدون شرط الربا، يودع الوديعة فقط من دون شرط الربا.\n\nوإذا تيسر له أن يجعل صندوقًا في هذا البنك معه مفتاحه يحفظه عنده؛ هذا أسلم؛ حتى لا يعينهم على رباهم إذا تيسر هذا، هذا معمول كما بلغنا في بعض البنوك، يجعل صندوقًا خاصًا فيه ماله، يعطيهم إياه بأجر معلوم، على السنة، أو الشهر حتى يأخذ هذا الصندوق، هذا أطيب وأحسن، فإن لم يتيسر ذلك؛ جعله عندهم بدون ربا للضرورة فقط، أما إذا تيسر أن يودعه في محل غير ربوي؛ فهذا هو الواجب عليه.","link":"https://binbaz.org.sa/fatwas/3092/حكم-ايداع-الاموال-في-البنوك-الربوية-بدون-اخذ-الفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1471.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7081,"question":"لقد قدمت إلى هذه الديار الطبية منذ أكثر من خمس سنوات، ولقد عانيت، وتعبت غاية التعب في أول الأمر، ولم يكن عند كفيلي أي عمل يخرجني مما أنا فيه من ضيق وحاجة للمال؛ لتسيير به حياتي، وأنفق على أهل بيتي من الوالدين والإخوان، وبحثت عن عمل، وتنقلت في أكثر من أربعة مؤسسات تجارية، وأخيرًا استقر بي المقام في أحد المصارف هنا في الرياض، ولقد بذلت غاية جهدي، وأخلصت في عملي؛ حتى صرت محاسبًا في الحسابات الجارية، فعلمت أن هذا المصرف يضع أكثر ماله في بنوك داخل المملكة وخارجها بالفائدة الربوية، وهناك حسابين لعملاء تأتينا الأوراق المصرفية بتسجيل فائدة ربوية لحساباتهم طرفنا، وهي من بنوك خارجية، ويعلم الله تعالى أني في غاية الضيق لهذا الأمر، ولم يهدأ لي بال منذ أن عرفت هذا الأمر، علمًا بأني قد تزوجت، وأحضرت زوجتي، ورزقني الله تعالى بولدين، وأنا طالب علم شرعي إلى أن قال: وأحب الفقه في الدين، وأحضر ندوات العلم، ويبين أنه لو ترك هذا العمل سيقع في ضيق، وفي حرج، وسيتأخر في الصرف على أهله وأبيه وأمه، فباله مشغول من ذلك، وينتظر من سماحتكم فتوى بهذا؟","title":"حكم العمل في البنوك الربوية لمن كان مضطرا","answer":"الجواب:\n\nالله -جل وعلا- أحل لعباده ما فيه نجاتهم، وقضاء حاجاتهم، وحرم عليهم ما يضرهم، فليس العبد مضطرًا إلى ما حرم الله عليه، بل عليه أن يسعى جهده في طلب الرزق من طريق الحلال، والتوظف في البنوك إعانة لهم على الإثم والعدوان، سواء كان محاسبًا أو كاتبًا أو غير ذلك، فالواجب على المؤمن أن يحذر ذلك، وأن يبتعد عن البنوك؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2]\n\nفالتعاون مع البنوك، أو مع قطاع الطريق، أو مع السراق، أو مع الغشاشين، أو مع أصحاب الرشوة كله تعاون على الإثم والعدوان، فلا يجوز، وما قبضته قبل ذلك -قبل العلم- فلك ما سلف، وما كان بعد العلم فليس لك، يقول الله -جل وعلا-: فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ [البقرة:275]. \n\nما قبضته سابقًا قبل أن تعلم فهو لك، وأما بعد أن علمت؛ فعليك أن تغادر هذا العمل، وتترك هذا العمل، وتبذل ما قبضته من طريق الربا، وأنت عالم في جهة البر والخير، كالصدقة على الفقراء والمساكين، إلى غيره؛ حتى تتخلص من هذا المال الذي جاءك بغير وجهه، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه لعن آكل الربا، وموكله، وكاتبه وشاهديه، وقال: هم سواء.\n\nفالواجب على المؤمن أن يحذر ذلك وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فأنت إذا اتقيت الله؛ يسر الله أمرك، ورزقك من حيث لا تحتسب، فالتمس أعمالًا أخرى، ولو بأجر قليل، إذا كنت تأخذ من البنك خمسة آلاف، أو ستة آلاف، أو عشرة آلاف شهريًا؛ فسوف تجد -إن شاء الله- من الأعمال المباحة بمعاش يكفيك، ويبارك الله لك فيه، ولو ألفين، أو ثلاثة، أو أربعة، ولو أقل من ذلك بكثير.\n\nأنت عليك أن تطلب الحلال والله يعوضك، يقول النبي ﷺ في الحديث الصحيح لما سئل أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور وقال أيضًا: ما أكل أحد طعامًا أفضل من أن يأكل من عمل يده، وإن نبي الله داود كان يأكل من عمل يده عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/3085/حكم-العمل-في-البنوك-الربوية-لمن-كان-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1467.mp3","categories":["الربا والصرف","الإجارة"]},{"id":7085,"question":"من تعريف ربا النسيئة: أنه الزيادة في الشيء مقابل التأجيل، فما مدى انطباق هذا الشيء على دينة الأكياس، والسيارات المعمول بها الآن بدلاً من القرض الحسن، أفتونا جزاكم الله خيرًا؟","title":"الفرق بين ربا النسيئة والتورق","answer":"الجواب:\n\nما يعمها هذا، الربا هو أن يأخذ شيئًا بجنسه مع زيادة، هذا ربا الفضل، وإن كان دينًا بدين؛ صار ربا الفضل والنسيئة جميعًا، فإذا أخذ دراهم بدراهم وزيادة؛ فهذا ربا الفضل، سواء كان يدًا بيد، أو نسيئة.\n\nوأما مسألة التورق فليست من هذا الباب، يأخذ سلعة بدراهم إلى أجل، ثم يبيعها -وهو على اختياره- في يومه، أو غده، أو بعد ذلك هو ما أخذ ربويًا بربوي، وإنما أخذ سلعة من طعام، أو سيارة، أو أرض، أو غير ذلك بدراهم معدودة، إلى أجل معلوم، فليس من الربا في شيء.","link":"https://binbaz.org.sa/fatwas/3088/الفرق-بين-ربا-النسيىة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1469.mp3","categories":["الربا والصرف","البيوع"]},{"id":7087,"question":"رجل رهن عليا مزرعة بمبلغ معين، وأنا أقوم بحرثها، وأدفع له الثلث من المحصول مقابل ملكه، وثلثين لي مقابل حراثة الأرض، والمبلغ الذي مع الراهن، ما حكمه؟ هل هو من الربا، أم من غير الربا؟","title":"حكم الرهن بالدين","answer":"الجواب:\n\nإذا رهن عليك الأرض التي فيها الزراعة فيما له عليك من الدين، وأخذتها بما يأخذ الناس بالثلث، أو بالربع مثل الناس، ما زدت له من أجل الدين؛ فلا بأس. \n\nأما إذا زدت له: الناس يأخذون الربع، وأنت أعطيته الثلث من أجل الدين ما يجوز؛ لأن هذا مقابل زيادة على القضاء، فيشبه القرض الذي بالزيادة، أما إذا أخذتها من جنس ما يأخذها الناس، هذه المزرعة بالثلث، بالربع، بالخمس، ما زدته على ذلك شيئًا؛ فلا بأس، وإلا فلا يجوز؛ لأنه من باب الزيادة؛ لأجل يمهلك في هذا الدين.","link":"https://binbaz.org.sa/fatwas/3101/حكم-الرهن-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1478.mp3","categories":["الربا والصرف","الرهن"]},{"id":7088,"question":"بعض الناس يضعون أموالهم في البنوك خارج المملكة، وحيث إن هذه البنوك تعطي فوائد في كل الأحوال، فيرى بعض الناس أن أخذ هذه الفوائد، والتصدق بها للدول الإسلامية الفقيرة، كبناء مساجد، وبناء المستشفيات، والصدقة، بدلًا من تركها لهذه البنوك التي تقدمها لدول غير إسلامية، فما حكم ذلك؟","title":"حكم أخذ الفوائد الربوية لصرفها في وجوه البر","answer":"الجواب:\n\nأما الاتفاق على ذلك فلا يجوز، الاتفاق على الربا لا يجوز، ولو قال: تصدق بالزيادة، ما يجوز الاتفاق على الربا، ولا يجوز المعاملة بالربا، لكن لو أن إنسانًا فعل ذلك لقلة إيمانه، وضعف إيمانه، ثم هداه الله، يتصدق بهذه الأشياء لما قبضها، يتصدق بها في وجوه البر، وأعمال الخير، يتصدق على الفقراء في أفريقيا وغيرها، وفي المجاهدين، أو غير ذلك؛ لأنه مال ليس له أحد، فيصرف فيما ينفع المسلمين. \n\nأما أنه يتعامل معهم، وينوي هذه النية ما يجوز، ما يجوز التعامل بالربا ويقول: أنا أتصدق، أو أفعل كذا وكذا، مثل ما أنه لا يجوز أن يغش، أو يخون، ويقول: أتصدق بالزيادة، كل هذا لا يجوز، يجب عليه أن يتحرى الشرع، ويتمسك بالشرع، ولا يتعدى حدود الشرع، لكن لو أن إنسانًا دخل عليه مليون، أو مليونين بالربا، تساهل في ذلك، وغلبه الطمع، ثم هداه الله، هذه التي دخلت عليه بالربا يتصدق بها، ويعطيها أهل الجهاد، أو الأفارقة المحتاجين، أو غيرهم من المحاويج، أو يقضي بها دينًا عن المدانين، وضعفاء المساكين، أو يصلح بها دورات المياه للمحتاجين، أو ما أشبه ذلك من وجوه البر.","link":"https://binbaz.org.sa/fatwas/3095/حكم-اخذ-الفواىد-الربوية-لصرفها-في-وجوه-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1473.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7092,"question":"هناك فتوى بتحريم دفع زيادة على مقايضة الذهب القديم بالجديد، واعتبار ذلك ربا الفضل، ولكن هناك كلام من تجار الذهب مفاده: أنهم ينفقون أموالًا في طلاء الذهب القديم؛ حتى يصبح ناصعًا مثل الجديد، كما أنهم يبذلون جهدًا في تصنيعه، فكيف تفسير هذه الشبهة؟","title":"حكم بيع الذهب القديم بالجديد مع مبلغ من المال","answer":"الجواب:\n\nبكل حال، ما يجوز بيع الذهب الجديد بالذهب القديم، ولا الذهب الجديد بالجديد، ولا الذهب القديم بالقديم، كله ما يجوز إلا يدًا بيد مثلًا بمثل، سواء بسواء، لا بد أن يكون هذا مثل هذا، وزنًا بوزن، مثلًا بمثل.\n\n أما كون هذا أغلى، أو أنفس، أو هذا دون ذلك، ما يضر، النبي ﷺ ألغى هذا الفرق، قال: \"الذهب بالذهب ربًا، مثلًا بمثل، سواء بسواء يدًا بيد\" وهكذا الفضة مثلًا وسواء، ومعلوم أنها لا بد لها من خلط .. الفضة يمسكها ويقيمها، وقد يبتلى الذهب بشيء من الغش اليسير.\n\nفالحاصل: أن الذهب بالذهب مطلقًا، لا بد يكون مثلًا بمثل، سواء بسواء، يدًا بيد، فلا يباع هذا بهذا وزيادة، هو ربا أن يباع الجنيه بجنيه وزيادة درهم أو درهمين، لا، لا بد يباع هذا بهذا يدًا بيد، مثلًا بمثل، أو يباع بسلعة أخرى، كأن يباع الذهب بالفضة بالورق، يباع بالتمر بالرز، بالشاي، بالسكر ما يخالف، أما ذهب بذهب لا بد فيه من التساوي، والتقابض، وهكذا الفضة، وهكذا الرز. \n\nالسؤال: ...؟\n\nالجواب: يأخذ لا بأس، لكن مثلًا بمثل، سواء بسواء، إذا سمح صاحب الطيب أن يعطيه سواء بسواء، وإلا فليبيع بشيء آخر غير الذهب، بالفضة، بالورق، بالطعام، بالملابس، بالسيارات، بشيء آخر، يعني حتى لا يقع الربا.","link":"https://binbaz.org.sa/fatwas/3097/حكم-بيع-الذهب-القديم-بالجديد-مع-مبلغ-من-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1475.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7128,"question":"ما ترى في استبدال عشرة ريالات ورقية سعودية بأحد عشر ريالًا حديدًا سعوديًا من عملة هذا الزمان، هل هذا ربا؟","title":"حكم استبدال عشرة ريالات ورقية بأحد عشر ريالا معدنيا","answer":"الجواب:\n\nكثير من الإخوان يقول: إنه شيء واحد؛ لأنها كلها ريال، وعندي في هذا الشيء.. لأن العملة غير العملة، الحديد غير الورق، ولكن توقي هذا أحسن وأحوط، كونه يأخذ عشرة بعشرة، خمسة بخمسة، يكون هذا أحوط، وأسلم.","link":"https://binbaz.org.sa/fatwas/3154/حكم-استبدال-عشرة-ريالات-ورقية-باحد-عشر-ريالا-معدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1512.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7148,"question":"يقول: أودعت فلوسي في أحد البنوك منذ فترة طويلة، وعندما سحبت المبلغ قالوا لي: هذا لك أرباح حوالي خمسين ألف ريال، وأنا علمت أن هذا ربا، ولا يجوز لي، والآن أسأل عندنا بقريتنا حفيرة، أي جابية، وهي مورد لهذه القرية، يشربون منها، فهل يصح لي أن أضع هذا المبلغ فيها، نريد توسعتها وإدرار الماء، وكثرة الاستفادة؟","title":"صرف المال الربوي في مصالح المسلمين","answer":"الجواب:\n\nنعم إذا أخذت مثل هذا المبلغ، أو دخل على الإنسان مبلغ ليس بشرعي؛ فإنه يجعل في مصالح المسلمين، في وجوه الخير، مثل المغصوب التي غصبها ونسي أهلها وجهل أهلها، يتصدق بها على الفقراء، أو يجعلها في مصالح المسلمين، وتوسيع الحفرة، وجعل سور عليها هذا من مصالح المسلمين، وهكذا إطعام الفقراء، أو قضاء دين المدينين، أو تزويج المحتاجين، كل هذا من مصالح المسلمين، ولا تأكلها.","link":"https://binbaz.org.sa/fatwas/3177/صرف-المال-الربوي-في-مصالح-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1535.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7171,"question":"لقد اقترضت من البنك العقاري على أرض لي، وبعد أن استلمت أول دفعة ثلاثين ألفًا أتاني رجل، ودفع لي عشرين ألفًا مع الثلاثين، وبعته الأرض، واقترض عليها باسمي، وسكن فيها، ولم يسدد البنك، حيث إن الاتفاق على أنه يسدد البنك، أفتوني أنا ومن يسمع، حيث هذه الطريقة مستعملة كثيرًا من الناس؟","title":"حكم بيع الرهن من قبل الراهن","answer":"الجواب:\n\nالذي نعلم أن الأرض مرهونة للبنك، وأنها لا تباع ولا يسمح البنك أن تباع إلا بإذنه، إلا بتسليم المال الذي على صاحبها، والراهن له الحق في منع البيع، وصاحب الرهن -الذي هو المالك- ليس له أن يتصرف حتى يستأذن المرتهن.\n\nالمقصود: أن هذا مال مرهون، فعليه أن يتفق مع البنك على هذا الأمر، إذا سمح البنك أنه يبيعه على فلان، أو فلان يحل محله؛ فلا حرج في ذلك، أو سمحت الدولة، وأرخصت للناس؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/3209/حكم-بيع-الرهن-من-قبل-الراهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1558.mp3","categories":["الربا والصرف","الرهن"]},{"id":7176,"question":"انتشر منذ فترة نوع من المضاربة تسمى سلة العملات، وهي أن يقوم الشخص بإعطاء البنك مبلغًا من المال، بالإضافة إلى تفويض؛ ليقوم البنك نيابة عنه بشراء العملات، وبيعها، كالدولار مثلًا، ونتيجة لهذا البيع والشراء يحصل الشخص على الأرباح، كما أنه معرض للخسارة أيضًا، فما رأي سماحتكم في ذلك؟","title":"حكم الاتجار بالعملات","answer":"الجواب:\n\nالذي بلغنا هو ما ذكره السائل أن يعطوا البنك، أو غير البنك عُمَلا يتجر لهم فيها، فالتجارة في العُمَل فيه التفصيل:\n\nإن كان من طريق الربا؛ حرم، وإن كان من طريق الشرع؛ أبيح، فإذا باع العملة بعملة أخرى يدًا بيد؛ فلا بأس، كأن يبيع العملة التي هي الدولار مثلًا بالجنيه الاسترليني، أو بالجنيه المصري، أو بالريال السعودي يدًا بيد؛ فلا بأس، أما إلى أجل، أو غير مقبوض في المجلس، هذا لا يجوز، لأن العُمَل هذه منزلة منزلة النقود في أصح أقوال أهل العلم من جنسها، وقائمة مقامها، وقال -عليه الصلاة والسلام-: الذهب بالذهب ربًا، إلا هاء وهاء. \n\nوفي اللفظ الآخر: الذهب بالفضة ربًا، إلا هاء وهاء يعني إلا يدًا بيد والفضة بالفضة ربا إلا هاء وهاء، والبر بالبر ربا إلا هاء وهاء، والشعير بالشعير ربا إلا هاء وهاء. \n\nوهكذا قوله في الحديث الآخر -عليه الصلاة والسلام-: الذهب بالذهب مثلًا بمثل سواءً بسواء يدًا بيد، والفضة بالفضة مثلا بمثل سواء بسواء يدا بيد.  \n\nثم هكذا ذكر في البر والشعير والتمر والملح كلها يدًا بيد، سواء بسواء، فالعُمَل التي يتعاطها الناس إذا باع بعضها ببعض مناجزة يدًا بيد؛ فلا بأس إذا كانت من أجناس كالدولار بالجنيه الاسترليني، أو المصري، أو الدولار بالدينار الأردني، أو الدينار العراقي يدًا بيد؛ فلا بأس.\n\nأما دولار بدولارين ما يجوز ربا فضل، إذا كان باع دولارًا بدولارين إلى أجل هذا اجتمع فيه الربا بنوعيه: ربا الفضل، وربا النسيئة، أو باع مثلاً العملة السعودية عشرة بإحدى عشرة، أو عشرة باثني عشر، ولو يدًا بيد، هذا ربا فضل، فإذا كان نسيئة، أو مؤخرًا عن المجلس؛ اجتمع فيه النوعان: ربا الفضل، وربا النسيئة.","link":"https://binbaz.org.sa/fatwas/3216/حكم-الاتجار-بالعملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1563.mp3","categories":["الربا والصرف","البيوع"]},{"id":7194,"question":"تجار الجملة يبيعون الذهب بالدين، ويسدد بأقساط، فمثلًا يشتري بائع الذهب المفرق بمائة ألف، أو أقل، أو أكثر، ويسددها أقساطًا، فهل في هذا إثم.. ذهب بذهب بفارق الصنعة؟","title":"حكم بيع الذهب بالدين مع التقسيط","answer":"الجواب: \n\nهذا لا يجوز، بيع الذهب، أو غيره من العٌمَل إلى أجل، لا يجوز هذا ربًا، فإذا باع ذهبًا بدولار، أو بجنيه استرليني، أو بدينار أردني، أو عراقي، أو غير ذلك، أو بالعملة السعودية نسيئة، أو مع التفرق من غير قبض، هذا هو الربا.\n\nالنبي  قال: الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح، مثلاً بمثل سواء بسواء يدًا بيد، فإذا اختلفت هذه الأصناف؛ فبيعوا كيف شئتم؛ إذا كان يدًا بيد إذا اختلفت لا بأس بالتفاضل، لكن يدًا بيد، فبيع الذهب بالدولار، أو بالفضة، أو بالدنانير، أو بالريال السعودي يدًا بيد لا بأس، أما نسيئة، أو في وقت آخر، يعني يقول له: أعطيك إياه بعدين؛ لا يصح، لا بد يدًا بيد.\n\nوهكذا بيع الذهب بالذهب أكثر، الذهب الجديد بالذهب القديم مع الفرق، هذا ما يجوز، لأن الذهب .. يكون مثلًا بمثل، سواء بسواء.\n\nولما اشترى رجل قلادة يوم خيبر، قلادة فيها ذهب وخرز؛ أنكر عليه النبي ﷺ وقال: لا تباع حتى تفصل يعني: لا تباع حتى يفصل الذهب لحاله، والخرز لحاله، وهذا الذي يفعله يقولون: هذا مقابل الصيغة، هذا غلط، الواجب أن يباع الذهب بعملة أخرى حتى لا يقع الربا، أما ذهب بذهب، ولو كان هذا أطيب، وهذا أردأ لا بد يكون مثلًا بمثل.\n\nولما اشترى بعض الصحابة الصاعين من التمر بثلاثة آصاع من التمر؛ أنكر عليه النبي ﷺ وقال: أوه -أي- عين الربا، مع أن الصاعين أفضل من الثلاثة؛ لأنه تمر طيب، لكن أنكر عليه النبي ﷺ قال: عين الربا لا تفعل، بع الجمع بالدراهم ثم اشتر بالدراهم جنيبًا يعني تمرًا طيبًا.","link":"https://binbaz.org.sa/fatwas/3252/حكم-بيع-الذهب-بالدين-مع-التقسيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1585.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7196,"question":"بخصوص العمل في تحويل الأموال بواسطة المصارف من ريال، إلى جنيه سوداني هذا يؤثر في اقتصاد السودان، ما رأي سماحتكم، وما حكم ذلك؟","title":"حكم صرف العملة إلى عملة أخرى أثناء تحويلها","answer":"الجواب:\n\nما نعلم بأسًا في التحويل، إذا حول دولارات إلى السودان، أو إلى غير السودان، أو الجنيه الاسترليني، أو غير ذلك بالعملة التي يريد، والتي يرغب فيها، لكن يدًا بيد، لا بد يكون يدًا بيد، يقبض العملة التي يريد، ويحولها.\n\nوأجاز قوم هذا الشيك؛ لأنه قبض، هذا الشيك إذا كان على بنك فيه رصيد للشخص، فإن قبض الشيك قبض للمال؛ لأنه يقوم مقامه، ليس مثل الدين، يقوم مقامه؛ لأنه مال، أينما ذهب به؛ حصل المطلوب، لكن إذا تيسر أن يقبض ماله بنفسه ثم يحوله؛ يكون هذا أكمل.\n\nالسؤال: لا، هو يحول الجنيه السوداني إلى دولار، ويحتفظ بالدولار معه؛ ليبيعه في السودان، أو في مصر، يسموه السوق السوداء، بدون علم الحكومة؟\n\nالجواب: لكن لابد يقبضها.\n\nالطالب: هو يقبضها فعلًا، ولكن هذا يضر الاقتصاد السوداني، أو المصري في حالة تحويلة عن طريق غير البنك؟ \n\nالجواب: ما نعلم بأسًا في هذا.","link":"https://binbaz.org.sa/fatwas/3268/حكم-صرف-العملة-الى-عملة-اخرى-اثناء-تحويلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1596.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7321,"question":"باستقراء آيات الربا في القرآن الكريم يتبين أن صاحب رأس المال هو المستفيد، وهو صاحب المنفعة وحده، والفقير هو المتضرر، وهو المظلوم، أما المعاملات المصرفية الموجودة اليوم في البنوك فالمستفيد هو صاحب رأس المال الصغير والمنفعة متبادلة، فهو يختلف عن الربا، بل هو عكس الربا، فما رأي سماحتكم في هذا، ألا ترون فيه تيسيرًا للمسلمين، ودفعًا للحرج عنهم؟","title":"تحريم الربا ليس مرتبطا بمعرفة الحكمة","answer":"الجواب: لا هذا غلط، هذه مغالطة، فالمستفيد هذا وهذا، المقترض قد يستفيد يبني له عمارة، يتزوج، يقضي دينه، هو يصبر على الزيادة التي سموها الفائدة، والبنك يستفيد؛ لأنه يصرف هذه الأموال في جهات كثيرة، يصرفها في معاملات كثيرة، في شراء سلع، وفي صرف أموال بأموال، يستفيد. وآخذ القرض قد يستفيد أيضًا فيما اقترض لأجله، في شراء سيارة يستعملها، في تزوج، في عمارة، في قضاء دين عليه قد أشغله صاحبه، إلى غير ذلك، قد يستفيد هذا وهذا، فكل منهما مستفيد، وإن كان بعض أهل الدين قد يكون مضطرًا، قد يكون محتاجًا إلى الدين، وإلى الزيادة التي يسمونها الفائدة، لكن هو مستفيد، وذاك مستفيد، كلاهما مستفيد.  فالذي أعطى المال ويعطى الفائدة هو مستفيد، والبنوك مستفيدة فائدة أكثر؛ لأنها تتصرف تصرفات كثيرة بأموال عظيمة، ويحصل لها فوائد كثيرة، فهي أيضًا مستفيدة. والربا محرم، سواء استفاد هذا أو هذا أو كلاهما، علينا أن نلتزم ما قاله الله ورسوله، وأن نحذر ما حرم الله ورسوله، وأما مراعاة الحكمة وتحققها وعدمها فهذا شيء آخر، إذا تحققت فنور على نور، وإذا تحققت الحكمة أو لم تعرف الحكمة لم يضرك ذلك، والحكمة في هذا واضحة؛ لأنهم يتساهلون في هذه الأمور ما دام يرجو هذه الفائدة، فهو يعطي الأموال الكثيرة، يرجو هذه الفائدة، وقد ينزل الله بها بأسه، فتتلف عليه أمواله، وتنزل العقوبة بصاحب المال، فيفلس وتذهب الأموال الكثيرة هدرًا من غير فائدة لهذا الذي وضع المال؛ فيخسر هذا وهذا، نسأل الله العافية. ثم لو قدرنا أنه ربح ربحًا كثيرًا، وأنه أراد الربح؛ فليس هذا علة في الربا، بل هذا مما يحرم الربا، إذا كان المضطر يمنع من الربا وهو مضطر ومحتاج، فكيف بالذي هو متساهل يريد الزيادة، ويريد الفضل، ويريد التمتع بالزيادات وليس مضطرًا إليها؟! فهو أولى بأن يمنع من تعاطي الربا.","link":"https://binbaz.org.sa/fatwas/3397/تحريم-الربا-ليس-مرتبطا-بمعرفة-الحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1711.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7352,"question":"لي قطعة أرض أحرثها، فذات يوم احتجت لمبلغ عشرة آلاف ريال لكي أسدد هذا المبلغ الذي علي، ثم رهنت الأرض بعشرة آلاف، وسجلت هذا المبلغ الذي علي، ثم إن هذه الأرض تبقى عند صاحبها يحرثها ويستثمرها جميع حصادها إلى أن أسدد له المبلغ، فهل في هذا ربا؟","title":"حكم استثمار المرهون حتى سداد القرض","answer":"الجواب: نعم، الربا كونه يأخذ الأرض يستثمرها، يستفيد منها بدون أجرة من أجل إمهالك في القرض، حتى تعطيه القرض، هذا ما يجوز، هذا ربًا، القرض ما يكون فيه زيادة، قرض مثلًا بمثل من دون زيادة، أما أن يشرط عليك أنه ينتفع بالأرض، ويستعملها حتى تؤدي إليه، فهذا مثل ما أقرضته ألفًا بألف ومائة، أو بألف ومائتين، هذا ربًا ما يجوز. السؤال: ...؟ الجواب: البيع شيء آخر، إذا اقترض المال وباعه الأرض إلى أجل معلوم ما هو متحيل، ما قصد التحيل حقيقة، ما هو تحيل على أنه يستثمرها ويعيدها إليه، بل حقيقة باعها عليه وجعل له خلال شهرين ثلاثة إن وجد المال وإلا الأرض له ما في بأس، أما إذا كان حيلة ما يجوز. السؤال: والذي يسمونه إقالة، يعني شبه بيع يوفي عليه الوقت المعلوم إن وفي فيها ونعمة وإلا حل عليها البيع؟ الجواب: لا، تكون له، الثمرة لصاحبها لأن هذا يتخذ حيلة، فالثمرة للبائع، لا للمشتري، حتى لا يتخذ حيلة.","link":"https://binbaz.org.sa/fatwas/3419/حكم-استثمار-المرهون-حتى-سداد-القرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1730.mp3","categories":["الربا والصرف","مسائل متفرقة في العقيدة","قضايا معاصرة"]},{"id":7502,"question":"سماحة الشيخ! هذه رسالة وردت من المستمع (ع. ع. ص) يسأل عن الزيادة في قروض البنوك، يقول: فضيلة الشيخ عبد العزيز بن باز حفظه الله! السلام عليكم ورحمة الله وبركاته، وبعد: أفيدكم بناحية هامة تمس العقيدة الإسلامية: وهي أن البنوك إذا أراد أحد أن يقترض منهم طلبوا عليه زيادة معينة عند تسديد القرض، ويشترطون على المقترض رهن الصك ولا يتم رهن الصك إلا بموافقة المحكمة أو كتابة العدل، والسؤال هو: هل يجوز أن يشترط البنك على المقترض زيادة معينة؟ وهل يجوز للمحكمة أو كتابة العدل أن توافق على رهن الصك للبنك مع علمها بأن في هذا الاقتراض معاملة ربوية؟ الرجاء توجيه نصيحة للناس ولأصحاب البنوك في هذه الناحية، كما أرجو الإجابة على سؤالي وفقكم الله.","title":"حرمة القروض الربوية","answer":"الجواب: بسم الله الرحمن الرحيم.\nالحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفهذا القرض الذي سأل عنه السائل محرم بلا شك، وتحريمه محل إجماع بين أهل العلم؛ لأن الزيادة في القرض ربا بلا شك عند أهل العلم، فلا يجوز للمسلم أن يقترض من أي إنسان من البنك أو غير البنك بزيادة عند الرد، كأن يقترض مائة على أن يرد إليه مائة وعشرة، أو مائة وخمسة، أو مائة وريال واحد، كل ذلك ربا، وهكذا ألف على أن يرد عليه ألف وخمسة، أو ألف وعشرة، أو ألف وعشرين، كل ذلك ربا، لا يجوز لمسلم أن يتعاطى هذا، لا من البنك ولا من غير البنك، لا مع الأفراد ولا مع الجماعات، كله منكر، وقد كتبنا في هذا غير مرة، ونشر في الصحف المحلية وغيرها، فالأمر واضح ولكن الكثير من الناس يقدم على الربا ولا يبالي إيثاراً للعاجل على الآجل، وعدم العناية بأمر الله سبحانه وتعالى، وإذا علمت المحكمة هذا الأمر، فليس لها أن توافق على ذلك، وليس لها أن توافق على تثبيت الصك؛ لأن هذا من باب الإعانة على الربا، ولكن فيما بلغني أن المحاكم لا تدري عن هذا؛ لأنهم يجملون الزيادة في القرض ويدعون أن لهم على فلان كذا وكذا، ويدخلون الزيادة في القرض، فلا يعلم القاضي الحقيقة، ويكتب لهم على دين معين ليس فيه ذكر الزيادة المعروفة.\nفالحاصل: أن الحاكم إذا عرف ذلك أو كاتب العدل لا يجوز له التوثيق لهذا الدين الذي فيه الربا، ولكن قد يعمون هذا ويخفونه ولا يبينونه، فيكتب كاتب العدل أو الحاكم التوثيق؛ لأنه لا يعلم الحقيقة، ومن جهل فهو معذور. نعم.","link":"https://binbaz.org.sa/fatwas/4463/حرمة-القروض-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00801.mp3","categories":["الربا والصرف"]},{"id":7529,"question":"هذه الرسالة وردت من عادل إبراهيم الحمود الخبر، يقول: أرجو من سعادتكم أن تعرضوا هذه الرسالة على سماحة الشيخ/ عبد العزيز بن عبد الله بن باز وجزاكم الله خيراً -نحن يا أخ عادل نعرضها الآن على سماحته- فضيلة الشيخ/ عبد العزيز بن عبد الله بن باز وفقه الله، لا يخفى عليكم بأننا نمر في هذه الأيام بفتن شتى، حتى أن أحدنا قد يقع في إحداها وهو لا يعلم، لذلك وجب  في هذه الأيام كثر التعامل بالأسهم البنكية وغيرها، حتى أننا لا نجد بيت من بيوت المسلمين إلا وقد تعامل بها إلا ما رحم الله وتعاطاها، وقد يظن الكثير أن التعامل بها حلالاً، وآخرون يقولون: إنه حراماً، فاختلط الأمر علينا حتى وجدنا فيكم من يرشدنا ويرشد المسلمين إلى ما فيه هدايتهم وصلاحهم إن شاء الله تعالى، نرجو الإفادة في ذلك؟","title":"حكم التعامل بالأسهم البنكية","answer":"الجواب: لا شك أيها الأخ السائل أن البنوك الربوية يحرم التعامل معها ويحرم مساعدتها، فالبنوك التي تعامل بالربا لا يجوز الاشتراك فيها ولا التعاون معها؛ لأن ذلك داخل في قوله سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] فلا يشترى منها سهام، ولا تعان بشيء؛ لأنها تعان على الإثم في هذا.\nأما البنوك الإسلامية التي لا تعامل بالربا فلا بأس بالاشتراك فيها والتعاون معها؛ لأنه تعاون على البر والتقوى، فينبغي للمؤمنين أن يحذروا هذه الأشياء التي حرم الله عليهم، فالتعامل مع البنوك الربوية مما لا يرضاه الله سبحانه، بل لا يجوز ذلك، سواء كان التعاون بالكتابة، أو الوظيفة، أو التعاون بالمساهمة فيها وبذل المال فيها والمشاركة، كل هذا لا يجوز؛ لأن الرسول ﷺ: لعن كاتب الربا، وآكل الربا، وموكله، وشاهديه؛ لأنهم يتعاونون في هذا، والتعاون على الإثم والعدوان أمر محرم، فالكتابة للربا، والشهادة على الربا، وأكل الربا، وإيكال الربا كله محرم، وهكذا أنواع التعاون مع المرابين. نعم.","link":"https://binbaz.org.sa/fatwas/4503/حكم-التعامل-بالاسهم-البنكية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_010/01007.mp3","categories":["الربا والصرف"]},{"id":7573,"question":"سؤال حامد محمد من البحرين يقول: سمعت أيضاً في برنامجكم أن المعاملة مع البنوك محرمة والشيكات كذلك، وأنا لابد من إرسال نقودي عن طريق البنك؛ لأنني لا أستطيع أن أذهب إلى مصر بالنقود التي معي ما زاد عن خمسين جنيه، فما الحل في ذلك، هل نرسل بواسطة البنوك أم لا؟","title":"حكم تحويل الأموال عن طريق البنوك","answer":"الجواب: أما المعاملة مع البنوك الربوية بالفوائد هذا لا يجوز، كونه يعطي مالاً ويأخذ عليه فوائد، أو يستقرض من البنك بفائدة، هذا لا يجوز، هذا ربا بلا شك وهو محرم، أما كونه يحول ماله من بنك إلى بنك لأجل المشقة في نقله، أو الخوف في نقله، فنرجو أن لا حرج في هذا، وهذا من جنس الشيء الذي يضطر إليه الإنسان، هذه أمور اليوم ضرورية، تعتبر ضرورية، وهو لا يقصد الربا وإنما حول ماله من جهة إلى جهة فلا يضره ذلك، ولا حرج في هذا إن شاء الله.","link":"https://binbaz.org.sa/fatwas/4579/حكم-تحويل-الاموال-عن-طريق-البنوك ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01609.mp3","categories":["الربا والصرف"]},{"id":7697,"question":"أيضاً يقول: شاب عليه دين ذهب إلى أحد البنوك، وأخذ سلفة مقدارها عشرة آلاف ريال، على أن يرجع المبلغ بعد سنة اثنا عشر ألف ريال، هل هذا ربا، وهل عليه أثم؟","title":"حكم الاقتراض بشرط الفائدة","answer":"الجواب: هذا ربا، إذا أخذ من البنك -مثلاً- عشرة آلاف قرضاً على أن يرده اثني عشر ألف، هذا من الربا الصريح، لا شك في ذلك عند جميع أهل العلم، هو ربا لا شك في ذلك، سواء كان من البنك أو من غير البنك، وهذه الفوائد الربوية قد نص أهل العلم على تحريمها، فلا يجوز لأحد أن يتعاطاها لا مع البنك ولا مع غير البنك، أن يقترض شيئاً ليرد أكثر منه، هذا لا يجوز أبداً ولو درهماً واحداً، لكن إذا أخذ قرضاً من دون فائدة ثم رد خيراً منه، تبرعاً منه ومعروفاً منه، فلا بأس لقول النبي ﷺ: إن خياركم أحسنكم قضاء فإذا اقترض من زيد عشرة آلاف من دون شرط فائدة معروفاً، ثم لما ردها عليه زاده شيئاً هذا لا بأس، معروفاً من دون شرط، إن خيار الناس أحسنهم قضاء، كان النبي يرد أحسن وأفضل عليه الصلاة والسلام إذا اقترض. نعم. \nالمقدم: لكن لو كان فيه التواطؤ -مثلاً- اشترط المقرض قال: تزودني مثلاً أو من هذا القبيل ولم يحدد شيئاً؟ \nالشيخ: التواطؤ ما يجوز، ولو ما كتب، ما دام فيه التواطؤ لا يجوز، لا تجوز الزيادة، بل يرد مثل ما أخذ سواء، هذا الواجب عليه. نعم.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4896/حكم-الاقتراض-بشرط-الفاىدة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02808.mp3","categories":["الربا والصرف"]},{"id":7911,"question":"في هذه الرسالة وردتنا من بعض المستمعين يقول: السلام عليكم ورحمة الله وبركاته.أرجو عرض سؤالي هذا على أحد المشايخ المجيبين في برنامج نور على الدرب، يقول: شركة سعودية كبيرة تدير مرفقاً هاماً من مرافق بلادنا العزيزة وأنا أحد موظفيها، وسؤالي: إذا كانت هذه الشركة تتعامل مع البنوك بحيث تودع فيها مبالغ لمدد قصيرة كشهر وشهرين وثلاثة شهور بفوائد؛ ولأنها تحتاج إلى سيولة نقدية، فهي تودع المبالغ التي تحتاجها حالاً في البنوك لفترة قصيرة جداً مقابل فوائد مئوية، هل العمل في هذه الشركة حلال أم حرام، علماً بأنها تحصل على معونة بنسبة كبيرة جداً، ويساهم فيها المواطنون بأسهم كثيرة مضمونة من قبل الدولة، أخوكم مؤمن ؟","title":"حكم العمل في شركة تتعامل مع البنوك الربوية","answer":"الجواب: الذي يظهر أن العمل في هذه الشركة لا يحرم؛ لأن المحرم فيها قليل بالنسبة إلى ما يأتيها من مساهمات وما يحصل لها من المساعدات لكن إذا تورع الإنسان وتركها وعمل في شركة أخرى لا تعمل هذا العمل أو في عمل آخر يكون بعيداً عن الربا وعن الحرام يكون أحوط، مثل ما قال النبي ﷺ: دع ما يريبك إلى ما لا يريبك.\nوالورع في مثل هذه الأمور من المهمات، والنبي ﷺ يقول: من اتقى الشبهات فقد استبرأ لدينه وعرضه هذه المعاملة الربوية مع البنوك تجعل المال فيه شبهة، وتجعل فيه خلطاً من الحرام، فإذا ترك المسلم العمل معها والمشاركة في أعمالها من باب الاحتياط هذا حسن.\nوأما التحريم فلا يظهر التحريم لأجل وجود الأموال الكثيرة السليمة فيها من الربا، والمال المشترك الذي فيه خلط من الربا لا يحرم على المسلم أن يعامل أهله، قد عامل النبي ﷺ اليهود واشترى منهم وهم أموالهم فيها الربا، فيها أشياء من المحرمات، والنبي ﷺ اشترى من الكفار، والكفار لا تخلو أموالهم من ذلك.\nلكن كونه يعمل الربا بنفسه أو يساعد عليه أو يعلم أن هذا المال ربا هذا لا يجوز له إذا علم، أما كونه مالاً دخل فيه الربا أو دخل فيه شيء من الحرام وهو مال كثير فالأصل السلامة، والأصل العافية، فلا يحرم على الإنسان إلا ما اتضح له تحريمه وعرف يقيناً أنه محرم، أو أنه من كسب محرم. نعم.","link":"https://binbaz.org.sa/fatwas/5400/حكم-العمل-في-شركة-تتعامل-مع-البنوك-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06208.mp3","categories":["الربا والصرف"]},{"id":7991,"question":"سماحة الشيخ! هذه الرسالة وردتنا من مقدمها محمد عبد الله الحدادي بجدة، يقول: صاحب الفضيلة! ظهرت شبهة ربا أو هو الربا نفسه فيما أعتقد ولا أدري بين باعة أهل الذهب ألا وهو: إذا جاء شخص ما يحمل أنواعاً من الحلي ذهباً وقصده بدلاً عنها من نوعها، فصاحب الذهب -أي: البائع- قد يزن هذا الذهب ليشتريه بمثله ذهباً من نوعها حلي، ولكن يطلب زيادة على الذهب كبيرة، فهل هذا من الربا، أفتونا مأجورين وفقكم الله؟","title":"حكم بيع الذهب بالذهب مع الزيادة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن النبي الكريم عليه الصلاة والسلام أنه قال في الذهب: الذهب بالذهب مثلاً بمثل، سواء بسواء، يداً بيد فإذا كان هذا الصائغ أو .. بائع الذهب يطلب الزيادة على الوزن وقع في الربا، فإذا كان في الحلي الموزونة تزن عشرين مثقالاً وذهبه كذلك، ولكن يريد المبذول زيادة من الورق، من العملة الورقية، فهذا لا يجوز؛ لأنها تقابل جزءاً من المبذول ... من عنده، فيكون باع الذهب بأقل منه والرسول ﷺ قال: مثلاً بمثل، سواء بسواء فالحاصل أنه إذا باع ذهب بذهب لابد أن يكونا مثلين، لا يزيد هذا على هذا لا من جنسه ولا من غير جنسه، فإذا زاد أحدهما ورقاً أو شيئاً آخر من السلع جاء الربا؛ لأن الرسول ﷺ قال:  مثلاً بمثل سواء بسواء يداً بيد وبهذا تعلم أن هذا البيع ربا. نعم.","link":"https://binbaz.org.sa/fatwas/5539/حكم-بيع-الذهب-بالذهب-مع-الزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07301.mp3","categories":["الربا والصرف"]},{"id":8274,"question":"أخونا يقول: شخص اقترض مبلغاً من شخصية اعتبارية حوالي مليون ريال تحت حساب ما يسمى جاري مدين وبعد فترة اضطرته الظروف ولم يتمكن من التسديد فوجد هذه الشخصية طيلة هذه المدة تأخذ فوائد بمعدل عشرة في المائة فيرغب الانتهاء فما هو العمل! كما أن الشخصية لم تعطه هذا المبلغ إلا مقابل عقار والعقار أصبح الآن لا يساوي شيئاً! وإذا أرادت الشخصية أن تخصم الفوائد من رأس ماله فما الحكم أيضاً أفيدونا عن هذه الأمور لو تكرمتم؟","title":"حكم من اقترض مالاً ثم ألزمه المقرض بأرباح وفوائد","answer":"الجواب: ليس للشخصية التي أشرت إليها واقترضت منها ليس لها أن تأخذ الفوائد وليس لك أن تستجيب لها في ذلك لو طلبت إنما عليك أن تؤدي المال الذي أخذته منها برأسه فقط من دون زيادة متى يسر الله لك وزال العسر، والله يقول سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280] فعلى الجهة الذي أقرضتك أن تنظرك حتى يتيسر أمر العقار فيباع فتوفي أو يتيسر لك أمر آخر فتوفي منه وأما أن تعطيهم فائدة من أجل التأخير فليس لك ذلك وليس لهم ذلك بل هذا عين الربا الذي كانت تفعله الجاهلية وقال الله فيه سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ  ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة:278-279].\nهذا الربا الذي تريد الجهة أن تحملك إياه لا يجوز تحمله بل يجب إسقاطه عليك وعليهم وعليك رأس المال أن تؤديه إليهم ويكفي وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة:279] لا تظلمون ببخس رأس المال أو تأخيره بغير الحق ولا تظلمون بتحميلكم الفائدة الزائدة لا هذا ولا هذا وإذا أبت هذه الجهة فعليك أن تحاكمها إلى المحكمة الشرعية. نعم.","link":"https://binbaz.org.sa/fatwas/6080/حكم-من-اقترض-مالا-ثم-الزمه-المقرض-بارباح-وفواىد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_106/10604.mp3","categories":["الربا والصرف"]},{"id":8276,"question":"رسالة أخرى وصلت إلينا من الأخ: عبد الستار موسى مصطفى يقول: مدرس مصري يعمل في الحديدة باليمن، أخونا يقول: معلوم أن المغترب يعود إلى بلده وقد اشترى من العملات العالمية مثل: الدولار وجنيهات الذهب أو حتى أي عملة غير عملة بلده، ثم يعود لبلده ليبيعها فيسعى وراء أعلى سعر يبيعه به، ومن أماكن البيع ما هو رسمي لدى الدولة ومنها ما يسمى السوق السوداء، والسؤال هو: متى يكون هذا ربا فضل وماذا ينبغي عندئذ؟ أفيدونا أفادكم الله.","title":"حكم بيع عملة بعملة أخرى","answer":"الجواب: العمل تختلف، فإذا باع عملة بعملة أخرى يداً بيد فهذا ليس فيه ربا، كأن يبيع الدولار بالجنيه المصري أو بالعملة اليمنية يداً بيد فلا بأس، وهكذا إذا باع أي عملة بعملة أخرى يداً بيد فإنه ليس في هذا ربا، أما إذا باع العملة بعملة أخرى إلى أجل كأن يبيع الدولار بالعملة اليمنية إلى أجل أو بالجنيه المصري أو الاسترليني أو الدينار الأردني والعراقي أو غير ذلك إلى أجل هذا يكون ربا؛ لأنها منزلة منزلة الذهب والفضة، فلا يجوز بيع بعضها ببعض نسأ بل لابد من القبض في المجلس.\nأما ربا الفضل فهذا يقع في العملة بنفسها، إذا باع العملة بالعملة نفسها متفاضلاً، كأن يبيع الجنيه الاسترليني بجنيه استرليني وزيادة كجنيه استرليني بجنيهين هذا ربا، ولو كان يداً بيد ربا، أو يبيع العملة السعودية عشرة بعشرة أو زيادة، عشرة ريالات بإحدى عشر ريال هذا ربا فضل.\nوإذا كان إلى أجل صار ربا فضل ونسيئة جميعاً فيه نوعا الربا، وهكذا أشباه ذلك كالدولار بدولارين بثلاثة إلى أجل أو حالاً، إن كان حالاًَ يداً بيد هو ربا فضل، وإن كان إلى أجل كان ربا فضل ونسيئة جميعاً اجتمع فيه الأمران، هذه وجوه الربا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6083/حكم-بيع-عملة-بعملة-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_099/09906.mp3","categories":["الربا والصرف"]},{"id":8301,"question":"هذه رسالة من السائل (م. ح. م) من المملكة العربية السعودية، يقول في رسالته: أنا شاب أدرس في المدرسة طيلة أيام العام الدراسي، فإذا جاءت الإجازة الصيفية أراد والدي أن أعمل في هذه الإجازة في أحد البنوك التي تتعامل بالربا، فهل أطيع والدي وأعمل في الإجازة في البنك أم لا يجوز لي طاعته، وكيف أقنعه؟","title":"حكم طاعة الوالد في العمل في بنك ربوي","answer":"الجواب: العمل في البنوك الربوية أمر منكر لا يجوز، والله جل وعلا قد وسع الطريق ويسر الأمر، ولم يجعل مكاسب الناس محصورة في الحرام، بل جعل لهم مكاسب كثيرة كلها حلال، من البيع والشراء، والزراعة، والصناعات المتنوعة.. إلى غير ذلك من أنواع المكاسب الطيبة، أما العمل في البنوك فهو إعانة على الإثم والعدوان، ومعاونة على الربا، وقد صح عن رسول الله عليه الصلاة والسلام أنه لعن آكل الربا وموكله وكاتبه وشاهديه وقال: هم سواء رواه مسلم في الصحيح، فالواجب عليك أن لا تعمل في البنوك وأن تعتذر لوالدك بالعذر المناسب وتوضح له أن هذا تعاون معهم على الإثم والعدوان وهذا لا يجوز؛ حتى يقتنع، وحتى يعلم أنك مصيب.\nوالحاصل: أنك لا تطيعه في هذا إنما الطاعة في المعروف، لكن ترد عليه رداً جميلاً، وتخاطبه مخاطبة حسنة وتعتذر إليه عذراً جميلاً، فتقول: يا والدي! يشق علي أن أعصيك وأحب أن أطيعك في كل شيء، لكن طاعة الله فوق ذلك، وحق الله فوق ذلك، فأرجو أن تعذرني وأن تسمح عني سامحك الله وجزاك خيراً، وما أشبه هذا من الكلام الطيب، فإن قنع فالحمد لله وإلا فاترك المعصية ولو لم يقنع لكنك تجتهد أبداً أبداً في طاعته، وفي إقناعه، وفي طلب رضاه، وفي التواضع له مهما أمكن.\nالمقدم: نعم، جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6117/حكم-طاعة-الوالد-في-العمل-في-بنك-ربوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20105.mp3","categories":["الربا والصرف"]},{"id":8364,"question":"رسالة أيضاً وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: (م. ح. ر) أختنا تقول: نسمع عن البنوك الإسلامية، هل هي كالبنوك الموجودة الآن أو أنها تختلف في شيء عنها؟ وما حكم التعامل مع تلك البنوك؟","title":"حكم التعامل مع البنوك الإسلامية","answer":"الجواب: البنوك الإسلامية تجتنب المعاملة الربوية، فالتعامل معها ليس مثل البنوك الربوية، التعامل مع البنوك الإسلامية لا حرج فيه، والتعامل مع البنوك الربوية فيه الحرج في أي معاملة يكون فيها ربا، أما المعاملات التي ليس فيها ربا مثل: الحوالات بدون ربا، وما أشبه هذا لا بأس، لكن المعاملة الربوية مع أي إنسان سواءً كان مع البنك الربوي أو مع غيره، لا تجوز، وذلك مثل: وضع الودايع بربح خمسة في المائة، عشرة في المائة، الاقتراض بربح خمسة في المائة، عشرة في المائة، أكثر أقل، هذا وأشباهه ربا، سواء كان ذلك مع بنكٍ ربويٍ أو بنكٍ إسلاميٍ، أو مع تاجرٍ، أو مع غير ذلك.\nفالبنوك الإسلامية التي تعتمد شرع الله، التعامل معها طيب وفيه عون لها على سيرها في هذا السبيل، والتعاون مع البنوك الربوية بالربا أمر لا يجوز، وهكذا مع غير البنوك، كالتجار والأفراد لا يجوز التعاون بالربا أبداً مع أي أحد.\nأما البنوك الإسلامية فالواجب تشجيعها والعناية بها، والواجب على القائمين عليها أن يحذروا كل ما يتعلق بالربا، وأن يكونوا محققين لما نسبوا إليه بنوكهم، من كونها إسلامية، وأن يحذروا التساهل في ذلك. نعم.\nالمقدم: بارك الله فيكم.\nسماحة الشيخ! يثير الناس قولهم: إن هذه البنوك لا تستغني هي أيضاً عن التعامل مع تلك البنوك الربوية؟\nالشيخ: أما ما اطلعنا عليه، فالذي ظهر منهم أنهم يتحرجون من ذلك، ويبتعدون عن الربا، أما ما يخفى فالله جل وعلا هو الذي يعلم، سبحانه وتعالى، لكن البنوك الإسلامية لها أعداء ولها خصوم لا يصدقون عليها، فالواجب تشجيعها والعناية بها، والواجب على القائمين عليها أن يبتعدوا عن كل شبهة، حتى لا يجد خصومهم سبيلاً إلى الطعن في أعمالهم.\nالمقدم: بارك الله فيكم. لكن فيما إذا كان تعاملها مع البنوك الأخرى سماحة الشيخ في غير شئون الربا، كالحوالات وما أشبه ..... ؟\nالشيخ: ما فيه بأس لا حرج في ذلك، الحمد لله. نعم.\nالمقدم: سماحة الشيخ! وقد تفضلتم بإثارة قضية الاقتراض من البنوك والفوائد عليها، هل هناك فرق بين الاقتراض للاستثمار، والاقتراض للاستهلاك؟\nالجواب: لا فرق في ذلك، إذا اقترض للاستثمار أو للاستهلاك على وجه الربا، فقد أتى الربا، سواء كان ذلك القرض سوف يستثمره في أعمال أخرى، أو كان لحاجته كله ربا، كله ممنوع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6213/حكم-التعامل-مع-البنوك-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11404.mp3","categories":["الربا والصرف"]},{"id":8471,"question":"أخونا محمد التونسي يسأل سماحة الشيخ ويقول: شيخنا الجليل ابن باز نتوجه إليكم بالأسئلة التالية رجاء أن تفيدونا بخصوصها ولكم من الله الأجر والثواب العظيم، الموظفون في تونس يتسلمون رواتبهم عن طريق الحسابات الجارية بالبريد أو البنك بصورة إجبارية، فلا تدفع الرواتب إلا بهذه الصورة تسهيلاً لعملية الدفع ونتيجة لهذا يسلم البنك أو البريد لصاحب كل حساب مبلغاً زائداً في نهاية كل سنة يزيد أو ينقص حسب كمية ومدة بقاء المبلغ في الحساب الجاري، فهل يصح الأخذ لهذا المبلغ الزائد أم يعتبر رباً ومالاً حراماً، وما وجه حرمته إن كان كذلك، وكيف يتخلص منه؟","title":"حكم الزيادة التي يأخذها الموظف من البنك نهاية كل سنة","answer":"الجواب: إذا لم يكن هذا عن اتفاق وإنما هو شيء بذله البنك الذي تحول من طريقه الرواتب، أعطى الموظفين هذه الزيادة من دون مشارطة ولا اتفاق بينه وبين الدولة ولا بينه وبين أهل الرواتب إنما هو شيء منه، بالنظر إلى أنه انتفع بها واستفاد منها، فهذا لا يضر ولا حرج على صاحب الراتب في أخذه.\nأما إذا كان عن اتفاق بينه وبين الدولة على أنها تحول من طريقه الرواتب وأنه يعطي بدلاً من هذه الرواتب يعطي زيادة في مقابل انتفاعه بها فإذا حولوا من طريقه مثلاً مائة ألف دولار، أعطى أهلها مع المائة ألف، ألف دولار زيادة من اتفاق بينه وبين الدولة، أو بينه وبين الموظفين لو كان الأمر باختيارهم هذا يكون من الربا، أما شيء ليس باختيار الموظفين وليس من عمل الدولة، لم تشرط عليهم الدولة هذا الشيء، وإنما هم بذلوه فقط من أجل أنهم انتفعوا بهذه الدولارات أو بهذه الدراهم أو الجنيهات أو نحو ذلك هذا لا بأس به، مثلما قال النبي ﷺ: إن خيار الناس أحسنهم قضاء الذي انتفع بمالك وأعطاك شيئاً من نفسه عن طيب نفس من دون شرط منك فلا حرج في ذلك.\nفلو أنك أقرضت إنساناً مائة ألف قرضاً حسناً من دون مشارطة في شيء، ثم لما قضاك المبلغ زادك شيئاً مكافأة حسنة شكراً لك على إقراضك إياه، هذا لا حرج فيه؛ لقول النبي ﷺ: إن خيار الناس أحسنهم قضاء وقد اقترض النبي ﷺ أربعين ألفاً فرد ثمانين ألفاً كما ذكر ذلك ابن القيم وجماعة.\nفالحاصل: أنه إذا كان القرض ليس فيه مشارطة وإنما أقرضته شيئاً فلما قضاك زادك فهذا لا بأس به، أما أن يزيد يعطيك قبل الوفاء حتى تمهله فلا يجوز، أو تشترط عليه قبل ذلك أنه يعطيك كذا وكذا هذا ربا، أما إذا كان عند الوفاء أعطاك شيئاً من دون شرط ولا اتفاق ولا تواطؤ هذا ليس من الربا في شيء، وإنما الربا الذي نهى عنه أصحاب النبي ﷺ وجاءت السنة به وجاء القرآن به أيضاً هو الشيء المتواطئ عليه والمتفق عليه أنك تؤجله ويعطيك زيادة عن التأجيل، أو يهدي لك هدايا حتى تمهله حتى تؤخر كما قال عبد الله بن سلام وزيد بن ثابت وابن مسعود وجماعة قالوا: إذا كان لك على شخص دين فأهدى إليك حمل قت أو كذا أو كذا فلا تقبله فإنه ربا؛ لأنه إنما أهدى إليك حتى تمهله حتى تنظره، فكأنه يقول: أمهلني ولك كذا وكذا، فهذا من ربا الجاهلية.\nأما هو لما قضى دينك لما أعطاك وأوفاك زادك من عنده شيئاً من دون مواطأة منك ولا شرط منك بل مجرد إحساناً منه، مجرد مكافأة فلا حرج في ذلك.\nوهكذا هؤلاء الذين تحول لكم الرواتب من طريقهم إذا أعطوكم ذلك من دون مشارطة ولا تواطؤ لا منكم ولا من الدولة فلا حرج في ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6488/حكم-الزيادة-التي-ياخذها-الموظف-من-البنك-نهاية-كل-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_124/12405.mp3","categories":["الربا والصرف"]},{"id":8535,"question":"وهذه رسالة من السائل عمر أحمد الكتوتابي من السودان، يقول: ما حكم رجل استلف قدراً من المال بنسبة مئوية هل في هذا ربا أم لا؟","title":"حكم من اقترض ديناً بنسبة بفائدة","answer":"الجواب: إذا اقترض شيئاً من المال بنسبة مئوية فائدة فهذا من الربا، فإذا اقترض من أخيه مثلاً ألف ريال على أنه يرد عليه ألف وخمسين ريال هذا ربا، أو اقترض مائة على أنه يرد مائة وريالين.. مائة وثلاثة، فهذا ربا، لا خلاف في هذا بين أهل العلم، ولا يجوز له هذا، بل يرد رأس المال فقط، لا يلزمه إلا رأس المال. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6620/حكم-من-اقترض-دينا-بنسبة-بفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20511.mp3","categories":["الربا والصرف"]},{"id":8998,"question":"رسالة وصلت إلى البرنامج من المستمع (م. ح. س) أخونا يقول: أنا أعمل في إحدى المحلات لبيع المجوهرات في منطقة القصيم، وكما علمنا أنه لا يجوز بيع الذهب إلا بالنقد ولم يجز فيه الدين، لكن صاحب المحل يقول: إذا جاءوا أصحابي المعروفين أعطهم السلف، فهل هذا صحيح أم لا؟","title":"حكم بيع الذهب إلى أجل","answer":"الجواب: الذهب لا يباع بالذهب إلا وزنًا بوزن مثلًا بمثل سواء بسواء، وليس له أن يبيع بالزيادة ولا بالغائب، فإذا كان عنده سلعة ذهبية، أسورة أو خواتم أو قلائد أو غير ذلك فلا مانع من بيعه لها بالنقد يدًا بيد من الأوراق المعروفة، أو بالفضة المعروفة يدًا بيد، أما أن يبيعها بذهب آخر سواء من عيارها أو من غير عيارها فلا يجوز إلا بشرطين:\nأحدهما: التساوي في الوزن.\nوالثاني: التقابض في المجلس، فإن كانا لا يتساويان فإنه يبيعها عليه، يبيع السلعة عليه بنقد من النقود المعروفة بالدولار، بالريال السعودي، وغير ذلك يدًا بيد، أما أن يبيع ذهب بذهب وزيادة فلا يجوز، يعطيه سلعة ذهبية بسلعة ذهبية مع زيادة ما يجوز هذا؛ لأن الرسول ﷺ لما رفع إليه أن رجل اشترى قلادة من ذهب فيها خرز، فقال: لا تباع حتى تفصل، فيباع الذهب وزنًا بوزن مثلًا بمثل، ويباع الخرز على حدة، حتى لا يقع التفاضل في الذهب، فليس له أن يبيع الذهب إلا مثلًا بمثل، سواء بسواء يدًا بيد، إذا كان بالذهب، أما إذا كان بأمر آخر بالفضة، بالعمل الورقية فلا بأس لكن يدًا بيد، وإن باعه بشيء آخر من غير العملة كأن باعه الذهب بغنم بإبل، بحبوب، بملابس فلا بأس ولو كان ليس يدًا بيد، لو قال: هذه الخواتم الذهبية أو هذه الأسورة أبيعها عليك بالزولية الفلانية الذي عنده الزولية، أو بالناقة التي عنده يعرفها، أو الفرس التي عندك الفلانية جاز البيع ولو كانت الفرس غائبة ما قبضها في الحال، لأن ما هي بعملة، أو باعها عليه بأرض أو بيت، عمارة باع عليه قلائد وأسورة كثيرة ببيت عنده أو بدكان أو بأرض معروفة كل هذا لا بأس به، ولو تفرقوا من دون قبض. نعم.\nالمقدم: إذًا البيع إلى أجل بالنسبة للذهب جائز سماحة الشيخ؟\nالشيخ: إذا كان بغير العملة نعم، بغير الذهب وبغير العمل المعروفة.\nالمقدم: بالورق مثلًا؟\nالشيخ: لا بأس أن يشتري مثلًا قلادة بأرض عنده، أو ببعير أو البقرة عنده، البيت معروفة يعرفها، نعم، ولو تفرق قبل قبض البقرة أو قبض الشاة أو قبض البعير، أو قبض الأرض. نعم.\nالمقدم: أما بالنقد فلا؟\nالشيخ: أما بالنقد لابد يدًا بيد، سواء كان النقد ورق أو فضة، فإن كان من ذهب من جنسه لابد مع القبض من التساوي وزنًا بوزن مثلًا بمثل، إذا كان من جنس ذهب بذهب يعني، أو فضة بفضة، فلابد من الشرطين: التساوي في الوزن مع التقابض.\nالمقدم: والذين يشترون الذهب الجديد بالذهب القديم ويدفعون الفرق؟\nالجواب: هذا ما يصلح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7156/حكم-بيع-الذهب-الى-اجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17609.mp3","categories":["الربا والصرف"]},{"id":8999,"question":"أخونا أيضًا يقول: يوجد في المحل خواتم خاصة بالرجال وبعض السلاسل ويشتريها الأجانب أيضًا من غير المسلمين، هل الذنب على البائع وهو يعمل براتب أو على صاحب المحل الأصلي؟","title":"حكم بيع خواتم الذهب للرجال","answer":"الجواب: لا مانع أن يشتريها المسلم وغير المسلم، لكن بس بالشروط الشرعية، إن كان ذهب لابد يشتريها بغير الذهب، يدًا بيد من العمل، وإن اشتراها بالذهب فلابد أن يكون بالشرطين؛ التساوي والتقابض سواء كان المشتري مسلمًا أو كافرًا.","link":"https://binbaz.org.sa/fatwas/7157/حكم-بيع-خواتم-الذهب-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17610.mp3","categories":["الربا والصرف"]},{"id":9008,"question":"أولى رسائل هذه الحلقة شيخ عبدالعزيز رسالة وصلت إلى البرنامج من الأخ: حسن أحمد من جيزان، أخونا يقول في رسالته: اتفق حسن وعلي وهما صديقان في العمل على تمويل مشروع بناء عمارة سكنية يقوم بموجبها علي بتمويل المشروع في حدود ثلاثمائة ألف ريال، على أن يسدد حسن هذا المبلغ لـعلي سنوياً من موارده الخاصة، وقد وعد حسن عليـاً طواعية بإعطائه بدون قيد ولا شرط أجار ثلاث شقق من العمارة هبة منه لعلي، ثم إن المشروع انتهى وقد زاد المبلغ من ثلاثمائة ألف ريال إلى أربعمائة ألف ريال. هل المبلغ الذي تعهد به حسن -المدين- لدفعه لعلي -الدائن- من أجار الشقق الثلاث طواعية وهبة هل هو حلال أم يكون فيه شيء من الربا أفيدونا عن هذا الموضوع جزاكم الله خيراً؟","title":"حكم قضاء الدين بزيادة لأجل التأخير","answer":"","link":"https://binbaz.org.sa/fatwas/7166/حكم-قضاء-الدين-بزيادة-لاجل-التاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14701.mp3","categories":["الربا والصرف"]},{"id":9231,"question":"وهذه رسالة وردتنا من علي إبراهيم علي من جمهورية السودان، يقول: إن عمي أخي والدي له مال يشغله بالأرباح الربوية على الناس بزيادة خمسين بالمائة في مدة ثلاثة أشهر فقط حتى ازداد المال بشدة، هل هذا المال حلال؟ وإذا لم يكن حلالاً فماذا يفعل؟","title":"حكم بيع النقود بالنقود إلى أجل والسلعة والتورق","answer":"الجواب: الواجب على المسلم أن يبتعد عن أعمال الربا وأن يحذرها؛ لأن الربا من أكبر الكبائر، يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ [البقرة:278-279]، ويقول : وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُوْلَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ ۝ يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ وَاللَّهُ لا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ [البقرة:275-276].\nفالربا أمره خطير، فالواجب الحذر منه، وهذه المسألة التي سألت عنها فيها تفصيل: فإن كان يبيع النقود بالنقود، المائة بمائة وخمسين، والعشرة بخمسة عشر إلى أجل أو يداً بيد هذا رباً صريح محرم عند جميع أهل العلم.\nأما إن كان قصدك أنه يشتري السلعة ثم يبيعها بزيادة هذا له شأن آخر، فإذا اشترى السلعة بمائة ثم بعد ما يحوزها وتكون في ملكه ويقبضها يبيعها على المحتاج إلى أجل معلوم بمائة وخمسين أو بمائة وأربعين أو بمائة وستين أو بأكثر أو بأقل إلى أجل معلوم هذا لا بأس به على الصحيح، ولا حرج فيه عند جمهور أهل العلم؛ لأن المسألة المذكورة تدعو لها الحاجة، وليس كل واحد يجد حاجته بالهدية أو بالقرض فيحتاج إلى أن يشتري السلع إلى أجل معلوم ولو بالزيادة، وقد يحتاجها للاستعمال كما يشتري سيارة ليستعملها، وكما يشتري البساط ليفرشه ويجلس عليه، وكما يشتري الطعام ليأكله، وقد يشتري ذلك ليبيعه بنقد لحاجته إلى النقد ليسدد ديناً عليه، أو ليعمر بيتاً له، أو ليتزوج، أو لأغراض أخرى، فهذه الصور كلها جائزة إذا كان البائع قد ملك المبيع وقبضه وحازه لديه، من سيارات أو أراضي أو أمتعة أخرى قد حازها وملكها وقبضها ثم باعها إلى أجل معلوم، باع ما يشترى مائة بمائة وخمسين، أو ما يساوي ألفاً بألف وخمسمائة، أو أكثر أو أقل، فالصحيح أنه لا حرج في ذلك، سواء كان أراد بذلك الاستعمال، أو أراد أن يبيع السلعة بنقد ليستعمل النقد في حاجته، وهذه الأخيرة تسمى: التورق، كونه يشتري السلعة إلى أجل أن يبيعها بالنقد ثم ينتفع بالنقد هذا يسميها بعض أهل العلم: مسألة التورق، ويسميها العامة: الوعدة، مسألة الوعدة، وهذه صحيحة لا بأس بها في أصح قولي العلماء لما عرفت من الأسباب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7394/حكم-بيع-النقود-بالنقود-الى-اجل-والسلعة-والتورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23404.mp3","categories":["الربا والصرف","البيوع"]},{"id":9564,"question":"يسأل أيضاً ويقول: ما حكم بيع كمية من الذهب لشخص تعرفه، ثم يدفع لك بعض القيمة ويعتذر بأن بقيتها ليست معه وسيسددها بعد أيام؟","title":"حكم بيع الذهب بالذهب مع عدم التقابض","answer":"الجواب: لا يجوز بيع الذهب بنقود أخرى سواءً كانت فضة أو العملة الورقية إلا يداً بيد؛ لأن العملة الورقية قامت مقام النقود، فإذا باع عليه ذهباً أو فضة بأي عملة دولار أو جنيه استرليني أو دينار أردني أو عراقي أو سعودي أو غير ذلك، لا بد من التقابض، لقول النبي ﷺ: الذهب بالذهب رباً إلا هاء وهاء، واللفظ الآخر: الذهب بالفضة رباً إلا هاء وهاء.\nفلا بد من التقابض وإلا صار في ربا النسيئة.. وقع في ربا النسيئة، فإذا كانا من جنس واحد كالذهب بالذهب والفضة بالفضة والدولار بالدولار فلا بد أن يكونا متساويين ديناران بديناران عشرة بعشرة يداً بيد لا بد من القبض، فإن كانت عملتان مختلفتان فإن الواجب التقابض فقط، فإذا باع عشرة دولارات مثلاً بعشرين ريال سعودي أو بدينار عراقي أو أردني فلا بأس لكن يداً بيد، لا يتفرقان إلا وقد تقابضا. نعم.\nالمقدم: بارك الله فيكم، أيضاً ولو لم يحدد السعر، يعني: اشترى كمية من الذهب إلى أن يدفع ثمنها غداً و..\nالشيخ: ولو كان الكمية قطعة من الذهب.\nالمقدم: ولم يحدد سعرها؟\nالشيخ: ولم توزن ولم تعرف زنتها لا بد أن يقبض ثمنها في الحال إذا كان من العملة، أما لو اشترى الذهب بأرز بحنطة بقهوة بهيل إلى أجل معلوم لا بأس لأنه ليس بعملة، فلو قال: هذا الذهب المعروف الذي عندهم يعرفونه قطعة معروضة يعرفونها أو قد وزنوها قال: هي عليك بمائة صاع أو بمائة كيلو هيل، بمائة كيلو حنطة، بمائة كيلو رز إلى أجل معلوم لا بأس؛ لأن الجنس مختلف. نعم.. فليس من الربا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7740/حكم-بيع-الذهب-بالذهب-مع-عدم-التقابض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24712.mp3","categories":["الربا والصرف"]},{"id":9567,"question":"أخيراً يقول: ما الحكم إذا استدان شخص مالاً لمدة سنة أو سنتين ثم حل الدفع ولم يستطع، فقال لصاحب المال: قيدها علي بنفس الاتفاق السابق لمدة سنة أو سنتين قادمتين؟","title":"حكم إنظار المدين عند حلول الأجل مع زيادة الدين","answer":"الجواب: إذا كان أراد بهذا يعني بزيادة فلا يجوز؛ لأن الواجب إنظاره، فإذا كان مثل: حل عليه عشرة آلاف ريال، ولكن لم يستطع الدفع فقال: قيدها علي إلى سنتين أو أكثر بإحدى عشر ألف زيادة ألف أو ألفين، هذا ربا ما يجوز.\nالمقدم: يقول: بنفس المربح السابق، يعني بمربح آخر مثل المربح السابق.\nالشيخ: ما يجوز هذا لا، ما يجوز، أما إذا كان معنى قيدها علي: أمهلني، فلا بأس بهذا سواءً أمهله سنة وإلا أكثر وإلا أقل، هذا واجب لقول الله تعالى: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]، أما قيدها علي يعني: بزيادة بربح هذا ما.. هذا ربا الجاهلية فلا يجوز. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7741/حكم-انظار-المدين-عند-حلول-الاجل-مع-زيادة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24713.mp3","categories":["الربا والصرف"]},{"id":10650,"question":"هذا السائل لم يذكر الاسم في هذه الرسالة يقول: ما حكم أخذ نقود معدنية لغرض الاتصال بنقود ورقية، حيث أنني آخذ تسعة من النقود المعدنية بعشرة من الورقية بفائدة ريال واحد هل هذا حرام، علمًا بأن كثير من الناس يتعامل بهذا جزاكم الله خيرًا؟","title":"حكم صرف تسعة من النقود المعدنية بعشرة من الورقية","answer":"الجواب: فيه خلاف بين أهل العلم في العصر الحاضر والأفضل ترك ذلك، الأحوط للمؤمن أن يأخذ عشرة بعشرة، ومائة بمائة، هذا هو الأحوط، أما التحريم فيه نظر، لكن الأحوط للمؤمن ترك ذلك، لقوله ﷺ: دع ما يريبك إلى ما لا يريبك وقوله عليه الصلاة والسلام: من اتقى الشبهات فقد استبرأ لدينه وعرضه فإذا ترك ذلك وأخذ عشرة بعشرة مائة بمائة لأنها كلها ريال يكون هذا أحوط، نعم.","link":"https://binbaz.org.sa/fatwas/8827/حكم-صرف-تسعة-من-النقود-المعدنية-بعشرة-من-الورقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28512.mp3","categories":["الربا والصرف"]},{"id":11152,"question":"يقول السائل: إذا بعت الذهب بنقد هل يجوز ذلك؟ وإذا بعت الذهب بالذهب هل يجوز الزيادة عليه؟","title":"حكم بيع الذهب بالنقد والذهب بالذهب","answer":"الجواب:  إذا باع الذهب بالنقد بالفضة جاز يدًا بيد، إذا باع ذهبًا بفضة يدًا بيد فلا بأس، أما ذهب بذهب، أو فضة بفضة فلا يجوز إلا مثلًا بمثل، إذا كان ذهب بذهب، وفضة بفضة لابد من التماثل والتقابض شرطين، أن يكون هذا مثل هذا، دينار بدينار، درهم بدرهم، مع التقابض في المجلس، نعم.","link":"https://binbaz.org.sa/fatwas/9325/حكم-بيع-الذهب-بالنقد-والذهب-بالذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29014.mp3","categories":["الربا والصرف"]},{"id":11153,"question":"السؤال الأخير في رسالة المستمع يقول: ما هو الربا؟ واشرحوا لنا ذلك جزاكم الله خيرًا.","title":"حقيقة الربا وحكمه","answer":"الجواب:  الربا هو معاملة بين جنسين من غير قبض، أو من الجنس الواحد من غير تماثل ولا قبض، يقال له: ربا، إذا كان الجنسان من المكيل المطعوم، أو الموزون المطعوم، أو من الذهب والفضة، أو من العمل التي تقوم مقام الذهب والفضة، فإذا باع عملة بعملة مثلها زائدة هذا ربا، أو عام باع عملة بعملة غيرها لكن من غير تقابض يكون ربا، لابد من يد بيد، دولار بمائة سعودي يدًا بيد، دولار بجنيه عراقي يدًا بيد وهكذا. وهكذا إذا باع حنطة بحنطة متماثلة يدًا بيد هذا ليس بربا، فإذا باع حنطة بحنطة أكثر صار ربا، أو فضة بفضة أكثر ربا، أو ذهب بذهب أكثر ربا، لكن إن باع الفضة بالذهب متقابضًا فليس بربا في المجلس، أو باع الحنطة بالشعير تقابضا في المجلس ليس بربا. فالحاصل إذا كان جنس واحد لابد فيه من شرطين:  التماثل،  والتقابض في المجلس. وإلا فيكون ربًا. أما إذا كانا جنسين فلابد من التقابض، يكفي التقابض في المجلس، مثل: ذهب بالشعير، مثل: ذهب بفضة، مثل: شعير بتمر، تمر بملح بحنطة وما أشبه ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9326/حقيقة-الربا-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29015.mp3","categories":["الربا والصرف"]},{"id":11349,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات من الرياض، تقول: المرسلة (و. ع. م) أختنا لها عدد من القضايا:في إحداها تقول: اشترى لي والدي مجموعة من الذهب بهذه الطريقة، باع ذهبي القديم واشترى به ذهبًا جديدًا وزاد عليه مبلغًا من المال، فهل يعتبر هذا من الربا، وإذا كان كذلك فماذا يجب علي؟ هل أبيعه وأتصدق بثمنه، أم أبيعه وأتصدق وأقبض الثمن ثم أشتري به ذهبًا جديدًا؟ جزاكم الله خيرًا.","title":"حكم بيع الذهب بالذهب مع دفع المشتري الفرق","answer":"الجواب:  هذه المعاملة لا شك أنها ربا، وإذا كنتم تعلمون ذلك فردوا الذهب على صاحبه وخذوا ذهبكم ودراهمكم والبيع باطل، أما إذا كنتم لا تعلمون فالأمر واسع -إن شاء الله- لأجل الجهل، الأمر واسع والحمد لله ولا حرج في ذلك، وعلى العبد أن يستقيم في المستقبل ويحذر هذا الربا الذي وقع من أبيك جهلًا منه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9543/حكم-بيع-الذهب-بالذهب-مع-دفع-المشتري-الفرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37820.mp3","categories":["الربا والصرف"]},{"id":11410,"question":"تقول: عندنا في المدارس يطلبون على البنات مبلغًا يسيرًا من المال في حدود عشرة ريالات، وإذا جاء آخر العام يعطون البنات المبلغ، ومثله معه، فهل هذا جائز؟","title":"حكم المال يؤخذ من الطالب ويرد مضاعفًا نهاية العام","answer":"الجواب:  إن كان هذا لسلع يشترونها للتجارة في المدرسة، يجعلوا من يجمع الدراهم هذه، يبيع أشياء، يشتري أشياء، ويبيع أشياء على الطلبة، فجمعوا أرباحًا؛ فلا بأس، أما أن يعطي عشرة، ويأخذ عشرين في آخر الوقت؛ لا يجوز، هذا ربا، لكن، أما إذا كان لا، إنما لهم وكيل يشتري حاجات من شراب، ومثل غيره، مثل عطور، ومثل غيره، يجمع شيئًا من الربح؛ فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9589/حكم-المال-يوخذ-من-الطالب-ويرد-مضاعفا-نهاية-العام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38009.mp3","categories":["الربا والصرف","البيوع"]},{"id":11415,"question":"من الجمهورية العربية السورية رسالة بعث بها المستمع سيف العتيب وفلاح ....... الأخوان يسألان يقولان: هل يجوز التعامل بالنقد، مثال: أخذت من شخص ألف ليرة سورية بشرط أردها إليه خلال فترة محدودة بفائض خمسمائة ليرة، هل يجوز هذا، أو لا؟ الشيخ: أعد أعد.المقدم: هل يجوز التعامل بالنقد، مثال ذلك: أخذت من شخص ألف ليرة سورية بشرط أردها إليه خلال فترة محددة بفائض خمسمائة ليرة، وهل يوجد حديث، أو آية قرآنية تنص على ذلك، مع العلم بأن الشخص يقول ويراهن على ذلك بأنه توجد آية تنص على ذلك وتحلله، ويعلل ذلك بأن العلماء يخفون ذلك أحيانًا لأمر ما، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"اشتراط المقرض رد القرض بزيادة","answer":"الجواب: هذا عين الربا، هذا عين الربا، النبي ﷺ يقول: الذهب بالذهب مثلًا بمثل، والفضة بالفضة مثلًا بمثل، والبر بالبر مثلًا بمثل، والشعير بالشعير مثلًا بمثل، والتمر بالتمر مثلًا بمثل، فمن زاد أو استزاد فقد أربى فإذا أعطى عملة دولار بدولارات أكثر، أو ليرة بليرات أكثر، أو ريال سعودي بريالات أكثر؛ هذا عين الربا بنص السنة عنه، عليه الصلاة والسلام. والذي يقول: إن هناك آية تبيح ذلك كذاب، والعلماء ما يخفون ذلك، العلماء يبينون الحق -علماء السنة علماء الحق- وإذا كان يقصد قوله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282]، هذه ليس فيها حل الربا، هذه مجملة، فسرها النبي ﷺ فسرها بالنصوص. فالمراد إذا تداينوا بدين يعني: باع سلعة بدين، باع بيته بدين، باع له طعام بنقود دين، ما هو معناه باع ذهب بذهب دين هذا ما يجوز، المقصود الدين الجائز يبيعه أرضًا بثمن مؤجل، يبيع السيارة بثمن مؤجل، يبيعه برًا، وإلا شعيرًا بثمن مؤجل؛ لا بأس، هذا الدين، أما أن يبيع عملة بعملة مؤجلة؛ ما يجوز هذا، ولا برًا ببر مؤجل، ولا ذهبًا بفضة مؤجلة، ولا برًا بشعير مؤجل، بنص السنة عن النبي ﷺ. فالصرف والربا معروف والمعاملات الأخرى معروفة، نعم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9596/اشتراط-المقرض-رد-القرض-بزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38015.mp3","categories":["الربا والصرف"]},{"id":11501,"question":"أخ في الله يقول: الكرار (أ. ع) أخونا يقول: أرجو أن تتفضلوا بتوضيح الحلال من الحرام في بيع العملة بعملة أخرى.","title":"حكم بيع العملة بعملة أخرى","answer":"الجواب:  نعم، بيع عملة بعملة أخرى لا حرج، لكن يدًا بيد في المجلس، يبيع دراهم سعودية بدولار، أو بدنانير؛ لا بأس، لكن يدًا بيد، لقوله ﷺ: فإذا اختلفت هذه الأصناف؛ فبيعوا كيف شئتم إذا كان يدًا بيد قال ﷺ: الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح، مثلًا بمثل، سواءً بسواء، يدًا بيد، فإذا اختلفت هذه الأصناف؛ فبيعوا كيف شئتم إذا كان يدًا بيد. فإذا باع ذهبًا بفضة يدًا بيد، باع برًا بشعير يدًا بيد، ولو اختلف، باع تمرًا بأرز، ولو اختلف؛ لابد يدًا بيد، أو ملحًا يدًا بيد، باع دولارات بدراهم سعودية، بدنانير، بجنيه مصري، أو إسترليني يدًا بيد، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9679/حكم-بيع-العملة-بعملة-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38312.mp3","categories":["الربا والصرف"]},{"id":11593,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع من الإمارات العربية المتحدة -أيضاً- يقول: (أ. س. محمد) يسأل ويقول: حدثونا عن الربا كيف يكون، وأرجو توجيه نصيحة للمسلمين بشأنه؟ جزاكم الله خيرًا.","title":"التحذير من الربا وبيان أقسامه","answer":"الجواب:  الربا من أكبر الكبائر، وقد توعد الله عليه بالعقوبات العظيمة، قال -جل وعلا- في كتابه العظيم: الَّذِينَ يَأْكُلُونَ الرِّبَا لا يَقُومُونَيعني: من قبورهم إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ [البقرة:275] يعني: لا يقوم من قبره إلا كالمجنون، وهذه عقوبة -والعياذ بالله- خاصة لهذا المرابي، وقال -جل وعلا-: يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ [البقرة:276] توعد بمحق الربا، محق أموال الربا، ونزع بركتها، قال -جل وعلا-: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُوْلَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ [البقرة:275]، هذا وعيد عظيم، من عاد في الربا توعده الله بالنار، وهذا وعيد عظيم، يجب الحذر. وقال -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ [البقرة:278-279] فجعل الربا حربًا لله ولرسوله، وهذا وعيد عظيم، يدل على كبر الذنب، وعظمة الذنب. فالواجب الحذر من الربا بجميع أنواعه، وقد صح عن رسول الله ﷺ أنه لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال هم سواء، فالله حذر من الربا، وأخبر أن أهله في النار وتوعدهم بالنار، والرسول ﷺ كذلك لعنهم على خبث عملهم.  فالواجب على المسلم أن يتقي الله، وأن يحاسب نفسه في ذلك، وأن يحذر جميع أنواع الربا في جميع تصرفاته؛ لأن الربا من أكبر الكبائر كما بين الله -جل وعلا- في هذه الآيات التي سمعت، وفي قول النبي ﷺ: اجتنبوا السبع الموبقات يعني: المهلكات، قلنا: وما هن يا رسول الله؟! قال: الشرك بالله، والسحر، وقتل النفس التي حرم الله إلا بالحق، وأكل الربا جعله منها وأكل مال اليتيم، والتولي يوم الزحف، والمحصنات الغافلات المؤمنات فالمحصنة الغافلة المؤمنة رميها بالفاحشة من أعظم الجرائم، من أعظم الموبقات. فالمقصود: أن الربا من أقبح السيئات، ومن أقبح الكبائر .... من السبع المهلكات، نسأل الله العافية. وحقيقته أمران: أحدهما: ربا الفضل، والثاني: ربا النسيئة، فربا الفضل: كونه يبيع جنسًا بجنسه متفاضلًا، كالدرهم بدرهمين سعودي، دولار بدولارين، جنيه بجنيهين، هذا ربًا صريح، ربا الفضل يسمى ربا الفضل، وقد حرمه النبي ﷺ وشدد في ذلك. النوع الثاني: يسمى ربا النسيئة: وهو أن يبيع نوعًا من أموال الربا بنوع آخر نسيئة، فإن كان من جنسه؛ صار فيه ربا الفضل، وربا النسيئة جميعًا، كأن يبيع -مثلاً- مائة ريال سعودي بمائة وعشرة إلى أجل مثلًا، هذا ربا فضل، وربا نسيئة جميعًا، أما ربا النسيئة: فأن يبيع نوعًا من الربا بنوع آخر غير مقبوض في المجلس، يسمى ربا النسيئة، كأن يبيع دراهم بذهب، أو دولارات بريالات سعودية إلى أجل، هذا يقال له: ربا النسيئة، ولا يجوز بإجماع المسلمين. فالواجب الحذر من الربا بنوعيه: ربا الفضل وربا النسيئة جميعًا، والحذر من التحيل على ذلك، نسأل الله العافية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9786/التحذير-من-الربا-وبيان-اقسامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38712.mp3","categories":["الربا والصرف"]},{"id":11720,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أبها، باعث الرسالة المستمع عمر بن أحمد، الأخ عمر يقول في أحد أسئلته: أنا أعمل في محل، ويأتيني جاري في بعض الأحيان ويقول لي: اصرف لي خمسين ريالًا، وحينئذ لا يكون عندي غير الثلاثين مثلًا فأخبره، فيقول: خذ الخمسين، وأعطني الثلاثين، ويبقى لي عندك عشرون، هل هذا يجوز، أم لا؟ جزاكم الله خيرًا.","title":"حكم صرف العملة مع بقاء بعض المبلغ لوقت لاحق","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: هذا العمل لا يجوز؛ لأنه فيه قبض للبعض، وتأجيل للبعض، والصرف لابد يكون يدًا بيد، والطريقة السليمة أن يعطيه الخمسين أمانة عنده، ويأخذ الثلاثين قرضًا، ثم بعد ذلك يحاسبه عليها حتى يعطيه، يبيع عليه الخمسين، أو يرد عليه الثلاثين، إما يبيع عليه الخمسين، ويعطيه العشرين الباقية يدًا بيد، ويحاسبه على الثلاثين، أو يرجع إليه بالثلاثين ويأخذ الخمسين. المقصود.. هذا بيع ما يصلح إلا يدًا بيد، وثلاثون بخمسين ما يجوز، لكن تكون الخمسين أمانة والثلاثون يأخذها قرضًا، ولا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9903/حكم-صرف-العملة-مع-بقاء-بعض-المبلغ-لوقت-لاحق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42101.mp3","categories":["الربا والصرف"]},{"id":11886,"question":"يقول: ليس لي عمل ثابت، أو وظيفة في بلدي، وقد قامت الجهة التي نتبعها بعمل مشروع تكافل اجتماعي مفاده: أن يدفع العضو قسطًا سنويًا من المال، وعند بلوغ سن الستين يستحق صرف مبلغًا من المال أضعاف ما سدده بكثير، أو يصرف عند حدوث الوفاة للعضو المشترك، هل الاشتراك في مثل هذا الصندوق بهذا الوضع يعتبر من الحلال، أم هو غير جائز؟","title":"حكم المشاركة بأقساط مالية في مشروع التكافل وإرجاعه بزيادة","answer":"الجواب:  لا يصلح هذا؛ لأنه ربا، يعطيهم قسطًا، ويعطونه زيادة ........ القسط الذي يتصرفون فيه، هذا من جنس التأمين الذي يؤمن كذا؛ يعطى كذا، هم يتصرفون في القسط، يستفيدون منه، وعند مضي المدة يعطونه مقابل ذلك، نعم، ما يصلح هذا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10070/حكم-المشاركة-باقساط-مالية-في-مشروع-التكافل-وارجاعه-بزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42507.mp3","categories":["الربا والصرف"]},{"id":12158,"question":"تسأل سماحتكم عن حكم تحويل العملة، من عملة إلى أخرى، كالدينار مثلًا بالدولار، وما أشبه ذلك؟","title":"شروط تحويل العملة الورقية إلى عملة أخرى","answer":"الجواب: لا حرج، لكن يداً بيد، إذا أراد أنه يشتري دولارًا بريال سعودي يكون يدًا بيد، أو جنيهًا استرليني بعملة أخرى يدًا بيد، أو دينارًا أردنيًا، أو عراقيًا، أو سوريًا أو غيره، يشتريها بعملة أخرى يدًا بيد؛ لا بأس بذلك. المقدم: جزاكم الله خيرًا.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/10343/شروط-تحويل-العملة-الورقية-الى-عملة-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44108.mp3","categories":["الربا والصرف"]},{"id":12311,"question":"المستمع عبدالرحمن علي شلبي بعث يسأل ويقول: بعض الجهات تستثمر أموالها في الفضة والدولار بحيث تشتري الدولار بالريال الفضة، وقد تبيع الفضة بالدولار، وهذه العملية عملية قيدية لا غير، بحيث لا يرى البائع أو المشتري شيئًا من النقد، سواءً كان من الفضة، أو من الدولارات، ولا يتم التقابض بين الطرفين، فما مدى صحة هذا النوع من التعامل؟","title":"حكم بيع النقود بالنقود دون تقابض","answer":"الجواب:  إذا كان هذا التعامل ليس فيه قبض؛ فلا يصح التعامل، فإن المعاملات بالنقود لابد فيها من القبض، سواءً كان بالدولار، أو بالريال السعودي، أو بالدينار، أو بالجنيه الاسترليني، أو المصري، أو غير ذلك، فلابد أن يكون هناك تقابض ولو بالقيد، إذا كان عند الشخص له دنانير، أو دولارات، فباعها على زيد، أو عمرو بالقيد أو بالهاتف، وقال: هذه الدنانير التي عندك، أو الدولارات التي عندك، وهي كذا وكذا قد بعتها عليك بكذا وكذا، واقبض فقبض من نفسه؛ صار وكيلاً، قبض من نفسه هذا المال؛ فلا بأس، أما إذا كان ما جرى قبض؛ فإنه لا يصح؛ لأن الرسول -عليه الصلاة والسلام- قال يدًا بيد، الذهب بالذهب، والفضة بالفضة، والبر بالبر إلى آخره يدًا بيد مثلاً بمثل سواءً بسواء ثم قال: فإذا اختلفت هذه الأصناف؛ فبيعوا كيف شئتم؛ إذا كان يدًا بيد. فالدولار بالجنيه الاسترليني يدًا بيد، والدولار بالريال السعودي يدًا بيد، فإذا قال: بعتك هذه الدنانير، أو هذه الدولارات بمائة ألف ريال سعودي، وهو مجرد قيد، ما سلم له فلوسًا؛ فهذا ما يصح البيع، لابد من التقابض.  المقدم: لابد من التقابض، والتقابض إما أن يكون حسيًا، أو معنويًا؟  الشيخ: مجرد القيد ما يصير قبضًا، لابد أن يكون المال مقبوضًا لصاحب المال الأول، فإذا كان الشراء بالدولارات من زيد؛ فلابد أن يكون المقابل مسلمًا لزيد، سواءً كان عنده، موجود عنده يقول: اقبضوه من.. يقبض من عنده، أو يرسل إليه، أو يحوله على إنسان حتى يقبض منه، فإذا حصل التقابض؛ تم البيع، وإلا فلا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10511/حكم-بيع-النقود-بالنقود-دون-تقابض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45402.mp3","categories":["الربا والصرف"]},{"id":12423,"question":"المستمع أحمد مبارك مصطفى يقول: هل يجوز بيع العملة المعدنية بعملة ورقية بالفائدة، بمعنى أبيع تسعة ريالات معدنية بعشرة ورقية؟ جزاكم الله خيرًا.","title":"حكم بيع العملة الورقية بعملة معدنية بنقص","answer":"الجواب:  الأحوط مثلًا بمثل عشرة بعشرة، مائة بمائة، هذا هو الأحوط، بعض أهل العلم أجاز ذلك؛ لأن المادة مختلفة، ولكن الأقرب والأحوط ترك ذلك؛ لأنها كلها ريال، كلها عملة واحدة، ريال واحد. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10630/حكم-بيع-العملة-الورقية-بعملة-معدنية-بنقص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40218.mp3","categories":["الربا والصرف"]},{"id":12983,"question":"السائلة تقول سماحة الشيخ: أرجو أن تحدثونا عن الربا وما هو فقد خفي على البعض من الناس في تعاملهم في العصر الحاضر، وأيضًا المخرج لبيع وشراء الذهب حيث لا يوجد من يزن الذهب بالذهب؛ لأن القديم ربما ينكسر، أو لا يصلح للاستعمال، مأجورين؟","title":"من أنواع المعاملات الربوية","answer":"الجواب:  الرسول ﷺ وضح الربا وبينه، فإذا بيع الذهب بالذهب، أو الفضة بالفضة، أو المطعوم المكيل بالمطعوم المكيل كالرز والحنطة والتمر والملح وأشباه ذلك فلابد من شرطين: التماثل والتقابض وزنًا بوزن، مثلًا بمثل، يدًا بيد، في الذهب والفضة، وفي التمر والشعير، والذرة والحنطة والملح، ونحو ذلك، لابد كيلًا بكيل متساويًا، يدًا بيد في المجلس قبل التفرق، فإن فعل خلاف ذلك؛ فهو الربا، فإذا باع ذهبًا بذهب أرجح منه ربا، أو فضة بفضة أرجح ربا، أو باع صاعًا من التمر بصاع ومد، أو صاعين من التمر ربا، أو صاعًا من حنطة بصاعين من الحنطة ربا، أو صاعًا من الشعير بصاعين من الشعير ربا، أو صاعًا من الملح بصاعين من الملح ربا. لابد من التماثل إذا كان النوع واحدًا، صاعًا بصاع، صاعين بصاعين إذا كان نوعًا واحدًا؛ تمر تمر، حنطة حنطة، شعير شعير، ملح ملح، ذرة ذرة، أرز، لابد من التماثل والتقابض، صاعًا من الأرز من أي نوع بصاع مثله، سواء كيلًا بكيل، يدًا بيد؛ لا بأس، صاعًا من التمر بصاع من التمر، ولو اختلف النوع، صاعًا من التمر بصاع من التمر يدًا بيد، يعني: يتقابضا في المجلس لا بأس. هكذا جنيه بجنيه ذهب، ولو اختلفت السكة والعملة إذا كان وزنهما واحدًا؛ فلا بأس، إذا كان وزنهما واحدًا يدًا بيد تقابضا في المجلس؛ فلا بأس. أو سلعة من الذهب بسلعة من الذهب وزنهما واحد، وليس فيهما خلط ذهب محض مع ذهب محض وزنهما واحد وتقابضا في المجلس؛ فلا بأس، كما بيَّن النبي ﷺ. أما إذا اختلف الجنس؛ فلا بأس بالتفاضل، لكن يدًا بيد، مثل: جنيه بعشرين، درهم بأربعمائة درهمًا، مائة درهم، يدًا بيد؛ لا بأس، في المجلس قبضًا، مثل: صاع تمر بصاعين شعير، أو صاعين حنطة، أو صاعين ملحًا، أو صاعين ذرة يدًا بيد، لا بأس، ولو كان هذا أكثر من هذا؛ لأن الجنس مختلف، لكن لابد يقبض صاع تمر بصاعين من الرز يدًا بيد، صاع تمر بصاعين من الذرة يدًا بيد؛ لا بأس، صاع تمر بصاعين من الملح يدًا بيد؛ لا بأس. هكذا العمل الموجودة لما ترك الناس الذهب والفضة، وعملوا بالعمل الموجودة، الأوراق الموجودة مثل: الذهب والفضة، إذا باع دراهم سعودية بدراهم سعودية مثلًا بمثل، يدًا بيد، مثل: خمسمائة قطعة واحدة بخمسمائة من ذوات العشرة، أو ذوات المائة، يدًا بيد؛ فلا بأس يدًا بيد، قطعة من ذوات المائة الريال السعودي بمائة من ذوات الريال، أو من ذوات الخمسة، أو من ذوات العشرة، يدًا بيد؛ فلا بأس؛ لأنها متماثلة، ويدًا بيد، أو مائة دولار بمائة دولار، وإن اختلفت الأحجام مائة دولار بمائة دولار يدًا بيد؛ لا بأس. هكذا مائة دينار أردني بمائة دينار أردني، أو مائة جنيه مصري بمائة جنيه مصري، يدًا بيد، لا بأس. فإذا اختلفت؛ فلا بأس بالتفاضل، مثل: مائة ريال سعودي بخمسين دولار أمريكي، يدًا بيد؛ لأنها عملة مختلفة، أو مائة دولار أمريكي بمائتي جنيه مصري يدًا بيد لا بأس. المقصود: إذا اختلفت العملة؛ جاز التفاضل، لكن يدًا بيد، أما إن كانت العملة واحدة، ريال سعودي بريال سعودي، فلابد من أمرين: التماثل والتقابض في المجلس، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11200/من-انواع-المعاملات-الربوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50313.mp3","categories":["الربا والصرف"]},{"id":13080,"question":"ننتقل إلى رسالة بعث بها السائل (ع. ع. ع) من جمهورية مصر العربية يقول: ما حكم الشرع فيمن يبيع الهلل التسعة بعشرة من الريالات، ويعطي بالريال العاشر عصيرًا، أو أي شيء بريال فما حكم ذلك مأجورين؟","title":"حكم بيع الريالات المعدنية بريالات ورقية مع الزيادة","answer":"الجواب:  فيه خلاف بين علماء العصر، والأفضل عدم الزيادة، عشرة بعشرة، ومائة بمائة، وهكذا، لأنها كلها ريال، هذا معدن، وهذا ورق، فالأفضل عدم التفاضل، الأفضل عشرة بعشرة وعشرين بعشرين وثلاثين.. أحوط؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك بعض إخواننا من العلماء قالوا: لا بأس؛ لأن المعدن غير الورق، فلا بأس أن يتفاضل كما يباع الريال سابقًا ... مختلف، وكما يباع الريال بأشياء أخرى من الحديد لأنها مختلفة، فلا حرج، يعني: في الجملة، لكن كونه يحتاط لدينه، ويعمل بالاحتياط، ويأخذ الهلل من المعدن بالورق متساويًا عشرة بعشرة، ومائة بمائة، يكون هذا أحوط، وأبعد عن الشبهة؛ لقوله ﷺ: دع ما يريبك إلى ما لا يريبك. نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11297/حكم-بيع-الريالات-المعدنية-بريالات-ورقية-مع-الزيادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50712.mp3","categories":["الربا والصرف"]},{"id":13111,"question":"هذا السائل مقيم في جدة، يقول: لو حدث أن رجلًا كان يتعامل في الربا من بيع وشراء، ثم مات، وترك مبلغًا من المال من عمله في الربا، هل الأولاد يرثون، أو يتصدقون بهذا المال؟","title":"حكم وراثة المال المكتسب من الربا","answer":"الجواب:  يرثون المال ..... يرثونه، وإذا علموا يقينًا أن جزءًا من المال ربا؛ تصدقوا به، إذا علموا يقينًا أن ماله -مثلًا- عشرة آلاف، هذه رأس مال، ما هي بربا، وعرفوا أن ألفًا أو ألفين من الربا يتصدقون بها في وجوه الخير، نعم، وإذا جهلوا؛ فالمال كله لهم، إذا جهلوا كل المال لهم، وإذا عرفوا جزءًا من المال ربا، أو سرقة، أو ما أشبه ذلك تصدقوا به، وإن عرفوا صاحبها ردوه عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11328/حكم-وراثة-المال-المكتسب-من-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50818.mp3","categories":["الربا والصرف"]},{"id":13163,"question":"من الصومال مقديشو الأخت هناء صالح بعثت برسالة ضمنتها بعض الأسئلة، في أحد أسئلتها تقول: أرجو تعريفي ما معنى الربا؟","title":"تعريف الربا وبيان أنواعه","answer":"الجواب:  الربا في اللغة: الزيادة، ويقال: ربا المال: زاد، وربا الشجر: نما وزاد. وفي الشرع: هو الزيادة في أحد النوعين من المال على النوع الآخر، هذا إذا كانا من جنس واحد، كالذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير ونحو ذلك، إذا زاد أحدهما على الآخر هذا يقال له: ربًا شرعًا، ممنوع شرعًا، فليس للمسلم أن يبيع درهمًا بدرهمين، ولا دينارًا بدينارين، إذا كانت زنة الدينار واحد، فإن هذا ذهب بذهب أزيد، وفضة بفضة أزيد، والنبي ﷺ قال: الذهب بالذهب مثلًا بمثل، سواء بسواء، يدًا بيد، والفضة بالفضة مثلًا بمثل، سواء بسواء، يدًا بيد، والبر بالبر والشعير بالشعير، والتمر بالتمر، والملح بالملح، مثلًا بمثل، سواء بسواء يدًا بيد، فمن زاد، أو استزاد؛ فقد أربى. ويكون الربا أيضًا بغير زيادة، لكن بالتفرق قبل القبض، أو بالتأجيل، يسمى ربا أيضًا شرعًا، إذا باع جنسًا من المال بجنسه، ولم يتقابضا أو بجنس لا يباع به نسيئة ولم يتقابضا؛ سمي ربًا، وإن لم يكن فيه زيادة.  فلو باع درهمًا بدرهم نسيئة، أو تفرقا قبل القبض؛ يسمى ربا شرعًا، ولو ما فيه زيادة، أو باع دينارًا بدينار، لكن لم يتقابضا أو قال: إلى أجل سمي ربا أيضًا، ولو لم يكن فيه زيادة. وهكذا لو باع فضة بذهب، أو ذهبًا بفضة، مؤجلًا، أو حالًا، لكن لم يتقابضا؛ يسمى ربًا أيضًا، وهكذا لو باع برًا بشعير، أو تمرًا بشعير، أو تمرًا ببر، ولم يتقابضا؛ يسمى ربًا، أو إلى أجل يسمى ربًا، وبهذا يتضح للسائل معنى الربا في الشرع ربا الفضل، وربا النسيئة؛ لأنه نوعان عند أهل العلم: أحدهما: يسمى ربا الفضل، مثل درهم بدرهمين، ودينار بدينارين، مثل صاع من البر بصاع ونص من البر، هذا يسمى ربا الفضل. والنوع الثاني: ربا النسيئة: درهم بدرهم إلى أجل هذا نسيئة، صاع بر ببر، بصاع بر آخر، لكن نسيئة، هذا ربا نسيئة، أو فضة بذهب من دون قبض؛ يسمى ربا نسيئة، أو بر بشعير بغير قبض؛ يسمى ربا نسيئة، وهكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11418/تعريف-الربا-وبيان-انواعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_475/47504.mp3","categories":["الربا والصرف"]},{"id":13245,"question":"بعد ذلك ننتقل إلى رسالة عبدالله محمد من تنزانيا يقول: هل الربا -سماحة الشيخ- يكون في الذهب والفضة فقط، أم في جميع المعاملات، والمطعومات؛ لأن الربا كما قرأت في كتب الفقه لا يكون إلا في الذهب والفضة، أما النقود فلا، اشرحوا لنا ذلك بالتفصيل؟","title":"من صور التعامل بالربا","answer":"الجواب:  الربا يكون في الذهب والفضة، ويكون أيضًا في العُمل الأخرى، الدولار والدينار والجنيه المصري والجنيه.. الجنيه والفرنسي والجنيه الإنجليزي، وغير ذلك، جميع العُمل هذا هو الصواب؛ لأنها قامت مقام الذهب والفضة.  والمقصود: أنها ثمن يتعامل به الناس، فتعطى أحكام الثمنية، فلا يجوز بيع بعضها ببعض من غير قبض، يعني: عن غيبة يعني: عن تفرق من دون قبض نسيئة، بل لابد يكون يدًا بيد، فإذا باع الدولار بالريال السعودي، أو الدولار بالجنيه المصري، أو الدولار بالدينار العراقي، أو الأردني، فلابد من التقابض كالذهب والفضلة، يدًا بيد؛ لأن الحكم صار لهذه العمل بدلًا من الذهب والفضة. وهكذا إذا باع برًا بشعير، أو برًا بتمر، أو شعيرًا بتمر، لابد من التقابض؛ لقوله ﷺ: الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح، مثلًا بمثل، سواءً بسواء، يدًا بيد ثم قال ﷺ: فإذا اختلفت هذه الأصناف؛ فبيعوا كيف شئتم إذا كان يدًا بيد. فالمثل بالمثل يشرط فيه شرطان: التماثل، والقبض، ذهب بذهب، لابد من التماثل والقبض .. فضة بفضة لابد من التماثل والقبض .. دولار بدولار لابد من التماثل والقبض، ديناران بدينارين، أربعة بأربعة، عشرة في بعشرة.. بر ببر، لابد من المثل والتقابض، صاع بصاع، صاعين بصاعين مع التقابض، شعير بشعير كذلك، تمر بتمر كذلك، لابد من الأمرين: التماثل والتقابض. أما إذا اختلفت فضة بذهب؛ فإنه لا يشرع التماثل؛ لأن بينهما فرق، لكن القبض الفضة بذهب يدًا بيد، لابد من يد بيد، دولار بريال سعودي يدًا بيد، دولار بجنيه مصري يدًا بيد، دولار بدينار عراقي، أو أردني يدًا بيد، وهكذا. وقد درس هذا الموضوع مجلس هيئة كبار العلماء فيما مضى، وقرر أن هذا هو الواجب، وأن هذا هو الذي ينبغي، وأن هذه العمل تعطى أحكام الذهب والفضة؛ لأنها حلت محلها في البيع والشراء. نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11530/من-صور-التعامل-بالربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51311.mp3","categories":["الربا والصرف"]},{"id":14015,"question":"أخونا محمد من ليبيا يسأل أيضًا ويقول: هل يجوز الاتجار في العملة من أجل الربح، فمثلًا: لو قمت بتصريف ثلاثمائة دينار ليبي نحصل على ألف دولار، والألف الدولار في المصارف التونسية ثمانمائة دينار تونسي، وقمت بعد ذلك بتبديل ثمانمائة دينار تونسي مع ثمانمائة دينار ليبي فنكون بذلك قد ربحنا خمسمائة دينار ليبي، هل هذا حلال أم حرام؟","title":"حكم التجارة في العملات","answer":"الجواب: البيع والشراء في العمل جائزة لكن بشرط اليد باليد يعني: التقابض، فإذا باع عملة ليبية بعملة أمريكية أو مصرية أو غيرهما يدًا بيد فلا بأس كأن يشتري دولارات بعملة ليبية يدًا بيد ... يقبض ويسلم، أو اشترى عملة مصرية أو إنجليزية أو غيرهما بعملة ليبية أو غيرها يدًا بيد، أما إلى أجل ... أو من غير قبض فلا يجوز ربا فلا بد من التقابض في المجلس يدًا بيد وإلا يكون ربا. نعم.","link":"https://binbaz.org.sa/fatwas/12435/حكم-التجارة-في-العملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61105.mp3","categories":["الربا والصرف"]},{"id":14035,"question":"تسأل أختنا أيضًا وتقول: امرأة كانت تقرض الشخص ألف ريال على أن يردها ألف وثلاثمائة، وهي لا تعرف أن هذا ربا، فهل يلحقها شيء في ذلك؟ وماذا يجب عليها؟","title":"حكم من تعامل بالربا جهلًا","answer":"الجواب: هذا لاشك أنه ربا، والذي فعل ذلك قبل أن يعلم، لا شيء عليه، كما قال الله جل وعلا في كتابه العظيم: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ وَمَنْ عَادَ فَأُوْلَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ [البقرة:275]، فبين سبحانه أن من جاءه موعظة من ربه، يعني: عرف الحق ووعظ وذكر؛ فانتهى وتاب إلى الله؛ فلا شيء عليه، وَمَنْ عَادَ فَأُوْلَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ [البقرة:275]، هذا يبين لنا أن الواجب على من عرف الربا أن يحذره، وأن يتباعد عنه، وأن يتوب إلى الله من ذلك. وعلى المؤمن أن يسأل ويتفقه في دينه ويتعلم؛ حتى لا يقع فيما حرم الله عليه، يقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين، متفق على صحته، هذا يدلنا على أن الإنسان إذا تفقه في الدين وتبصر وتعلم؛ فهذا من الدلائل على أن الله أراد به خيرًا، أما إذا استمر في الجهالة والإعراض؛ فهذا من علامات أن الله أراد به شرًا ولا حول ولا قوة إلا بالله، وقد قال عليه الصلاة والسلام في الحديث الصحيح: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة.\nفالتعلم من أهم المهمات، والتفقه في الدين، وإذا تصدقت بالزائد احتياطًا؛ لأنك تساهلت في السؤال، وإذا صرفتيه في وجوه الخير فهو أحوط وأحسن، كما قال تعالى: وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة:279]، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12453/حكم-من-تعامل-بالربا-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60702.mp3","categories":["الربا والصرف"]},{"id":14054,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم ومحبكم في الله منذر (أ. أ) من ليبيا، الأخ منذر له جمع من الأسئلة، يسأل في سؤاله الأول فيقول: إذا كان الدينار الليبي يساوي تقريبًا ثلاثة دولارات، فما حكم من يقوم ببيع الدولار الواحد بدينار أو من يقوم ببيع الدينار الليبي بدينار تونسي، والصحيح أن الدينار الليبي يساوي دينارين تونسيين، نرجو إفادتنا في ذلك، حيث شاع مثل هذا العمل بين الناس ولم يكلفوا أنفسهم حتى مجرد التفكير فيما إذا كان هذا العمل جائز أو غير جائز، وجهونا ووجهوا الناس، جزاكم الله خيرًا.","title":"حكم بيع وشراء العملات","answer":"الجواب: العمل تعتبر أجناسًا، فإذا باع العملة الليبية بعملة تونسية أو أمريكية أو سعودية أو غير ذلك فلا بأس بشرط أن يكون ذلك يدًا بيد كما يبيع الذهب بالفضة يدًا بيد، فإذا باع الجنيه من الذهب بدراهم من الفضة يدًا بيد فلا بأس، فهكذا إذا باع عملة من العُمَل بعملة أخرى مثلها أو أكثر أو أقل إذا كان ذلك يدًا بيد كما يبيع الذهب بالفضة يدًا بيد.\nوالمقصود أن العُمَل تعتبر أجناسًا، فالعملة الليبية جنس والعملة التونسية جنس والعملة الأمريكية جنس وهكذا العملة الإنجليزية والفرنسية وأشباه ذلك، وقد درس مجلس هيئة كبار العلماء لدينا هذا الموضوع ورأى ما ذكرناه؛ رأى أن العُمَل أجناس، وهو الذي ينبغي الأخذ به؛ لأنها اعتبرت أثمانًا للمبيعات وقيمًا للمبيعات فحلت محل الذهب والفضة، فكل عملة قائمة برأسها وأصلية بنفسها، تعتبر جنسًا مستقلًا، فإذا بيع بعملة أخرى جاز ذلك يدًا بيد.  فلو باع دينارًا ليبيًا بدولارين أو ثلاثة دولارات أمريكية أو بجنيه إسترليني أو أقل أو أكثر فلا بأس بذلك لكن يدًا بيد يتقابضوا في المجلس، لا نسيئة ولا يتفرقون إلا بعد التقابض؛ لقول النبي ﷺ: الذهب بالذهب والفضة بالفضة والبر بالبر والشعير بالشعير والتمر بالتمر والملح بالملح مثلًا مثل سواءً بسواء يدًا بيد، فإذا اختلفت هذه الأصناف فبيعوا كيف شئتم إذا كان يدًا بيد. فقوله إذا اختلفت الأصناف مثل اختلاف العمل سواء، يباع بعضها ببعض لكن يدًا بيد كما يباع البر بالشعير ولو تكلف يدًا بيد صاعًا من بر بصاعين من شعير لا بأس لكن يدًا بيد، صاعًا من تمر بصاعين من شعير لا بأس لكن يدًا بيد، جنيه من الذهب بمائة درهم فضة بخمسين درهم بأكثر بأقل يدًا بيد لا بأس، فهكذا دولار أمريكي بدولارين من عملة أخرى أو دينار ليبي بدولارين من العملة الأمريكية أو بغيرها يدًا بيد لا بأس بذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12482/حكم-بيع-وشراء-العملات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61302.mp3","categories":["الربا والصرف"]},{"id":14147,"question":"السائلة التي رمزت لاسمها (مريم . أ. أ) تقول: بأنها إنسانة تبيع وتشتري في الذهب، وفي أحد الأيام باعت مجموعة من الحلي على الصائغ ثم اشترت منه حليًا وزاد على القيمة الأولى، فما الحكم يا سماحة الشيخ وما معنى الحديث: الذهب بالذهب مثلاً بمثل سواء بسواء وهل على الذهب زكاة بالتفصيل؟ جزاكم الله خيراً.","title":"حكم بيع الذهب بالذهب وحكم الزكاة فيه","answer":"الجواب: يجب عليها أن تأخذ قيمته ثم تشتري ذهبًا آخر حتى لا يكون وسيلة إلى بيع الذهب بالذهب أو بيع الفضة بالفضة، فإذا باعت عليه الذهب تقبض الثمن ثم تشتري ما شاءت منه، إن شرت ذهب يدًا بيد، إن شرت فضة بذهب يدًا بيد، إن شرت ذهبًا بذهب يكون متماثلًا، سواء بسواء وزنًا بوزن.\nالمقصود أنها إذا باعت عليه الذهب تقبض الثمن حتى لا يكون حيلة، تقبض الثمن ثم تشتري منه ما شاءت. نعم.\nالمقدم: تقول سماحة الشيخ: ما معنى: الذهب بالذهب مثلًا بمثل؟\nالشيخ: معناه أنه سواء بسواء، يعني: مثقال بمثقال، مثقالان بمثقالين، ثلاثة بثلاثة، جنيه بجنيه، جنيهين بجنيهين على السواء، وزنًا بوزن سواء بسواء يدًا بيد مثلما قال ﷺ: الذهب بالذهب مثلًا بمثل سواء بسواء وزنًا بوزن فليس لها الزيادة ولا غيرها، لابد أن يكونا متماثلين، وزنًا بوزن، سواء كان حلي أو نقود لابد وزنًا بوزن، والفضة كذلك، أما إذا اختلفا ذهب بفضة فلا حرج، يدًا بيد.\nالمقدم: والجواب يا سماحة الشيخ عبد العزيز في زكاة الذهب؟\nالشيخ: نعم؟\nالمقدم: هل تجب فيه الزكاة -الذهب-؟\nالشيخ: نعم، تجب زكاة الذهب والفضة، تجب الزكاة فيهما إذا حال عليهما الحول وبلغا النصاب، كانا نقودًا أو حليًا أو غير ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/12588/حكم-بيع-الذهب-بالذهب-وحكم-الزكاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54612.mp3","categories":["الربا والصرف","زكاة النقدين"]},{"id":14821,"question":"رسالة وصلت إلى البرنامج من المستمع عبدالرحمن موسى من ليبيا، رسالته مطولة، ملخص ما فيها في هذا السؤال يقول:هل الفائدة المصرفية تعتبر ربا أم لا؟ وإذا كانت ربا ما حكم من اقترض قرضًا بفائدة؟نرجو التوجيه، جزاكم الله خيرًا.","title":"حكم الفائدة المصرفية والقرض بفائدة","answer":"الجواب: نعم الفائدة المصرفية ربا، فإذا اقترض مائة بمائة وخمسة أو بمائة وسبعة أو أكثر أو أقل فهذا ربا، وهكذا ما هو أكثر من ذلك، ولا يجوز تسليم هذه الفائدة، بل على الفاعل التوبة والرجوع إلى الله والإنابة والندم، وعدم العودة، وليس للمقرض إلا رأس ماله، كما قال تعالى: وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة:279] ولا يجوز تعاطي هذه المعاملة. ولا ينبغي للعاقل أن يغتر بالناس الذين يفعلونها مع كثرتهم، فإن الحق أحق بالاتباع، والله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59] وقد قال -عليه الصلاة والسلام-: الذهب بالذهب مثلًا بمثل، سواء بسواء، يدًا بيد، والفضة بالفضة يدًا بيد، مثلًا بمثل، سواء بسواء الحديث. وهذه المعاملات، وهذه العمل الجديدة من الدولارات والدنانير وغيرها من العمل الورقية كلها لها حكم الذهب والفضة، فلا يجوز أن يباع بعضها ببعضٍ مفاضلةً، وهي من جنس واحد ولا نسيئة، بل لا بد أن يكون ذلك يدًا بيدٍ، مع التماثل إن كانت من جنس واحد كالدينار بالدينار والدولار بالدولار.  أما إن كانت من أجناس كأن يبيع دولارًا بدراهم سعودية، أو بدنانير أردنية، أو عراقية، أو شبه ذلك، فلا بأس، لكن يدًا بيد بالتقابض، وأما دينار بدينارين أو دولار بدولارين أو مائة دولار بمائة وخمسة أو مائة ريال سعودي بمائة وخمسة؛ لأجل الفائدة هذا ما يجوز، هذا هو الربا، هذا عين الربا، نسأل الله السلامة، نعم. المقدم: نسأل الله السلامة، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13320/حكم-الفاىدة-المصرفية-والقرض-بفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64304.mp3","categories":["الربا والصرف"]},{"id":14826,"question":"سماحة الشيخ، الذين يفرقون بين الاقتراض بفائدة في عمل استثماري أو عمل استهلاكي، هل لهم وجه أو لا؟","title":"حكم القرض بفائدة في عمل استثماري أو استهلاكي","answer":"الجواب: كل هذا غلط، هذا من كيسهم، ليس له وجه، الرسول ﷺ حرم ذلك مطلقًا، سواء كان القرض للاستثمار أو للاستهلاك لحاجته، كله محرم، والرسول ﷺ لم يفرق بين هذا وهذا -عليه الصلاة والسلام-، بل عمم وأطلق، فدل ذلك على أنه لا يجوز مطلقًا، سواء كان القصد من ذلك الاستهلاك أم كان القصد الاستثمار والمتاجرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13321/حكم-القرض-بفاىدة-في-عمل-استثماري-او-استهلاكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64305.mp3","categories":["الربا والصرف"]},{"id":14838,"question":"هل يجوز لي التصدق بالفائدة التي تضاف إلى المبلغ الذي أحفظه في البنك؟ علمًا بأنها ستضاف إليه، سواء أبيت أم رضيت، مثلًا أتبرع بها للمركز الإسلامي أو للمجاهدين أو لغير ذلك.","title":"كيفية التصرف في الفائدة التي يضيفها البنك","answer":"الجواب: لا حرج، لا تأكلها، ولكن تدفعها في وجوه الخير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13340/كيفية-التصرف-في-الفاىدة-التي-يضيفها-البنك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63820.mp3","categories":["الربا والصرف"]},{"id":15303,"question":"سؤاله الآخر يقول: هناك إنسان يقرض الناس بفائدة، فمثلًا: يعطي رجلًا مائة دينار لمدة ستة أشهر، فيأخذ على هذا المبلغ عشرين دينارًا مثلًا زيادة، فما حكم الإسلام في هذا؟","title":"حكم القرض بفائدة","answer":"الجواب: هذه المعاملة ربوية من أعمال الربا، حكمها أنها معاملة باطلة ربوية، الله -جل وعلا- حرم الربا ورسوله ﷺ لعن آكل الربا وموكله وكاتبه وشاهديه وقال: هم سواء والله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا[البقرة:278] فالمعنى: أن الربا يجب أن يترك، ثم بيَّن  أنه حرب لله وحرب للرسول -عليه الصلاة والسلام-.  فعلى المؤمن أن يحذر أنواع الربا كلها؛ ولهذا قال: فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ[البقرة:279] يعني: فاعلموا بحرب من الله والرسول، وأنكم محاربون لله ورسوله في تعاطي الربا، فالفوائد في القروض ربا، فإذا أقرضه عشرة دنانير حتى يعطيه بعد ذلك اثني عشر أو ثلاثة عشر هذا من الربا، نعم.","link":"https://binbaz.org.sa/fatwas/13811/حكم-القرض-بفاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68202.mp3","categories":["الربا والصرف"]},{"id":17247,"question":"هذه الأخت أم عاصم يا سماحة الشيخ تقول: سؤالي أولًا أقول: ما هو الربا؟ والفقرة الثانية تقول في المعاملات: هل يعتبر هذا ربا: تبادل كيلو غرام من الطحين بكيلو غرام من العجينة؟","title":"تعريف الربا، وحكم تبادل الطحين بالعجين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالربا من أقبح السيئات، ومن أقبح الكبائر، حرمه الله -جل وعلا- وقال: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275] وقال سبحانه في كتابه العظيم: الَّذِينَ يَأْكُلُونَ الرِّبَا لا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ [البقرة:275] فالواجب الحذر منه، وقال -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ [البقرة:278-279]. والربا: هو بيع الشيء من النقود بمثله؛ كالذهب بالذهب، أو الفضة بالفضة، أو البر بالبر، أو الشعير بالشعير، أو التمر بالتمر، أو الملح بالملح، أو الذرة بالذرة، هذا ربا إذا باع مثله متفاضلًا، كأن يبيع صاعًا من التمر بصاعين من التمر، أو الجنيه بجنيهين، أو درهمًا بدرهمين، يعني: متفاضلة؛ هذا ربًا بإجماع المسلمين، أو يبيعه بمثله، لكن من غير تقابض، يقول: درهم بدرهم، لكن لا يتقابضان، ما يقبضه في المجلس، فلابد من التقابض في المجلس، وأن يكونا متماثلين إذا كان من جنس واحد، عشرة بعشرة.. مائة بمائة، وأن يتقابضا في المجلس، صاعًا بصاع.. صاع تمر بصاع تمر في المجلس يتقابضان، صاعين بصاعين.  أما إذا كانا من جنسين؛ ذهب بفضة، فلا بأس بالتفاضل، لكن يكون يدًا بيد، جنيهًا بصرف من الفضة، أو بغير الفضة من العمل الأخرى يدًا بيد، يأخذ جنيهًا بدولار أو غيره، يأخذ بنوع آخر من العملة في المجلس يدًا بيد، دولارات بدراهم، أو بدنانير لا بأس أن تكون متفاضلة إذا كانت من أجناس، لكن يدًا بيد، أو صاع تمر بصاعين من الحنطة يدًا بيد في المجلس، أو صاعًا من الذرة بصاعين من التمر، يدًا بيد لا بأس وإن تفاضلا، فكيلو من البر بكيلو من البر العجين لا بأس به يدًا بيد. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16079/تعريف-الربا-وحكم-تبادل-الطحين-بالعجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59201.mp3","categories":["الربا والصرف"]},{"id":17489,"question":"أحسن الله إليكم، سماحة الشيخ: لعلكم تبينون أنواع الربا المحرم جزاكم الله خيرًا؟","title":"ما هي أنواع الربا؟","answer":"الجواب: الربا معروف واضح في كتب أهل العلم، في كتب الحديث وكتب الفقه في باب الربا، ورد فيه أحاديث كثيرة، فالواجب على المؤمن يتفقه في ذلك ويسأل أهل العلم، وإن كان طالب علم يراجع كتب أهل العلم حتى يعرف حقيقة الربا وما يجري فيه الربا، وما لا يجري فيه الربا؛ لأن هذا يحتاج إلى بحث فيه طويل، ولكن المؤمن يعتني بهذا بسؤال أهل العلم. ومما ورد في ذلك قوله ﷺ: الذهب بالذهب مثلًا بمثل، والفضة بالفضة مثلًا بمثل، والبر بالبر مثلًا بمثل، والتمر بالتمر مثلًا بمثل، والشعير بالشعير مثلًا بمثل، والملح بالملح مثلًا بمثل فمن زاد أو استزاد فقد أربى، هذا من أنواع الربا كونه يأخذ جنيه بجنيهين، درهم بدرهمين هذا ربا صريح، كذلك يأخذ صاع بر بصاعين، أو صاع رز بصاعين، أو صاع تمر بصاعين، أو صاع ملح بصاعين.. أو نحو ذلك يعني: بأكثر، هذا كله لا يجوز، لا نقدًا ولا نسيئة. أما إذا أراد أن يشتري ذهبًا بفضة فلا بأس، يدًا بيد، يشتريه بعشرين ريالًا بمائة ريال، يدًا بيد لا بأس؛ لأنهما جنسان أو يشتري صاع رز بصاعين حنطة، أو صاعين رز بصاع حنطة.. أو ما أشبه ذلك؛ لأن الجنس مختلف، إذا اختلفت هذه الأجناس فلا بأس يدًا بيد، أو يشتري صاع ملح بصاعين رز أو بنصف صاع حنطة.. أو ما أشبه ذلك، لا بأس إذا اختلف الجنس يقول ﷺ: إذا اختلفت هذه الأجناس فبيعوا كيف شئتم إذا كان يدًا بيد يعني: يقبض في الحال، فإذا أخذ صاع رز بصاع ونصف من الحنطة أو صاع حنطة بصاعين من الشعير يدًا بيد، أو صاع ملح بنصف صاع من الحنطة يدًا بيد لا بأس، أو جنيه من الذهب بمائة ريال من الفضة يدًا بيد أو بمائة دولار أو بأقل أو بأكثر يدًا بيد، وتقابض في المجلس فلا بأس.\nالمقدم: ما هو ربا النسيئة يا سماحة الشيخ؟\nالشيخ: بيع الربوي بالربوي نسيئة، هذا النسيئة، يبيع ذهب بفضة نسيئة، يبيع تمر بشعير نسيئة، يبيع تمر بحنطة نسيئة، هذا ربا النسيئة، يعني: عدم التقابض في المجلس.\nالمقدم: وربا الفضل؟\nالشيخ: ربا الفضل: الريال بريالين، والجنيه بجنيهين، هذا ربا الفضل، صاع حنطة بصاعين، صاع رز بصاعين، صاع تمر بصاعين، جنس واحد يصير هذا أكثر من هذا.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16401/ما-هي-انواع-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77320.mp3","categories":["الربا والصرف"]},{"id":18161,"question":"أعطيت أخي في مصر مبلغًا من المال، وقلت له: دع هذا المبلغ في جهة للاستثمار، فأخذ المبلغ ووضعه في جهة ربوية، وحينئذٍ كان له أرباح، كيف تنصحونني تجاه تلك الأرباح؟ جزاكم الله خيرًا.","title":"حكم أخذ الفوائد الربوية لمن لم يتعمدها","answer":"الجواب: تلك الأرباح تصرف في بعض المشاريع الخيرية، وليس لكم إلا رأس المال، وعليه التوبة من ذلك على أخيك التوبة إلى الله من ذلك وعدم العود، والأرباح التي قبضتم من طريق الربا تصرف في بعض المشاريع الخيرية مثل الصدقة على الفقراء، مثل قضاء دين إنسان معسر، مثل إصلاح دورات مياه للمساجد، أو إصلاح بعض الطرق، أو حاجة بعض المدارس، أو ما أشبه ذلك، من المشاريع الخيرية التي تصرف فيها هذه الأموال التي ليس لها مالك شرعي، بل هي من جنس الأموال الضائعة والرهون المجهولة أهلها ونحو ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17229/حكم-اخذ-الفواىد-الربوية-لمن-لم-يتعمدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_855/nour_85502.mp3","categories":["الربا والصرف"]},{"id":18487,"question":"هل يجوز بيع الهلل -مثلًا- تشتري ألف ريال من الهلل بألف ريال، ثم تبيع تسع هلل بعشرة ريالات، هل هذا العمل حلال؟","title":"حكم بيع تسعة ريالات من الهلل بعشرة من الورق","answer":"الجواب: الأحوط التماثل، هذا هو الأحوط، فيه خلاف، والأحوط التماثل، وإن فعل فلا حرج إن شاء الله، لكن الأحوط هو التماثل، عشرة بعشرة، مائة بمائة، ثلاثين بثلاثين، من الورق والهلل جميعًا؛ لأنها كلها تسمى دراهم عملة، هذه ورق وهذه هلل، فإذا ساوى بينهما يكون أحوط، ريال ورق بريال هلل أو عشرة ريال هلل بعشرة ريال ورق، كل هذا أحوط وأحسن خروجًا من الخلاف في هذا. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17585/حكم-بيع-تسعة-ريالات-من-الهلل-بعشرة-من-الورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78525.mp3","categories":["الربا والصرف"]},{"id":18527,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، وسبق أن عرضنا جزءًا من أسئلتها، وهي الأخت أم محمد بنت معلي، أختنا تسأل عن قضية تعاني منها والدتها، وهي أنها تتقاضى من مال أبيها الذي يتعامل بالربا، وتسأل عن الحكم، لو تكرمتم شيخ عبد العزيز.","title":"حكم أخذ المرأة من مال أبيها إذا كان ربا","answer":"الجواب: إذا كانت تعلم أن ما تأخذه من مال الربا لا يجوز لها ذلك، أما إذا كان له أموال مختلطة، ولا تدري عما حصل في يدها هل هو من الربا أو غيره؟ فلا حرج.  والتورع عن ذلك أولى إذا لم يترتب عليه مفسدة ولا عقوق، وأما إذا علمت أن هذا المال من نفس الربا فلا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/17637/حكم-اخذ-المراة-من-مال-ابيها-اذا-كان-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87010.mp3","categories":["الربا والصرف"]},{"id":18536,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، وسبق أن عرضنا جزءًا من أسئلتها، وهي الأخت أم محمد بنت معلي، أختنا تسأل عن قضية تعاني منها والدتها، وهي أنها تتقاضى من مال أبيها الذي يتعامل بالربا، وتسأل عن الحكم، لو تكرمتم شيخ عبد العزيز.","title":"حكم أخذ المرأة من مال أبيها إذا كان ربا","answer":"الجواب: إذا كانت تعلم أن ما تأخذه من مال الربا لا يجوز لها ذلك، أما إذا كان له أموال مختلطة، ولا تدري عما حصل في يدها هل هو من الربا أو غيره؟ فلا حرج.  والتورع عن ذلك أولى إذا لم يترتب عليه مفسدة ولا عقوق، وأما إذا علمت أن هذا المال من نفس الربا فلا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/17637/حكم-اخذ-المراة-من-مال-ابيها-اذا-كان-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87010.mp3","categories":["الربا والصرف"]},{"id":19065,"question":"سماحة الشيخ هذا سائل يقول: ما معنى \"كل قرض جر نفعًا فهو ربا\"؟","title":"معنى قول: (كل قرض جر نفعًا فهو ربا)","answer":"الجواب: كل قرض يجر عليك نفعًا إذا أقرضت زيد ألف ريال وأعطاك كسوة، أو أهدى إليك فاكهة، أو ما أشبه ذلك، هذا من الربا، أو أسكنك في البيت بدون أجرة، أو أعطاك السيارة تستعملها بدون أجرة، هذا جر ربا هذا من الربا؛ لأن ما أعطاك إلا من أجل القرض. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18272/معنى-قول-كل-قرض-جر-نفعا-فهو-ربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88329.mp3","categories":["الربا والصرف","زكاة النقدين","قضايا المرأة","شروح الحديث"]},{"id":19453,"question":"رسالة وصلت إلى البرنامج من شرورة باعثها مستمع من هناك يقول: أخوكم (فرج م. المري) أخونا يقول: أنا رجل أحب علماء المسلمين، وأحب فعل الخير، وهذا من فضل ربي والحمد لله، ولكن عندما تزوجت كنت في أشد الحاجة إلى المال من أجل أن أكمل الذي في حاجته، فذهبت إلى أحد الإخوان وطلبت منه سلف دين، وقد وافق ولكن بشرط أن آخذ منه خمسة آلاف ريال وأردها له بعد ستة أشهر سبعة آلاف وخمسمائة ريال، يعني: بزيادة ألفين وخمسمائة ريال، ولحاجتي الماسة أخذت هذا المبلغ وأنا كاره، ولقد سددت المبلغ، أي: أعدته بعد ستة أشهر على حسب الشرط وفي خاطري شيء من الحرج، فهل علي ذنب؛ لأنني أخشى أن أكون قد أخذت بالربا، أرجو إفتائي؟ جزاكم الله خيرًا.","title":"حكم الزيادة في القرض","answer":"الجواب: لا شك أن هذه المعاملة معاملة ربوية، وحرام، ومنكر عليك، وعلى صاحبك، فالواجب عليكما التوبة إلى الله  والندم على ما مضى، والعزم أن لا تعودا إلى ذلك، والواجب على صاحبك أن يرد عليك المبلغ الزائد ألفين وخمسمائة؛ لأنها لا تحل له بل هي ربا، فالواجب عليه أن يردها إليك إلا أن تسمح عنها، وتبيحه بها؛ لأنها معاملة ربوية ليس له أخذ هذه الزيادة، ويقول النبي ﷺ: الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح مثلاً بمثل، سواءً بسواء، يدًا بيد، فمن زاد أو استزاد فقد أربى وهذه العمل قد أقيمت مقام الذهب والفضة. فليس له أن يأخذ الزيادة، فليس له أن يبيع عشرة باثنا عشر، أو يقرض عشرة باثنا عشر، أو بثلاثة عشر، أو بأكثر كل هذا لا يجوز؛ لأنه من الربا، فأنت عليك التوبة، وهو عليه التوبة، والندم على ما مضى والعزم أن لا تعودا في ذلك، وعليه أن يرد إليك ما زاد على الخمسة؛ لأنها أخذت بغير حق، لكن إن أبحته بها وسامحته بها معروفاً منك فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18711/حكم-الزيادة-في-القرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94407.mp3","categories":["الربا والصرف"]},{"id":19691,"question":"من أسئلة هذا السائل يقول: يا سماحة الشيخ، ما هو بيع العينة، وما حكمه؟","title":"تعريف بيع العينة وحكمه","answer":"الجواب: بيع العينة ربا، أن تبيع سلعة على إنسان بثمن مؤجل، ثم تشتريها منه بنقد هذه العينة، تبيع عليه مثلًا سيارة بستين ألف أقساط، ثم تبيعها عليه بنقد، تبيعها عليه بأربعين نقدًا يعطيك إياه. فالمعنى أنك أخذت أربعين بستين ربا حيلة، السيارة هنا جعلت حيلة، هذه هي العينة، أن تبيع سلعة بأجل، ثم تأخذها ممن اشتراها منك بنقد، تبيعها عليه بنقد، يعني: يعطيك نقدًا ويرد السلعة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/19001/تعريف-بيع-العينة-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95037.mp3","categories":["الربا والصرف","البيوع"]},{"id":19700,"question":"ما تقول في الشخص الذي يعمل بأحد البنوك، ويتقاضى راتبًا، هل هذا الراتب حلالٌ أم حرامٌ؟ وإذا قلتُم بأنه حرامٌ لأن البنوك ربوية، وليس لهذا الشخص عملٌ آخر في الوقت، فهل يترك عمله أو يستمر حتى يُلاقي عملًا آخر؟ أفتونا جزاكم الله خيرًا.","title":"حكم الراتب من البنك الربوي","answer":"الجواب: قد صدرت منا ومن اللجنة الدائمة فتاوى متعددة في تحريم هذا، وأنه لا يجوز أن يبقى في البنوك، ولا يحل له العمل فيها؛ لأنه إعانة لهم على الإثم والعدوان، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ [المائدة:2]، والرسول ﷺ قال: لعن الله آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء. فلا يجوز العمل في البنوك؛ لأنه عونٌ لهم على المحرم، ولو ما وجد وظيفةً: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ينفصل ويُبادر ولو ما وجد عملًا، يلتمس عملًا بعد الانفصال، والله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2- 3]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، وليس الرزق منوطًا بالحرام، الرزق مُيسَّر من طريق الحلال، فعليه أن يتَّقي الله، وأن يبتعد عن الحرام، والله سبحانه سوف يُسهّل له أمره إذا صدق في التوبة.","link":"https://binbaz.org.sa/fatwas/20576/حكم-الراتب-من-البنك-الربوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0530%D9%81%D8%AA%D8%A7%D9%88%D9%89%20%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D8%B6%D8%B1%D8%A7%D8%AA%20%D9%84%D9%84%D8%B4%D9%8A%D8%AE%20%D8%B9%D8%A8%D8%AF%D8%A7%D9%84%D8%B9%D8%B2%D9%8A%D8%B2%20%D8%A8%D9%86%20%D8%A8%D8%A7%D8%B2%20%D8%B1%D8%AD%D9%85%D9%87%20%D8%A7%D9%84%D9%84%D9%87.mp3","categories":["الربا والصرف"]}]
